window.VNR_DATA = {"questions":[{"id":"1","question":"Đại biểu của tổ chức cộng sản nào không tham dự Hội nghị thành lập Đảng đầu năm 1930?","qHighlight":["hông"],"options":[{"key":"A","text":"Đông Dương cộng sản liên đoàn","hl":[]},{"key":"B","text":"An Nam cộng sản Đảng","hl":[]},{"key":"C","text":"Đông Dương cộng sản Đảng","hl":[]},{"key":"D","text":"Quốc tế cộng sản","hl":[]}],"answer":["A"],"note":""},{"id":"2","question":"Chủ đề của Đại hội đại biểu toàn quốc lần thứ XIII của Đảng Cộng sản Việt Nam là? (Lựa chọn phương án đúng nhất).","qHighlight":[],"options":[{"key":"A","text":"Tăng cường chỉnh đốn Đảng và hệ thống chính trị trong sạch vững mạnh, khơi dậy khát vọng phát triển đất nước, phát huy ý chí, sức mạnh đại đoàn kết toàn dân tộc kết hợp sức mạnh thời đại, tiếp tục đẩy mạnh toàn diện, đồng bộ công cuộc đổi mới, xây dựng và bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa, giữ vững môi trường hòa bình, ổn định, phấn đấu đến giữa thế kỷ XXI nước ta trở thành nước phát triển theo định hướng xã hội chủ nghĩa.","hl":[]},{"key":"B","text":"Tăng cường xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh; khơi dậy ý chí và quyết tâm phát triển đất nước, phát huy sức mạnh đại đoàn kết toàn dân tộc kết hợp với sức mạnh thời đại;....phấn đấu để đến giữa thế kỷ 21, nước ta trở thành một nước phát triển, theo định hướng xã hội chủ nghĩa.","hl":[]},{"key":"C","text":"Tiếp tục đẩy mạnh toàn diện, đồng bộ công cuộc đổi","hl":[]}],"answer":["B"],"note":""},{"id":"3","question":"Hồ Chí Minh đọc bản Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin trên báo nào?","qHighlight":[],"options":[{"key":"A","text":"Thợ thuyền","hl":[]},{"key":"B","text":"Tình cảnh công nhân Anh","hl":[]},{"key":"C","text":"Nhân đạo","hl":[]},{"key":"D","text":"Người cùng khổ","hl":[]}],"answer":["C"],"note":""},{"id":"4","question":"Một trong những nội dung kinh nghiệm của Đảng về lãnh đạo kháng chiến chống thực dân Pháp và can thiệp của Mỹ đó là?","qHighlight":[],"options":[{"key":"A","text":"Đẩy mạnh phát triển cuộc kháng chiến về mọi mặt.","hl":[]},{"key":"B","text":"Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc.","hl":[]},{"key":"C","text":"Đề ra đường lối đúng đắn, sáng tạo, phù hợp với thực tiễn lịch sử của cuộc kháng chiến ngay từ những ngày đầu.","hl":[]},{"key":"D","text":"Kết hợp đấu tranh quân sự và ngoại giao, kết thúc thắng lợi cuộc kháng chiến","hl":[]}],"answer":["C"],"note":""},{"id":"5","question":"Đâu là nhận định đúng khi đề cập đến Đại hội lần thứ IV của Đảng trong các nhận định sau đây?","qHighlight":[],"options":[{"key":"A","text":"Là Đại hội toàn thắng của sự nghiệp giải phóng dân tộc, thống nhất Tổ quốc (1976)","hl":["thống nhất Tổ quốc (1976)"]},{"key":"B","text":"Đại hội khẳng định và xác định đường lối đưa miền Bắc tiến lên chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Đại hội đã nhìn thẳng vào sự thật, đánh giá đúng sự thật, nói rõ sự thật","hl":[]},{"key":"D","text":"Là Đại hội đổi mới toàn diện, đưa đất nước thoát khỏi khủng hoảng kinh tế - xã hội","hl":[]}],"answer":["A"],"note":""},{"id":"6","question":"Nghị quyết số 03-NQ/TW tại Hội nghị Trung ương 5 khóa VIII (7/1998) được coi như:","qHighlight":["số 03-NQ/TW"],"options":[{"key":"A","text":"Tuyên ngôn văn hóa của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa","hl":["văn hóa"]},{"key":"B","text":"Tuyên ngôn văn nghệ của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa","hl":[]},{"key":"C","text":"Tuyên ngôn nghệ thuật của Đảng trong thời kỳ thực hiện công nghiệp hóa, hiện đại hóa","hl":[]},{"key":"D","text":"Tuyên ngôn văn hóa văn nghệ của Đảng trong thời kỳ toàn cầu hóa","hl":[]}],"answer":["A"],"note":""},{"id":"7","question":"Trung Quốc cho quân đội chiếm đảo Gạc Ma và các bãi cạn Châu Viên, Chữ Thập, Tư Nghĩa ở quần đảo Trường Sa của Việt Nam vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"Tháng 3/1988.","hl":[]},{"key":"B","text":"Tháng 3/1986.","hl":[]},{"key":"C","text":"Tháng 3/1987.","hl":[]},{"key":"D","text":"Tháng 2/1979.","hl":[]}],"answer":["A"],"note":""},{"id":"8","question":"Đại hội lần thứ V của Đảng đã khẳng định: \"Trong khi không một phút lơi lỏng nhiệm vụ củng cố quốc phòng, bảo vệ Tổ quốc, Đảng ta và nhân dân phải đặt lên hàng đầu...\". Từ nào còn thiếu trong nhận định trên?","qHighlight":[],"options":[{"key":"A","text":"Nhiệm vụ xây dựng chủ nghĩa xã hội","hl":[]},{"key":"B","text":"Mục tiêu của cách mạng Việt Nam","hl":[]},{"key":"C","text":"Vấn đề cơ bản của cách mạng Việt Nam","hl":[]},{"key":"D","text":"Vấn đề cơ bản khi xây dựng chủ nghĩa xã hội","hl":[]}],"answer":["A"],"note":""},{"id":"9","question":"Sau Hiệp định Giơnevơ (7/1954) cách mạng Việt Nam có những thuận lợi gì?","qHighlight":[],"options":[{"key":"A","text":"Hệ thống chủ nghĩa xã hội lớn mạnh.","hl":[]},{"key":"B","text":"Phong trào giải phóng dân tộc trên thế giới lên cao.","hl":[]},{"key":"C","text":"Miền Bắc được hoàn toàn giải phóng, làm hậu phương lớn cho cả nước kháng chiến.","hl":[]},{"key":"D","text":"Mỹ âm mưu bá chủ toàn cầu","hl":[]}],"answer":["C"],"note":""},{"id":"10","question":"Nhiệm vụ chiến lược của cách mạng được Đại hội Đảng toàn quốc lần thứ III đề ra là gì?","qHighlight":[],"options":[{"key":"A","text":"Tiến hành cách mạng XHCN ở miền Bắc, giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước.","hl":[]},{"key":"B","text":"Tiến hành cách mạng XHCN ở miền Bắc","hl":[]},{"key":"C","text":"Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ","hl":[]},{"key":"D","text":"Xây dựng chủ nghĩa xã hội trên cả nước","hl":[]}],"answer":["A"],"note":""},{"id":"11","question":"Phấn đấu đến giữa thế kỷ XXI, nước ta trở thành nước phát triển theo định hướng xã hội chủ nghĩa. Được đề cập trong Đại hội lần thứ mấy của Đảng Cộng sản Việt Nam?","qHighlight":["kỷ XXI,"],"options":[{"key":"A","text":"Đại hội Đảng lần thứ XIII.","hl":[]},{"key":"B","text":"Đại hội Đảng lần thứ XII.","hl":[]},{"key":"C","text":"Đại hội Đảng lần thứ XI.","hl":[]},{"key":"D","text":"Đại hội Đảng lần thứ X.","hl":[]}],"answer":["A"],"note":""},{"id":"12","question":"Chiến lược phát triển khoa học và công nghệ, giáo dục và đào tạo đã được đề ra từ năm 1996 nhằm:","qHighlight":[],"options":[{"key":"A","text":"Thúc đẩy mạnh mẽ sự nghiệp công nghiệp hóa, hiện đại hóa đất nước.","hl":[]},{"key":"B","text":"Thúc đẩy mạnh mẽ sự nghiệp công nghiệp hóa đất nước.","hl":[]},{"key":"C","text":"Thúc đẩy mạnh mẽ sự nghiệp phát triển kinh tế đất nước","hl":[]},{"key":"D","text":"Thúc đẩy mạnh mẽ sự nghiệp giáo dục","hl":[]}],"answer":["A"],"note":""},{"id":"13","question":"Vì sao Mỹ buộc phải tuyên bố ngừng hẳn ném bom, bắn phá miền Bắc lần thứ nhất?","qHighlight":[],"options":[{"key":"A","text":"Thất bại trong chiến lược \"Chiến tranh cục bộ\" ở miền Nam","hl":[]},{"key":"B","text":"Thất bại nặng nề trong chiến tranh phá hoại miền Bắc","hl":[]},{"key":"C","text":"Thất bại trong chiến lược \"Chiến tranh đặc biệt\" ở miền Nam","hl":[]},{"key":"D","text":"Nhân dân thế giới lên án","hl":[]}],"answer":["A"],"note":""},{"id":"14","question":"Chế độ cai trị của thực dân Pháp đối với nhân dân Việt Nam cuối thế kỷ XIX đầu thế kỷ XX là chế độ nào?","qHighlight":[],"options":[{"key":"A","text":"Dân chủ","hl":[]},{"key":"B","text":"Dân chủ cộng hòa","hl":[]},{"key":"C","text":"Thuộc địa nửa phong kiến","hl":[]},{"key":"D","text":"Cộng hòa đại nghị","hl":[]}],"answer":["C"],"note":""},{"id":"15","question":"Cuối năm 1974, đầu năm 1975, Bộ Chính trị đã đề ra mấy kế hoạch khi hạ quyết tâm giải phóng miền Nam trong hai năm 1975-1976?","qHighlight":[],"options":[{"key":"A","text":"1","hl":[]},{"key":"B","text":"2","hl":[]},{"key":"C","text":"3","hl":[]},{"key":"D","text":"4","hl":[]}],"answer":["B"],"note":""},{"id":"22","question":"Trong cuộc xâm lược Việt Nam từ 1858 đến 1945, thực dân Pháp đã tiến hành mấy cuộc khai thác thuộc địa?","qHighlight":[],"options":[{"key":"A","text":"1","hl":[]},{"key":"B","text":"2","hl":[]},{"key":"C","text":"3","hl":[]},{"key":"D","text":"4","hl":[]}],"answer":["B"],"note":""},{"id":"16","question":"Ngày 2/9/1945, quân Pháp trắng trợn gây hấn cho nổ súng vào những người tham gia míttinh mừng ngày độc lập ở đâu?","qHighlight":[],"options":[{"key":"A","text":"Sài Gòn - Chợ Lớn","hl":[]},{"key":"B","text":"Hà Nội.","hl":[]},{"key":"C","text":"Khu căn cứ cách mạng.","hl":[]},{"key":"D","text":"An toàn khu","hl":[]}],"answer":["A"],"note":""},{"id":"17","question":"Ngày 2/9/1945 gắn với sự kiện lịch sử nào?","qHighlight":[],"options":[{"key":"A","text":"Pháp xâm lược nước ta lần 2","hl":[]},{"key":"B","text":"Ngày Nam Bộ kháng chiến","hl":[]},{"key":"C","text":"Chủ tịch Hồ Chí Minh đọc tuyên ngôn độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa","hl":["đọc tuyên ngôn độc"]},{"key":"D","text":"Ngày toàn quốc kháng chiến chống thực dân Pháp xâm lược","hl":[]}],"answer":["C"],"note":""},{"id":"18","question":"\"Chiến tranh có thể kéo dài 5 năm, 10 năm, 20 năm hoặc lâu hơn nữa. Hà Nội, Hải Phòng và một số thành phố, xí nghiệp có thể bị tàn phá, song người Việt Nam quyết không sợ. Không có gì quý hơn độc lập, tự do\". Khẳng định trên của Chủ tịch Hồ Chí Minh được viết trong tác phẩm nào?","qHighlight":[],"options":[{"key":"A","text":"Lời kêu gọi","hl":[]},{"key":"B","text":"Đường cách mệnh","hl":[]},{"key":"C","text":"Tuyên ngôn độc lập","hl":[]},{"key":"D","text":"Di chúc","hl":[]}],"answer":["A"],"note":""},{"id":"19","question":"Cách mạng tháng Tám năm 1945 là cuộc cách mạng gì?","qHighlight":[],"options":[{"key":"A","text":"Tư sản","hl":[]},{"key":"B","text":"Xã hội chủ nghĩa","hl":[]},{"key":"C","text":"Giải phóng dân tộc","hl":[]},{"key":"D","text":"Ruộng đất","hl":[]}],"answer":["C"],"note":""},{"id":"20","question":"Động lực cách mạng trong Cương lĩnh chính trị đầu tiên của Đảng ta xác định bao gồm những lực lượng nào?","qHighlight":[],"options":[{"key":"A","text":"Giai cấp công nhân","hl":["công nhân"]},{"key":"B","text":"Giai cấp tư sản mại bản","hl":[]},{"key":"C","text":"Giai cấp tư sản dân tộc","hl":[]},{"key":"D","text":"Giai cấp nông dân","hl":["nông dân"]}],"answer":["A","D"],"note":""},{"id":"21","question":"Chiến dịch Điện Biên Phủ bắt đầu vào ngày nào và kết thúc vào ngày nào?","qHighlight":[],"options":[{"key":"A","text":"Bắt đầu 13/3/1954, kết thúc 7/5/1954","hl":[]},{"key":"B","text":"Bắt đầu 1/4/1954, kết thúc 2/5/1954","hl":[]},{"key":"C","text":"Bắt đầu 15/3/1954, kết thúc 25/5/1954","hl":[]},{"key":"D","text":"Bắt đầu 2/3/1954, kết thúc 10/5/1954","hl":[]}],"answer":["A"],"note":""},{"id":"23","question":"Các cuộc khai thác thuộc địa của thực dân Pháp đã làm xuất hiện ở Việt Nam những giai cấp, tầng lớp mới nào?","qHighlight":[],"options":[{"key":"A","text":"Địa chủ phong kiến, nông dân, công nhân","hl":[]},{"key":"B","text":"Nông dân, công nhân, tiểu tư sản","hl":[]},{"key":"C","text":"Công nhân, tiểu tư sản, tư sản dân tộc","hl":[]},{"key":"D","text":"Tiểu tư sản, tư sản dân tộc, tiểu địa chủ","hl":[]}],"answer":["C"],"note":""},{"id":"24","question":"Hội nghị Trung ương 13 (1/1967) chủ trương mở mặt trận nào để tiến công địch?","qHighlight":[],"options":[{"key":"A","text":"Mặt trận chính trị","hl":[]},{"key":"B","text":"Mặt trận quân sự","hl":[]},{"key":"C","text":"Mặt trận binh vận","hl":[]},{"key":"D","text":"Mặt trận ngoại giao","hl":[]}],"answer":["D"],"note":""},{"id":"25","question":"Quốc dân Đại hội Tân Trào được triệu tập bởi:","qHighlight":[],"options":[{"key":"A","text":"Quốc tế Cộng sản","hl":[]},{"key":"B","text":"Đảng Cộng sản Đông Dương","hl":[]},{"key":"C","text":"Lãnh tụ Hồ Chí Minh","hl":[]},{"key":"D","text":"Tổng bộ Việt Minh","hl":[]}],"answer":["D"],"note":""},{"id":"26","question":"Tính chất toàn diện trong cuộc kháng chiến chống Pháp được hiểu là:","qHighlight":["toàn diện"],"options":[{"key":"A","text":"Kháng chiến trên mọi lĩnh vực kinh tế, quân sự, chính trị, văn hóa, giáo dục","hl":["vực kinh tế, quân sự, chính trị, văn hóa, giáo dục"]},{"key":"B","text":"Tất cả mọi người dân đều tham gia kháng chiến","hl":[]},{"key":"C","text":"Kháng chiến lâu dài","hl":[]},{"key":"D","text":"Phải dựa vào sức mình","hl":[]}],"answer":["A"],"note":""},{"id":"27","question":"Việt Nam chính thức thiết lập quan hệ ngoại giao với Mỹ vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"1990","hl":[]},{"key":"B","text":"1994","hl":[]},{"key":"C","text":"1995","hl":[]},{"key":"D","text":"2000","hl":[]}],"answer":["C"],"note":""},{"id":"28","question":"Điểm khác nhau giữa Luận cương chính trị tháng 10/1930 với Cương lĩnh chính trị đầu tiên (2/1930) của Đảng là:","qHighlight":[],"options":[{"key":"A","text":"Đường lối quốc tế của cách mạng giải phóng dân tộc","hl":[]},{"key":"B","text":"Đường lối tập hợp lực lượng bên trong của cách mạng","hl":[]},{"key":"C","text":"Phương pháp tiến hành cách mạng","hl":[]},{"key":"D","text":"Không có điểm khác nhau giữa 2 văn kiện","hl":[]}],"answer":["B"],"note":""},{"id":"29","question":"\"Cuộc cách mạng Đông Dương hiện tại không phải là cuộc cách mạng tư sản dân quyền, cuộc cách mạng phải giải quyết hai vấn đề phản đề và điền địa nữa, mà là cuộc cách mạng chỉ phải giải quyết một vấn đề cần kíp \"dân tộc giải phóng\"\". Chủ trương trên của Đảng được khẳng định tại Hội nghị nào?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị Ban Chấp hành Trung ương tháng 11/1939","hl":[]},{"key":"B","text":"Hội nghị Cán bộ Trung ương tháng 11/1940","hl":[]},{"key":"C","text":"Hội nghị Ban Chấp hành Trung ương tháng 5/1941","hl":[]},{"key":"D","text":"Hội nghị Ban Thường vụ Trung ương tháng 3/1945","hl":[]}],"answer":["C"],"note":""},{"id":"30","question":"Luận cương chính trị của Đảng Cộng sản Đông Dương tháng 10/1930 xác định:","qHighlight":[],"options":[{"key":"A","text":"Mâu thuẫn giai cấp diễn ra gay gắt ở Việt Nam","hl":[]},{"key":"B","text":"Mâu thuẫn dân tộc là chủ yếu","hl":[]},{"key":"C","text":"Nhiệm vụ giải phóng dân tộc được đặt lên hàng đầu","hl":[]},{"key":"D","text":"Liên minh dân tộc và giai cấp được thiết lập rộng rãi","hl":[]}],"answer":["A"],"note":""},{"id":"31","question":"Tuyến vận tải chiến lược Trường Sơn - đường mòn Hồ Chí Minh trên bộ chi viện miền Nam đánh Mỹ hình thành vào năm:","qHighlight":[],"options":[{"key":"A","text":"1958","hl":[]},{"key":"B","text":"1959","hl":[]},{"key":"C","text":"1960","hl":[]},{"key":"D","text":"1961","hl":[]}],"answer":["B"],"note":""},{"id":"32","question":"Đâu không phải là điều kiện tạo nên thời cơ cách mạng chín muồi của Tổng khởi nghĩa tháng Tám năm 1945 ở Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"Phát xít Nhật đảo chính lật đổ Pháp ở Đông Dương","hl":[]},{"key":"B","text":"Đảng và quần chúng nhân dân đã sẵn sàng hành động","hl":[]},{"key":"C","text":"Lực lượng trung gian đã ngả hẳn về phía cách mạng","hl":["gả hẳn"]},{"key":"D","text":"Phát xít Nhật đầu hàng quân Đồng minh không điều kiện","hl":[]}],"answer":["C"],"note":""},{"id":"33","question":"Đại hội lần thứ III của Đảng (1960) xác định nhiệm vụ trung tâm trong suốt thời kỳ quá độ lên chủ nghĩa xã hội ở Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Cách mạng văn hóa tư tưởng","hl":[]},{"key":"B","text":"Công nghiệp hóa xã hội chủ nghĩa","hl":[]},{"key":"C","text":"Cải tạo xã hôi chủ nghĩa đối với nông nghiệp, thủ công nghiệp","hl":[]},{"key":"D","text":"Phát triển kinh tế quốc doanh","hl":[]}],"answer":["B"],"note":""},{"id":"34","question":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội (bổ sung, phát triển năm 2011) đã bổ sung đặc trưng của xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng. Điểm bổ sung đó là:","qHighlight":[],"options":[{"key":"A","text":"Có nền văn hóa tiên tiến, đậm đà bản sắc dân tộc","hl":[]},{"key":"B","text":"Do nhân dân làm chủ","hl":[]},{"key":"C","text":"Dân giàu, nước mạnh, dân chủ, công bằng, văn minh","hl":[]},{"key":"D","text":"Có nền kinh tế phát triển cao dựa trên lực lượng sản xuất hiện đại và quan hệ sản xuất tiến bộ, phù hợp","hl":[]}],"answer":["C"],"note":""},{"id":"35","question":"Hội nghị Trung ương VI khóa XII Ban hành Nghị quyết số 20-NQ/TW ngày 25/10/2017 về:","qHighlight":[],"options":[{"key":"A","text":"Công tác dân số trong tình hình mới","hl":[]},{"key":"B","text":"Xây dựng văn hóa trong tình hình mới","hl":[]},{"key":"C","text":"Hội nhập trong tình hình mới","hl":[]},{"key":"D","text":"Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới","hl":[]}],"answer":["D"],"note":""},{"id":"36","question":"Năm 1929, Hội Việt Nam Cách mạng Thanh niên phân hóa thành:","qHighlight":[],"options":[{"key":"A","text":"An Nam Cộng sản Đảng","hl":[]},{"key":"B","text":"Đông Dương Cộng sản Đảng","hl":["Đông Dương Cộng sản Đảng đông duoeng"]},{"key":"C","text":"Đông Dương Cộng sản Liên đoàn","hl":[]},{"key":"D","text":"Đảng Cộng sản Việt Nam","hl":[]}],"answer":["A","B"],"note":""},{"id":"37","question":"Đâu là hạn chế của Đảng khi đề ra đường lối cách mạng xã hội chủ nghĩa tại Đại hội lần thứ III (9/1960)?","qHighlight":[],"options":[{"key":"A","text":"Chưa hoàn chỉnh đường lối chiến lược chung của cách mạng Việt Nam","hl":[]},{"key":"B","text":"Chưa đề ra chiến lược cách mạng riêng ở 2 miền","hl":[]},{"key":"C","text":"Chưa có dự kiến về chặng đường đầu tiên của thời kỳ quá độ lên chủ nghĩa xã hội","hl":[]},{"key":"D","text":"Nhận thức về con đường đi lên chủ nghĩa xã hội còn giản đơn","hl":[]}],"answer":["D"],"note":""},{"id":"38","question":"Lãnh tụ Nguyễn Ái Quốc đã đề cập những vấn đề cơ bản của một cương lĩnh chính trị, qua đó chuẩn bị về tư tường chính trị cho việc thành lập Đảng thông qua tác phẩm nào?","qHighlight":[],"options":[{"key":"A","text":"Đường Kách Mệnh","hl":[]},{"key":"B","text":"Bản án chế độ thực dân Pháp","hl":[]},{"key":"C","text":"Đông Dương","hl":[]},{"key":"D","text":"Điều lệ vắn tắt, Chương trình tóm tắt của Đảng","hl":[]}],"answer":["A"],"note":""},{"id":"39","question":"Hội nghị Trung ương nào của Đảng đề ra nghị quyết mở đường cho sự bùng nổ của phong trào Đồng Khởi ở miền Nam đầu năm 1960?","qHighlight":["Đồng Khởi"],"options":[{"key":"A","text":"Hội nghị Trung ương lần thứ 12 (3/1957)","hl":[]},{"key":"B","text":"Hội nghị Trung ương lần thứ 13 (12/1957)","hl":[]},{"key":"C","text":"Hội nghị Trung ương lần thứ 14 (11/1958)","hl":[]},{"key":"D","text":"Hội nghị Trung ương lần thứ 15 (1/1959)","hl":[]}],"answer":["D"],"note":""},{"id":"40","question":"Hội nghị Trung ương 5 khóa XII (5/2017) ban hành nghị quyết về phát triển kinh tế tư nhân, trong đó xác định:","qHighlight":[],"options":[{"key":"A","text":"Kinh tế tư nhân là một động lực quan trọng để phát triển kinh tế","hl":["nhân là một động lực quan trọng để phát triển kinh tế"]},{"key":"B","text":"Kinh tế tư nhân giữ vai trò chủ đạo của nền kinh tế","hl":[]},{"key":"C","text":"Kinh tế tư nhân là trụ cột của nền kinh tế","hl":[]},{"key":"D","text":"Kinh tế tư nhân giữ vai trò quyết định trong phát triển kinh tế","hl":[]}],"answer":["A"],"note":""},{"id":"41","question":"Đại hội lần thứ mấy của Đảng đã lần đầu tiên khẳng định một bài học trong quá trình đổi mới đất nước là phải \"lấy lợi ích quốc gia, dân tộc làm mục tiêu cao nhất\"?","qHighlight":["lấy lợi ích quốc gia, dân tộc"],"options":[{"key":"A","text":"Đại hội X (2006)","hl":[]},{"key":"B","text":"Đại hội XI (2011)","hl":[]},{"key":"C","text":"Đại hội XII (2016)","hl":[]},{"key":"D","text":"Đại hội XIII (2021)","hl":[]}],"answer":["C"],"note":""},{"id":"42","question":"Xây dựng, chỉnh đốn Đảng được Đại hội X (2006) xác định là:","qHighlight":[],"options":[{"key":"A","text":"Nhiệm vụ trung tâm","hl":[]},{"key":"B","text":"Nhiệm vụ then chốt","hl":[]},{"key":"C","text":"Nhiệm vụ hàng đầu","hl":[]},{"key":"D","text":"Nhiệm vụ đặc biệt quan trọng","hl":[]}],"answer":["B"],"note":""},{"id":"43","question":"Nội dung chủ yếu của đấu tranh giai cấp trong thời kỳ Đổi mới được Đảng Cộng sản Việt Nam xác định là:","qHighlight":[],"options":[{"key":"A","text":"Lật đổ giai cấp địa chủ phong kiến","hl":[]},{"key":"B","text":"Xóa bỏ giai cấp tư sản","hl":[]},{"key":"C","text":"Thực hiện thắng lợi sự nghiệp công nghiệp hóa, hiện đại hóa theo định hướng xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Không còn đấu tranh giai cấp","hl":[]}],"answer":["C"],"note":""},{"id":"44","question":"Phiên họp đầu tiên của Chính phủ Lâm thời Việt Nam Dân chủ Cộng hòa ngày 3/9/1945 xác định mấy nhiệm vụ lớn trước mắt của chính quyền cách mạng?","qHighlight":[],"options":[{"key":"A","text":"2","hl":[]},{"key":"B","text":"3","hl":[]},{"key":"C","text":"4","hl":[]},{"key":"D","text":"5","hl":[]}],"answer":["B"],"note":""},{"id":"45","question":"Trong 5 yếu tố chính để tăng trưởng kinh tế, yếu tố nào giữ vai trò quyết định?","qHighlight":[],"options":[{"key":"A","text":"Vốn, Khoa học - công nghệ","hl":[]},{"key":"B","text":"Con người","hl":[]},{"key":"C","text":"Cơ cấu kinh tế","hl":[]},{"key":"D","text":"Thể chế chính trị và quản lý nhà nước","hl":[]}],"answer":["B"],"note":"Mẹo nhớ: Trong 5 yếu tố tăng trưởng kinh tế, CON NGƯỜI giữ vai trò quyết định"},{"id":"46","question":"Đại hội VI của Đảng (1986) đã bầu ai làm Tổng Bí thư?","qHighlight":[],"options":[{"key":"A","text":"Trường Chinh","hl":[]},{"key":"B","text":"Phạm Văn Đồng","hl":[]},{"key":"C","text":"Nguyễn Văn Linh","hl":[]},{"key":"D","text":"Đỗ Mười","hl":[]}],"answer":["C"],"note":""},{"id":"47","question":"Ai là người ban hành mệnh lệnh \"thần tốc, thần tốc hơn nữa, táo bạo, táo bạo hơn nữa, tranh thủ từng phút, từng giờ, xốc tới mặt trận, giải phóng miền Nam. Quyết chiến và toàn thắng\"?","qHighlight":[],"options":[{"key":"A","text":"Võ Nguyên Giáp","hl":[]},{"key":"B","text":"Văn Tiến Dũng","hl":[]},{"key":"C","text":"Trần Văn Trà","hl":[]},{"key":"D","text":"Hoàng Văn Thái","hl":[]}],"answer":["A"],"note":""},{"id":"48","question":"Đại hội nào của Đảng lần đầu tiên đề ra hai nhiệm vụ chiến lược của cách mạng Việt Nam là xây dựng thành công chủ nghĩa xã hội và bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa?","qHighlight":["Việt Nam xã hội chủ nghĩa"],"options":[{"key":"A","text":"Đại hội IV (1976)","hl":[]},{"key":"B","text":"Đại hội V (1982)","hl":[]},{"key":"C","text":"Đại hội VI (1986)","hl":[]},{"key":"D","text":"Đại hội VII (1991)","hl":[]}],"answer":["B"],"note":""},{"id":"49","question":"Đại hội Đảng lần thứ IV (12/1976) đã nêu lên mấy đặc điểm lớn của cách mạng Việt Nam trong giai đoạn mới?","qHighlight":[],"options":[{"key":"A","text":"2","hl":[]},{"key":"B","text":"3","hl":[]},{"key":"C","text":"4","hl":[]},{"key":"D","text":"5","hl":[]}],"answer":["B"],"note":""},{"id":"50","question":"\"Trong lúc này nếu không giải quyết được vấn đề dân tộc giải phóng, không đòi được độc lập tự do cho toàn thể dân tộc, thì chẳng những toàn thể quốc gia dân tộc còn chịu mãi kiếp ngựa trâu mà quyền lợi của bộ phận, giai cấp đến vạn năm cũng không đòi lại được\". Luận điểm trên được đưa ra tại Hội nghị nào của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị Ban Chấp hành Trung ương tháng 11/1939","hl":[]},{"key":"B","text":"Hội nghị Cán bộ Trung ương tháng 11/1940","hl":[]},{"key":"C","text":"Hội nghị Ban Chấp hành Trung ương tháng 5/1941","hl":["Chấp hành Trung ương tháng 5/1941"]},{"key":"D","text":"Hội nghị Ban Thường vụ Trung ương tháng 3/1945","hl":[]}],"answer":["C"],"note":""},{"id":"51","question":"Động lực của công nghiệp hóa, hiện đại hóa trong thời kỳ Đồi môi được đưa ra tại Đại hội VIII của Đảng (1996) là:","qHighlight":[],"options":[{"key":"A","text":"Giáo dục và đào tạo","hl":[]},{"key":"B","text":"Khoa học và công nghệ","hl":[]},{"key":"C","text":"Quốc phòng an ninh","hl":[]},{"key":"D","text":"Văn hóa xã hội","hl":[]}],"answer":["B"],"note":""},{"id":"52","question":"Đường lối đối ngoại \"Việt Nam muốn là bạn với tất cả các nước trong cộng đồng thế giới, phấn đấu vì hòa bình, độc lập và phát triển\" được Đảng đề ra tại Đại hội lần thứ mấy?","qHighlight":["Việt Nam muốn là bạn với"],"options":[{"key":"A","text":"Đại hội VI (1986)","hl":[]},{"key":"B","text":"Đại hội VII (1991)","hl":[]},{"key":"C","text":"Đại hội VIII (1996)","hl":[]},{"key":"D","text":"Đại hội IX (2001)","hl":[]}],"answer":["B"],"note":"Mẹo nhớ: Đại hội VII (1991) = \"muốn là bạn\" (khác ĐH IX = \"sẵn sàng là bạn, là đối tác tin cậy\")"},{"id":"53","question":"Đại hội Đảng lần thứ IV (12/1976) đã bầu ai làm Tổng Bí thư?","qHighlight":[],"options":[{"key":"A","text":"Tôn Đức Thắng","hl":[]},{"key":"B","text":"Trường Chinh","hl":[]},{"key":"C","text":"Phạm Văn Đồng","hl":[]},{"key":"D","text":"Lê Duẩn","hl":[]}],"answer":["D"],"note":""},{"id":"54","question":"Đại hội Đảng lần thứ III (9/1960) xác định mục tiêu chung trước mắt của cả nước là:","qHighlight":[],"options":[{"key":"A","text":"Hoàn thành cách mạng xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Lật đổ chế độ độc tài gia đình trị ở miền Nam","hl":[]},{"key":"C","text":"Đánh đuổi quân đội Mỹ khỏi miền Nam","hl":[]},{"key":"D","text":"Giải phóng miền Nam, hòa bình, thống nhất Tổ quốc","hl":[]}],"answer":["D"],"note":""},{"id":"55","question":"Đại hội lần thứ I Đảng Cộng sản Đông Dương được tổ chức tại:","qHighlight":[],"options":[{"key":"A","text":"Quảng Châu","hl":[]},{"key":"B","text":"Hồng Công","hl":[]},{"key":"C","text":"Ma Cao","hl":[]},{"key":"D","text":"Thượng Hải","hl":[]}],"answer":["C"],"note":""},{"id":"56","question":"Nguyên tắc tổ chức cơ bản của Đảng Cộng sản Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Dân chủ","hl":[]},{"key":"B","text":"Tập trung","hl":[]},{"key":"C","text":"Dân chủ tập trung","hl":[]},{"key":"D","text":"Tập trung dân chủ","hl":[]}],"answer":["D"],"note":""},{"id":"57","question":"Thành quả quan trọng nhất của cuộc Tổng tiến công và nổi dậy Tết Mậu Thân (1968) là:","qHighlight":["Mậu Thân"],"options":[{"key":"A","text":"Đánh bại ý chí xâm lược của Mỹ","hl":[]},{"key":"B","text":"Đánh bại quân đội Mỹ trên chiến trường","hl":[]},{"key":"C","text":"Đánh bại quân đội Sài Gòn","hl":[]},{"key":"D","text":"Đánh đổ chính quyền Sài Gòn","hl":[]}],"answer":["A"],"note":""},{"id":"58","question":"Phương châm tác chiến của Quân đội nhân dân Việt Nam trong chiến dịch Điện Biên Phủ là:","qHighlight":["Điện Biên Phủ"],"options":[{"key":"A","text":"Đánh nhanh, thắng nhanh","hl":[]},{"key":"B","text":"Đánh thần tốc, táo bạo, chắc thắng","hl":[]},{"key":"C","text":"Đánh thần tốc, táo bạo, bất ngờ","hl":[]},{"key":"D","text":"Đánh chắc, tiến chắc","hl":[]}],"answer":["D"],"note":""},{"id":"59","question":"Việt Nam chính thức trở thành thành viên của tổ chức WTO vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"11/1/2006","hl":[]},{"key":"B","text":"11/1/2007","hl":[]},{"key":"C","text":"11/1/2008","hl":[]},{"key":"D","text":"11/1/2009","hl":[]}],"answer":["B"],"note":""},{"id":"60","question":"Chỉ thị Kháng chiến kiến quốc (25/11/1945) xác định kẻ thù chính của cách mạng Việt Nam lúc bấy giờ là:","qHighlight":[],"options":[{"key":"A","text":"Thực dân Pháp","hl":[]},{"key":"B","text":"Thực dân Anh","hl":[]},{"key":"C","text":"Quân đội Tường Giới Thạch","hl":[]},{"key":"D","text":"Lực lượng Việt Quốc, Việt Cách","hl":[]}],"answer":["A"],"note":""},{"id":"61","question":"Lãnh tụ Nguyễn Ái Quốc tìm thấy ở Chủ nghĩa Lênin con đường giải phóng cho dân tộc Việt Nam thông qua việc:","qHighlight":[],"options":[{"key":"A","text":"Gửi Bản yêu sách của nhân dân An Nam (1919)","hl":[]},{"key":"B","text":"Bỏ phiếu tán thành Quốc tế Cộng sản, sáng lập Đảng Cộng sản Pháp (1920)","hl":[]},{"key":"C","text":"Đọc Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa (1920)","hl":["Đọc Sơ thảo lần thứ nhất những luận cương"]},{"key":"D","text":"Dự Đại hội lần thứ V Quốc tế Cộng sản (1924)","hl":[]}],"answer":["C"],"note":""},{"id":"62","question":"Tác động của chương trình khai thác thuộc địa lần thứ hai của Pháp đến kinh tế Việt Nam làm cho :","qHighlight":[],"options":[{"key":"A","text":"Cơ cấu kinh tế Việt Nam mất cân đối, lạc hậu, nghèo nàn","hl":["Nam mất cân đối, lạc hậu, nghèo"]},{"key":"B","text":"Nền kinh tế Việt Nam phát triển độc lập","hl":[]},{"key":"C","text":"Kinh tế Việt Nam phát triển một cách tự chủ","hl":[]},{"key":"D","text":"Kinh tế Việt Nam phụ thuộc kinh tế Pháp","hl":[]}],"answer":["A"],"note":""},{"id":"63","question":"Tính chất của xã hội Việt Nam sau khi thực dân Pháp đặt được ách cai trị là gì? Tính chất của xã hội Việt Nam dưới sự thống trị của thực dân Pháp là :","qHighlight":[],"options":[{"key":"A","text":"Xã hội thuộc địa, nửa phong kiến","hl":["thuộc địa, nửa phong"]},{"key":"B","text":"Xã hội phong kiến","hl":[]},{"key":"C","text":"Xã hội thuôc địa","hl":[]},{"key":"D","text":"Xã hội chiếm hữu","hl":[]}],"answer":["A"],"note":""},{"id":"64","question":"Sự kiện nào được lãnh tụ Nguyễn Ái Quốc đánh giá \"nó chứng tỏ rằng giai cấp vô sản ta đã trưởng thành và đủ sức lãnh đạo cách mạng giải phóng dân tộc\"?","qHighlight":[],"options":[{"key":"A","text":"Quốc tế Cộng sản ra đời (1919)","hl":[]},{"key":"B","text":"Hội Việt Nam Cách mạng Thanh niên ra đời (1925)","hl":[]},{"key":"C","text":"Ba tổ chức cộng sản ra đời (1929)","hl":[]},{"key":"D","text":"Đảng Cộng sản Việt Nam ra đời (1930)","hl":[]}],"answer":["D"],"note":""},{"id":"65","question":"Lãnh tụ Nguyễn Ái Quốc sáng lập tờ báo Le Paria (Người cùng khổ) và viết nhiều bài trên đó là sự chuẩn bị cho sự ra đời của Đảng Cộng sản Việt Nam về mặt:","qHighlight":[],"options":[{"key":"A","text":"Tư tưởng","hl":[]},{"key":"B","text":"Chính trị","hl":[]},{"key":"C","text":"Tổ chức","hl":[]},{"key":"D","text":"Đạo đức","hl":[]}],"answer":["A"],"note":"Mẹo nhớ: Báo Người cùng khổ (Le Paria) = chuẩn bị về TƯ TƯỞNG"},{"id":"66","question":"Trong các nội dung sau đây, nội dung nào không thuộc luận cương chính trị tháng 10/1930?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng Việt Nam phải trải qua hai giai đoạn: cách mạng tư sản dân quyền và cách mạng xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Cách mạng do Đảng của giai cấp vô sản lãnh đạo","hl":[]},{"key":"C","text":"Cách mạng Việt Nam là một bộ phận của cách mạng thế giới","hl":[]},{"key":"D","text":"Lực lượng để đánh đuổi đế quốc và phong kiến là công nông. Đồng thời \"phải biết liên lạc với tiểu tư sản, tri thức, trung nông ... để kéo họ về phe vô sản giai cấp\"","hl":[]}],"answer":["D"],"note":""},{"id":"67","question":"Sự kiện nào được Nguyễn Ái Quốc đánh giá \"là một bước ngoặt vô cùng quan trọng trong lịch sử Cách mạng Việt Nam ta\"?","qHighlight":[],"options":[{"key":"A","text":"Đảng Cộng sản Việt Nam ra đời","hl":[]},{"key":"B","text":"Sự thành lập Đảng Cộng sản Pháp","hl":[]},{"key":"C","text":"Sự thành lập hội Việt Nam Cách mạng thanh niên","hl":[]},{"key":"D","text":"Nguyễn Ái Quốc tìm thấy con đường cứu nước","hl":[]}],"answer":["A"],"note":""},{"id":"68","question":"Cương lĩnh đầu tiên của Đảng đã xác định mục tiêu chiến lược của cách mạng Việt Nam là gì?","qHighlight":[],"options":[{"key":"A","text":"Xây dựng một nước Việt Nam dân giàu, nước mạnh, dân chủ, công bằng, văn minh","hl":[]},{"key":"B","text":"Xây dựng một nước Việt Nam dân giàu mạnh","hl":[]},{"key":"C","text":"Làm tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản","hl":[]},{"key":"D","text":"Cách mạng tư sản dân quyền, lập chính quyền của công nông bằng hình thức Xô viết, để dự bị điều kiện đi tới cách mạng xã hội chủ nghĩa","hl":[]}],"answer":["C"],"note":""},{"id":"69","question":"Nội dung nào không có trong \"Luận cương chính trị\" tháng 10 năm 1930?","qHighlight":["không c"],"options":[{"key":"A","text":"Đặt nhiệm vụ chống đế quốc, giải phóng dân tộc lên hàng đầu.","hl":[]},{"key":"B","text":"Đánh giá không đúng vai trò cách mạng của tầng lớp tiểu tư sản, phủ nhận mặt tích cực của tư sản dân tộc.","hl":[]},{"key":"C","text":"Không nêu được mâu thuẫn chủ yếu là mâu thuẫn giữa dân tộc Việt Nam và đế quốc Pháp.","hl":[]},{"key":"D","text":"Không đề ra được chiến lược liên minh dân tộc và giai cấp rộng rãi","hl":[]}],"answer":["A"],"note":""},{"id":"70","question":"Hình thức đấu tranh chủ yếu trong phong trào 1930-1931 của nhân dân Nghệ - Tĩnh là gì?","qHighlight":[],"options":[{"key":"A","text":"Bãi công chính trị.","hl":[]},{"key":"B","text":"Biểu tình có vũ trang tự vệ.","hl":["có vũ trang tự vệ."]},{"key":"C","text":"Mít tinh đòi quyền dân chủ.","hl":[]},{"key":"D","text":"Đưa yêu sách cải thiện đời sống.","hl":[]}],"answer":["B"],"note":""},{"id":"71","question":"Đại hội đại biểu toàn quốc của Đảng cộng sản Đông Dương vào tháng 3-1935 bầu ai làm Tổng bí thư?","qHighlight":[],"options":[{"key":"A","text":"Trần Phú","hl":[]},{"key":"B","text":"Nguyễn Văn Cừ","hl":[]},{"key":"C","text":"Lê Hồng Phong","hl":[]},{"key":"D","text":"Hà Huy Tập","hl":[]}],"answer":["C"],"note":""},{"id":"72","question":"Xu hướng giành độc lập dân tộc theo con đường cải cách đất nước gắn với tên tuổi của nhà yêu nước nào?","qHighlight":[],"options":[{"key":"A","text":"Phan Châu Trinh","hl":[]},{"key":"B","text":"Phan Bội Châu","hl":[]},{"key":"C","text":"Phan Đình Phùng","hl":[]},{"key":"D","text":"Phan Văn Trường","hl":[]}],"answer":["A"],"note":""},{"id":"73","question":"Mục tiêu cụ thể trước mắt của phong trào vận động dân chủ Đông Dương (1936-1939) là gì?","qHighlight":["dân chủ Đông Dương"],"options":[{"key":"A","text":"Độc lập dân tộc, gắn với chủ nghĩa xã hội","hl":[]},{"key":"B","text":"Các quyền tự do, dân chủ, cơm áo và hòa bình","hl":[]},{"key":"C","text":"Ruộng đất cho dân cày","hl":[]},{"key":"D","text":"Đánh đổ đế quốc Pháp và tay sai","hl":[]}],"answer":["B"],"note":""},{"id":"74","question":"Chủ trương chuyển hướng chiến lược cách mạng từ làm cách mạng tư sản dân quyền sang làm cách mạng giải phóng dân tộc được đặt ra từ Hội nghị nào của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị Ban Chấp hành Trung ương tháng 10/1930","hl":[]},{"key":"B","text":"Hội nghị Ban Chấp hành Trung ương tháng 11/1939","hl":["/1939"]},{"key":"C","text":"Hội nghị Cán bộ Trung ương tháng 11/1940","hl":[]},{"key":"D","text":"Hội nghị Ban Chấp hành Trung ương tháng 5/1941","hl":[]}],"answer":["B"],"note":""},{"id":"75","question":"(Hội nghị Trung ương 6 (11/1939) mở đầu quá trình chuyển hướng. Hội nghị Trung ương 7 (11/1940) tiếp tục phát triển hướng này. Hội nghị Trung ương 8 (5/1941) hoàn thiện chủ trương chuyển hướng chiến lược.) Chiến tranh thế giới thứ II nổ ra vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"1937","hl":[]},{"key":"B","text":"1938","hl":[]},{"key":"C","text":"1939","hl":[]},{"key":"D","text":"1940","hl":[]}],"answer":["C"],"note":""},{"id":"76","question":"Mâu thuẫn chủ yếu ở Việt Nam cuối thế kỷ XIX đầu thế kỷ XX là mâu thuẫn giữa:","qHighlight":[],"options":[{"key":"A","text":"Địa chủ phong kiến với nông dân","hl":[]},{"key":"B","text":"Tư sản với công nhân","hl":[]},{"key":"C","text":"Tư sản Việt Nam với tư sản Pháp","hl":[]},{"key":"D","text":"Dân tộc Việt Nam với đế quốc Pháp","hl":[]}],"answer":["D"],"note":""},{"id":"77","question":"Nội dung nào sai trong Hội nghị Trung ương VIII của Đảng (tháng 5 năm 1941)?","qHighlight":[],"options":[{"key":"A","text":"Đưa nhiệm vụ giải phóng dân tộc lên hàng đầu.","hl":[]},{"key":"B","text":"Chuẩn bị điều kiện để \"đánh đổ địa chủ, chia ruộng đất cho dân cày\".","hl":["kiện để \"đánh đổ địa chủ, chia ruộng đất cho dân cày\"."]},{"key":"C","text":"Thành lập mặt trận Việt Minh để tập hợp lực lượng cách mạng nhằm mục tiêu giải phóng dân tộc.","hl":[]},{"key":"D","text":"Xác định chuẩn bị khởi nghĩa là nhiệm vụ trung tâm trong giai đoạn hiện tại","hl":[]}],"answer":["B"],"note":""},{"id":"78","question":"Mặt trận Việt Nam độc lập đồng minh được thành lập năm nào?","qHighlight":[],"options":[{"key":"A","text":"19/5/1940","hl":[]},{"key":"B","text":"19/5/1941","hl":[]},{"key":"C","text":"19/5/1942","hl":[]},{"key":"D","text":"19/5/1943","hl":[]}],"answer":["B"],"note":""},{"id":"79","question":"Hội nghị của Ban chấp hành Trung ương nào sau đây nhấn mạnh giải phóng dân tộc là nhiệm vụ bức thiết nhất?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị trung ương I tháng 10/1930","hl":[]},{"key":"B","text":"Hội nghị trung ương VI tháng 11/1939","hl":[]},{"key":"C","text":"Hội nghị trung ương VII tháng 11/1940","hl":[]},{"key":"D","text":"Hội nghị trung ương VIII tháng 5/1941","hl":[]}],"answer":["D"],"note":""},{"id":"80","question":"Mặt trận dân chủ Đông dương chính thức thành lập vào năm nào?","qHighlight":[],"options":[{"key":"A","text":"Năm 1938","hl":[]},{"key":"B","text":"Năm 1930","hl":[]},{"key":"C","text":"Năm 1941","hl":[]},{"key":"D","text":"Năm 1945","hl":[]}],"answer":["A"],"note":""},{"id":"81","question":"Nguyên nhân nào làm cho phong trào ở Nghệ - Tĩnh lên cao?","qHighlight":[],"options":[{"key":"A","text":"Vì Nghệ - Tĩnh đã lập được chính quyền xô viết.","hl":[]},{"key":"B","text":"Vì Nghệ - Tĩnh có tổ chức cộng sản và cơ sở đảng khá mạnh.","hl":[]},{"key":"C","text":"Vì nhân dân ở đây có lòng yêu nước và căm thù giặc sâu sắc.","hl":[]},{"key":"D","text":"Vì cơ sở công nghiệp Vinh - Bến Thủy ở Nghệ - Tĩnh là trung tâm kỹ nghệ lớn nhất ở Việt Nam.","hl":[]}],"answer":["B"],"note":""},{"id":"82","question":"Để tuyên truyền chủ nghĩa Mác trong giai đoạn 1932-1933, Đảng Cộng sản Việt Nam đã sử dụng phương pháp gì?","qHighlight":[],"options":[{"key":"A","text":"Tổ chức các hội công khai, như hội cấy, hội cày, hội đá bóng...","hl":[]},{"key":"B","text":"Tổ chức các cuộc bút chiến công khai","hl":[]},{"key":"C","text":"Tổ chức các buổi học bí mật","hl":[]},{"key":"D","text":"Tổ chức giải truyền đơn","hl":[]}],"answer":["B"],"note":""},{"id":"83","question":"Đặc điểm lớn nhất của cách mạng Việt Nam sau tháng 7/1954 là:","qHighlight":[],"options":[{"key":"A","text":"Kẻ thù chính lúc này là đế quốc Mỹ với tiềm lực kinh tế và quân sự hùng mạnh","hl":[]},{"key":"B","text":"Miền Bắc đi lên chủ nghĩa xã hội từ một nền nông nghiệp lạc hậu","hl":[]},{"key":"C","text":"Miền Nam trở thành thuộc địa kiểu mới, do chính quyền đối phương quản lý","hl":[]},{"key":"D","text":"Đất nước bị chia thành hai miền, có hai chế độ chính trị xã hội khác nhau","hl":[]}],"answer":["D"],"note":"Mẹo nhớ: Sau 7/1954 đất nước tạm chia 2 miền tại vĩ tuyến 17 (sông Bến Hải)"},{"id":"84","question":"Đặc điểm của nước Việt Nam Dân chủ Cộng hòa ngay khi ra đời là","qHighlight":[],"options":[{"key":"A","text":"Được các nước lớn công nhận","hl":[]},{"key":"B","text":"Được Liên hợp quốc công nhận","hl":[]},{"key":"C","text":"Không được sự ủng hộ của các nước Đồng minh","hl":[]},{"key":"D","text":"Gắn liền với hậu phương xã hội chủ nghĩa","hl":[]}],"answer":["C"],"note":""},{"id":"85","question":"Nội dung nào chưa đúng trong các bài học lãnh đạo cách mạng của Đảng để dẫn tới cách mạng Tháng Tám 1945 thắng lợi?","qHighlight":[],"options":[{"key":"A","text":"Giương cao ngọn cờ độc lập dân tộc, kết hợp đúng đắn hai nhiệm vụ chống đế quốc và chống phong kiến.","hl":[]},{"key":"B","text":"Sử dụng lực lượng vũ trang áp đảo tiêu diệt kẻ thù","hl":[]},{"key":"C","text":"Lợi dụng mâu thuẫn trong hàng ngũ kẻ thù.","hl":[]},{"key":"D","text":"Nắm vững nghệ thuật khởi nghĩa, nghệ thuật chọn đúng thời cơ.","hl":[]}],"answer":["B"],"note":""},{"id":"86","question":"Phong trào Xô Viết Nghệ Tĩnh được bắt đầu từ ngày tháng năm nào?","qHighlight":[],"options":[{"key":"A","text":"1 - 5 - 1930","hl":[]},{"key":"B","text":"1 - 5 - 1931","hl":[]},{"key":"C","text":"19 - 5 - 1930","hl":[]},{"key":"D","text":"19 -8 - 1930","hl":[]}],"answer":["A"],"note":""},{"id":"87","question":"Tại Đại hội nào, lần đầu tiên Đảng giương cao ngọn cờ tư tưởng Hồ Chí Minh và khẳng định \"lấy chủ nghĩa Mác - Lênin và tư tưởng Hồ Chí Minh làm nền tảng tư tưởng và kim chỉ nam cho hành động\"?","qHighlight":[],"options":[{"key":"A","text":"Đại hội VI (1986)","hl":[]},{"key":"B","text":"Đại hội VII (1991)","hl":[]},{"key":"C","text":"Đại hội VIII (1996)","hl":[]},{"key":"D","text":"Đại hội IX (2001)","hl":[]}],"answer":["B"],"note":""},{"id":"88","question":"Bài học \"giương cao ngọn cờ độc lập dân tộc, kết hợp đúng đắn hai nhiệm vụ chống đế quốc và chống phong kiến\" được Đảng rút ra sau thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng Tháng Tám","hl":[]},{"key":"B","text":"Cách mạng dân tộc dân chủ nhân dân ở miền Nam","hl":[]},{"key":"C","text":"Cách mạng xã hội chủ nghĩa ở miền Bắc","hl":[]},{"key":"D","text":"Cách mạng Tháng Mười","hl":[]}],"answer":["A"],"note":""},{"id":"89","question":"Nhân dân ta phải tiến hành tổng khởi nghĩa giành chính quyền trước khi quân Đồng minh vào Đông Dương vì:","qHighlight":[],"options":[{"key":"A","text":"Đó là lúc so sánh lực lượng có lợi nhất đối với cách mạng","hl":[]},{"key":"B","text":"Đó là lúc kẻ thù cũ đã ngã gục nhưng kẻ thù mới chưa kịp đến","hl":[]},{"key":"C","text":"Quân Đồng minh có thể dựng ra một chính quyền trái với ý chí và nguyện vọng của nhân dân ta","hl":[]},{"key":"D","text":"Tất cả nhận định trên","hl":[]}],"answer":["D"],"note":""},{"id":"90","question":"Kỳ họp thứ nhất Quốc hội khóa VI (24/6 - 3/7/1976) quyết định đặt tên nước ta là:","qHighlight":[],"options":[{"key":"A","text":"Cộng hòa xã hội chủ nghĩa Việt Nam","hl":[]},{"key":"B","text":"Cộng hòa Việt Nam","hl":[]},{"key":"C","text":"Cộng hòa Dân chủ Việt Nam","hl":[]},{"key":"D","text":"Việt Nam Dân chủ Cộng hòa","hl":[]}],"answer":["A"],"note":""},{"id":"91","question":"Lần đầu tiên Ban Chấp hành Trung ương Đảng tại hội nghị lần thứ 8 (5-1941) chủ trương thành lập chính quyền Nhà nước với hình thức gì?","qHighlight":[],"options":[{"key":"A","text":"Cộng hòa dân chủ","hl":[]},{"key":"B","text":"Cộng hòa xã hội chủ nghĩa","hl":[]},{"key":"C","text":"Cộng hòa nghị viện","hl":[]},{"key":"D","text":"Cộng hòa nhân dân","hl":[]}],"answer":["A"],"note":""},{"id":"92","question":"\"Đoàn kết, tập hợp lực lượng cách mạng nhằm giải phóng dân tộc\" là chủ trương của Đảng trong việc thành lập tổ chức nào?","qHighlight":[],"options":[{"key":"A","text":"Mặt trận Việt Minh","hl":[]},{"key":"B","text":"Mặt trận dân chủ thống nhất phản đế Đông Dương","hl":[]},{"key":"C","text":"Mặt trận dân chủ Đông Dương","hl":[]},{"key":"D","text":"Hội phản đế đồng minh","hl":[]}],"answer":["A"],"note":""},{"id":"93","question":"Cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 bắt đầu bằng chiến dịch nào?","qHighlight":[],"options":[{"key":"A","text":"Chiến dịch Mậu Thân (1968)","hl":[]},{"key":"B","text":"Chiến dịch Tây Nguyên (3/1975)","hl":[]},{"key":"C","text":"Chiến dịch Huế - Đà Nẵng (3/1975)","hl":[]},{"key":"D","text":"Chiến dịch Hồ Chí Minh (4/1975)","hl":[]}],"answer":["B"],"note":""},{"id":"94","question":"Hội nghị thành lập Đảng Cộng sản Việt Nam thông qua mấy văn kiện do lãnh tụ Nguyễn Ái Quốc soạn thảo?","qHighlight":[],"options":[{"key":"A","text":"2 văn kiện","hl":[]},{"key":"B","text":"3 văn kiện","hl":[]},{"key":"C","text":"4 văn kiện","hl":[]},{"key":"D","text":"5 văn kiện","hl":[]}],"answer":["B"],"note":""},{"id":"96","question":"Chính phủ lâm thời nước Việt Nam dân chủ cộng hòa ra đời từ tổ chức nào?","qHighlight":["âm thời"],"options":[{"key":"A","text":"Việt Minh","hl":[]},{"key":"B","text":"Ủy ban dân tộc giải phóng Việt Nam","hl":["giải phóng Việt Nam"]},{"key":"C","text":"Ủy ban lâm thời khu giải phóng","hl":[]},{"key":"D","text":"Ủy ban khởi nghĩa","hl":[]}],"answer":["B"],"note":""},{"id":"97","question":"Ban chấp hành Trung ương Đảng chủ trương thành lập nước Việt Nam dân chủ cộng hoà tại Hội nghị nào?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị trung ương tháng 10/1930","hl":[]},{"key":"B","text":"Hội nghị trung ương VI tháng 11/1939","hl":[]},{"key":"C","text":"Hội nghị trung ương VII tháng 11/1940","hl":[]},{"key":"D","text":"Hội nghị trung ương VIII tháng 5/1941","hl":[]}],"answer":["D"],"note":""},{"id":"98","question":"Chống phát xít, chống chiến tranh đế quốc, chống bọn phản động thuộc địa và tay sai là nhiệm vụ cách mạng được Đảng đề ra trong giai đoạn nào?","qHighlight":[],"options":[{"key":"A","text":"1930 - 1931","hl":[]},{"key":"B","text":"1936-1939","hl":[]},{"key":"C","text":"1939 - 1945","hl":[]},{"key":"D","text":"1945-1954","hl":[]}],"answer":["B"],"note":""},{"id":"99","question":"Hai khẩu hiệu mà Đảng ta vận dụng trong phong trào cách mạng 1930- 1931 là:","qHighlight":[],"options":[{"key":"A","text":"\"Độc lập dân tộc\" và \"Ruộng đất dân cày\"..","hl":[]},{"key":"B","text":"\"Tự do dân chủ\" và \"cơm áo hòa bình\".","hl":[]},{"key":"C","text":"\"Giải phóng dân tộc\" và \"tịch thu ruộng đất của đế quốc Việt gian\".","hl":[]},{"key":"D","text":"\"Chống đế quốc\" và \"Chống phát xít, chống chiến tranh\".","hl":[]}],"answer":["A"],"note":""},{"id":"100","question":"Đại hội lần thứ III của Đảng (9/1960) xác định cách mạng Việt Nam trong giai đoạn mới phải đồng thời thực hiện mấy chiến lược cách mạng?","qHighlight":[],"options":[{"key":"A","text":"2","hl":[]},{"key":"B","text":"3","hl":[]},{"key":"C","text":"4","hl":[]},{"key":"D","text":"5","hl":[]}],"answer":["A"],"note":""},{"id":"101","question":"Chủ trương điều chỉnh chiến lược cách mạng của Đảng được bắt đầu từ Hội nghị Trung ương nào của khóa I?","qHighlight":["nào của khóa I?"],"options":[{"key":"A","text":"Hội nghị Trung ương 6 (11/1939)","hl":["1939)"]},{"key":"B","text":"Hội nghị Trung ương 7 (11/1940)","hl":[]},{"key":"C","text":"Hội nghị Trung ương 8 (5/1941)","hl":[]}],"answer":["A"],"note":""},{"id":"102","question":"Cuộc tập dượt thứ nhất của Đảng chuẩn bị cho thắng lợi của cách mạng tháng Tám là giai đoạn :","qHighlight":["dượt thứ nhất"],"options":[{"key":"A","text":"1930-1931","hl":[]},{"key":"B","text":"1936-1939","hl":[]},{"key":"C","text":"1939-1945","hl":[]},{"key":"D","text":"1945-1954","hl":[]}],"answer":["A"],"note":""},{"id":"103","question":"Chánh cương vắn tắt, Sách lược vắn tắt do Hội nghị thành lập Đảng thông qua đã đặt nhiệm vụ gì lên hàng đầu?","qHighlight":[],"options":[{"key":"A","text":"Nhiệm vụ chống tư sản","hl":[]},{"key":"B","text":"Nhiệm vụ chống phong kiến","hl":[]},{"key":"C","text":"Nhiệm vụ chống tay sai phản động","hl":[]},{"key":"D","text":"Nhiệm vụ chống đế quốc","hl":[]}],"answer":["D"],"note":""},{"id":"104","question":"Điền vào chỗ trống: Đêm 9/3/1945, Nhật đảo chính Pháp, ngày 12-3-1945, ... đã ra Bản Chỉ thị \"Nhật Pháp bắn nhau và hành động của chúng ta\"","qHighlight":[],"options":[{"key":"A","text":"Ban Thường vụ Trung ương Đảng","hl":[]},{"key":"B","text":"Trung ương cục miền Nam","hl":[]},{"key":"C","text":"Quốc dân đại hội","hl":[]},{"key":"D","text":"Đại hội toàn quốc của Đảng","hl":[]}],"answer":["A"],"note":""},{"id":"105","question":"Đảng chủ trương thành lập mặt trận Việt Minh vì mục đích gì?","qHighlight":[],"options":[{"key":"A","text":"Nhằm tập hợp rộng rãi nông dân chống đế quốc","hl":[]},{"key":"B","text":"Tạm gác lại khẩu hiệu \"đánh đổ địa chủ, chia ruộng đất cho dân cày\"","hl":[]},{"key":"C","text":"Để đoàn kết, tập hợp lực lượng cách mạng nhằm giải phóng dân tộc","hl":["Để đoàn kết,"]},{"key":"D","text":"Nhằm tranh thủ lực lượng đồng minh chống phát xít Nhật","hl":[]}],"answer":["C"],"note":""},{"id":"106a","question":"Quốc tế cộng sản (Quốc tế III) được thành lập vào năm nào?","qHighlight":[],"options":[{"key":"A","text":"1918","hl":[]},{"key":"B","text":"1919","hl":[]},{"key":"C","text":"1920","hl":[]},{"key":"D","text":"1921","hl":[]}],"answer":["B"],"note":"Liên hệ: Nguyễn Tất Thành tham gia Đảng Xã hội Pháp cũng vào năm 1919"},{"id":"106b","question":"Mục tiêu cụ thể trước mắt của cao trào cách mạng 1936 - 1939 là:","qHighlight":[],"options":[{"key":"A","text":"Độc lập dân tộc","hl":[]},{"key":"B","text":"Ruộng đất cho dân cày","hl":[]},{"key":"C","text":"Đánh đổ chế độ thực dân, phong kiến","hl":[]},{"key":"D","text":"Các quyền dân chủ đơn sơ","hl":[]}],"answer":["D"],"note":""},{"id":"107","question":"Nguyên nhân chủ yếu và có ý nghĩa quyết định sự bùng nổ và phát triển của cao trào cách mạng Việt Nam năm 1930?","qHighlight":[],"options":[{"key":"A","text":"Tác động tiêu cực của cuộc khủng hoảng kinh tế 1929-1933","hl":[]},{"key":"B","text":"Chính sách khủng bố trắng của đế quốc Pháp","hl":[]},{"key":"C","text":"Chính sách tăng cường vơ vét bóc lột của đế quốc Pháp","hl":[]},{"key":"D","text":"Sự lãnh đạo của Đảng Cộng sản Việt Nam","hl":[]}],"answer":["D"],"note":""},{"id":"108","question":"Điểm giống nhau giữa Luận cương chính trị 10-1930 và Cương lĩnh chính trị đầu tiên của Đảng tháng 2-1930 là:","qHighlight":[],"options":[{"key":"A","text":"Khẳng định vai trò lãnh đạo cách mạng của Đảng Cộng sản","hl":[]},{"key":"B","text":"Xác định nhiệm vụ cách mạng là chống đế quốc, phong kiến","hl":[]},{"key":"C","text":"Ảnh hưởng quan trọng đối với cách mạng Đông Dương","hl":[]},{"key":"D","text":"Xác định lực lượng là công- nông","hl":[]}],"answer":["A"],"note":""},{"id":"109","question":"Nghị quyết Hội nghị Trung ương 2 khóa VIII (12/1996) coi khoa học và công nghệ, giáo dục và đào tạo là:","qHighlight":[],"options":[{"key":"A","text":"Quốc sách chiến lược","hl":[]},{"key":"B","text":"Quốc sách hàng đầu","hl":[]},{"key":"C","text":"Quốc sách đặc biệt","hl":[]},{"key":"D","text":"Quốc sách quan trọng nhất","hl":[]}],"answer":["B"],"note":""},{"id":"110","question":"Hội nghị trung ương VIII tháng 5/1941 nhấn mạnh điều gì?","qHighlight":[],"options":[{"key":"A","text":"Giải phóng dân tộc là nhiệm vụ quan trọng","hl":[]},{"key":"B","text":"Giải phóng dân tộc là nhiệm vụ cần thiết","hl":[]},{"key":"C","text":"Giải phóng giai cấp là nhiệm vụ bức thiết nhất","hl":[]},{"key":"D","text":"Giải phóng dân tộc là nhiệm vụ bức thiết nhất","hl":[]}],"answer":["D"],"note":""},{"id":"111","question":"Đại hội lần thứ VII của Quốc tế Cộng sản họp vào năm nào?","qHighlight":[],"options":[{"key":"A","text":"1936","hl":[]},{"key":"B","text":"1930","hl":[]},{"key":"C","text":"1935","hl":[]},{"key":"D","text":"1939","hl":[]}],"answer":["C"],"note":"Đại hội VII Quốc tế Cộng sản họp tháng 7/1935"},{"id":"112","question":"Trong lịch sử Đảng Cộng sản Việt Nam, giai đoạn 1932 - 1935 là giai đoạn:","qHighlight":[],"options":[{"key":"A","text":"Chuẩn bị các điều kiện để giành chính quyền","hl":[]},{"key":"B","text":"Phục hồi hệ thống tổ chức của Đảng","hl":[". Phục hồi hệ thống"]},{"key":"C","text":"Đẩy mạnh phong trào đấu tranh","hl":[]},{"key":"D","text":"Hợp tác với phong trào nhân dân Pháp","hl":[]}],"answer":["B"],"note":""},{"id":"113","question":"Phát xít Nhật xâm lược nước ta vào ngày tháng, năm nào?","qHighlight":[],"options":[{"key":"A","text":"Ngày 22 Tháng 9-1940","hl":[]},{"key":"B","text":"Ngày 26 Tháng 9-1940","hl":[]},{"key":"C","text":"Ngày 20 Tháng 9-1940","hl":[]},{"key":"D","text":"Ngày 25 Tháng 9-1940","hl":[]}],"answer":["A"],"note":""},{"id":"114","question":"Hoạt động chủ yếu của Hội Việt Nam Cách Mạng Thanh Niên thời kỳ ở Quảng Châu (Trung Quốc) là","qHighlight":[],"options":[{"key":"A","text":"Xuất bản báo Thanh niên làm cơ quan tuyên truyền của Hội.","hl":[]},{"key":"B","text":"Thực hiện chủ trương \"vô sản hóa\".","hl":[]},{"key":"C","text":"Mở lớp huấn luyện chính trị, đào tạo cán bộ cách mạng.","hl":[]},{"key":"D","text":"Thành lập cơ sở trong nước.","hl":[]}],"answer":["C"],"note":""},{"id":"115","question":"Chọn các đáp án đúng. Đại hội lần thứ II Đảng Cộng sản Đông Dương (1951) đã quyết định:","qHighlight":[],"options":[{"key":"A","text":"Giữ nguyên Đảng Cộng sản Đông Dương","hl":[]},{"key":"B","text":"Đổi tên thành Đảng Lao động Việt Nam","hl":[]},{"key":"C","text":"Thành lập chính đảng cách mạng riêng ở 2 nước Lào và Campuchia","hl":[]},{"key":"D","text":"Chỉ thành lập chính đảng cách mạng ở Việt Nam","hl":[]}],"answer":["B","C"],"note":""},{"id":"116","question":"Nhiệm vụ cách mạng nào được xác định bởi Cương lĩnh chính trị?","qHighlight":[],"options":[{"key":"A","text":"Đánh đổ phong kiến, đánh đổ đế quốc, 2 nhiệm vụ có quan hệ mật thiết khăng khít với nhau","hl":[]},{"key":"B","text":"Đánh đổ đế quốc Pháp và tư sản phản cách mạng","hl":[]},{"key":"C","text":"Đánh đổ đế quốc Pháp, phong kiến, tư sản phản cách mạng làm cho nước nhà độc lập","hl":[]},{"key":"D","text":"Đánh đuổi đế quốc Pháp và phong kiến","hl":[]}],"answer":["C"],"note":""},{"id":"117","question":"Chính sách đối ngoại \"làm cho nước mình ít kẻ thù hơn hết, nhiều bạn đồng minh hơn hết\" được nêu ra trong văn kiện nào của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Tuyên ngôn độc lập (2/9/1945)","hl":[]},{"key":"B","text":"Chỉ thị Kháng chiến kiến quốc (25/11/1945)","hl":["Chỉ thị Kháng"]},{"key":"C","text":"Hiến pháp năm 1946 (9/11/1946)","hl":[]},{"key":"D","text":"Lời kêu gọi toàn quốc kháng chiến (19/12/1946)","hl":[]}],"answer":["B"],"note":""},{"id":"118","question":"Mặt trận được xây dựng thời kỳ cách mạng 1930- 1931 gọi tên là:","qHighlight":[],"options":[{"key":"A","text":"Mặt trận nhân dân phản đế Đông Dương","hl":[]},{"key":"B","text":"Mặt trận dân chủ Đông Dương","hl":[]},{"key":"C","text":"Hội phản đế Đông Dương","hl":[]},{"key":"D","text":"Mặt trận dân tộc thống nhất phản đế Đông Dương","hl":[]}],"answer":["C"],"note":"Ghi chú tài liệu: Mặt trận 1930-1931 là Hội phản đế Đông Dương"},{"id":"119","question":"Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết (1/1973) đánh dấu hoàn thành nhiệm vụ của cách mạng miền Nam, đó là:","qHighlight":[": Hiệp định Paris"],"options":[{"key":"A","text":"Thống nhất đất nước","hl":[]},{"key":"B","text":"Giải phóng miền Nam","hl":[]},{"key":"C","text":"Buộc quân đội Mỹ rút khỏi miền Nam","hl":[]},{"key":"D","text":"Chiến tranh kết thúc","hl":[]}],"answer":["C"],"note":""},{"id":"120","question":"Đối tượng của cách mạng Việt Nam được xác định trong Cương lĩnh chính trị đầu tiên của Đảng (2/1930) là :","qHighlight":[],"options":[{"key":"A","text":"Phong kiến, đế quốc","hl":[]},{"key":"B","text":"Đế quốc, tư sản phản cách mạng","hl":[]},{"key":"C","text":"Thực dân Pháp và tư sản mại bản","hl":[]},{"key":"D","text":"Đế quốc, phong kiến và tư sản phản cách mạng","hl":[]}],"answer":["D"],"note":""},{"id":"121","question":"Hội Việt Nam Cách mạng Thanh niên hoạt động theo khuynh hướng nào?","qHighlight":[],"options":[{"key":"A","text":"Khuynh hướng phong kiến","hl":[]},{"key":"B","text":"Khuynh hướng vô sản","hl":["vô sản"]},{"key":"C","text":"Khuynh hướng tư sản","hl":[]},{"key":"D","text":"Khuynh hướng tiểu tư sản","hl":[]}],"answer":["B"],"note":""},{"id":"122","question":"Chỉ thị Kháng chiến kiến quốc của Trung ương Đảng ngày 25/11/1945, xác định nhiệm vụ nào là trung tâm, bao trùm nhất?","qHighlight":[],"options":[{"key":"A","text":"Củng cố, bảo vệ chính quyền cách mạng","hl":["Củng cố,"]},{"key":"B","text":"Chống thực dân Pháp xâm lược","hl":[]},{"key":"C","text":"Cải thiện đời sống nhân dân","hl":[]},{"key":"D","text":"Củng cố, bảo vệ chính quyền cách mạng","hl":[]}],"answer":["A"],"note":""},{"id":"123","question":"Cách mạng tháng Mười Nga thành công (1917) và Quốc tế Cộng sản ra đời (1919) có ý nghĩa:","qHighlight":[],"options":[{"key":"A","text":"Đánh dấu sự thành công của cách mạng vô sản trên thế giới","hl":[]},{"key":"B","text":"Thức tỉnh phong trào đấu tranh của giai cấp công nhân ở các nước đế quốc","hl":[]},{"key":"C","text":"Thúc đẩy cuộc đấu tranh giai cấp ở các nước thuộc địa, phụ thuộc","hl":[]},{"key":"D","text":"Thức tỉnh phong trào đấu giải phóng dân tộc ở các nước thuộc địa, phụ thuộc","hl":[]}],"answer":["D"],"note":""},{"id":"124","question":"Sự kiện lịch sử nào ảnh hưởng đến phong trào cách mạng nước ta trong những năm 1930-1931?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng tháng Mười Nga thành công","hl":[]},{"key":"B","text":"Sự thành lập Quốc tế Cộng sản","hl":[]},{"key":"C","text":"Cuộc khủng hoảng kinh tế 1929-1933","hl":[]},{"key":"D","text":"Thắng lợi của cách mạng tháng Tám","hl":[]}],"answer":["C"],"note":""},{"id":"125","question":"Khởi nghĩa thắng lợi ở địa phương nào đã tạo điều kiện quyết định cho Tổng khởi nghĩa thành công trên cả nước trong Cách mạng tháng Tám (1945)?","qHighlight":[],"options":[{"key":"A","text":"Thái Nguyên","hl":[]},{"key":"B","text":"Hà Nôi","hl":[]},{"key":"C","text":"Huế","hl":[]},{"key":"D","text":"Sài Gòn","hl":[]}],"answer":["B"],"note":""},{"id":"126","question":"Nghị quyết Hội nghị Trung ương lần thứ 15 (1/1959) đánh dấu sự thay đổi chiến lược trong chỉ đạo cách mạng miền Nam ở điểm nào?","qHighlight":[],"options":[{"key":"A","text":"Chuyển cách mạng miền Nam sang đấu tranh đòi quyền tự do dân chủ","hl":[]},{"key":"B","text":"Kết hợp đấu tranh chính trị với đấu tranh vũ trang quân sự, tiến tới khởi nghĩa vũ trang giành chính quyền về tay nhân dân","hl":["giành chính quyền về tay nhân dân"]},{"key":"C","text":"Sử dụng đấu tranh chính trị giành chính quyền về tay nhân dân","hl":[]},{"key":"D","text":"Tập trung lực lượng chính trị, lực lượng vũ trang đấu tranh giành độc lập dân tộc","hl":[]}],"answer":["B"],"note":""},{"id":"127","question":"Chính sách phát triển kinh tế được Đảng đề ra tại Đại hội VI (1986) là:","qHighlight":[],"options":[{"key":"A","text":"Tự cung tự cấp","hl":[]},{"key":"B","text":"Kế hoạch hóa tập trung","hl":[]},{"key":"C","text":"Kinh tế thị trường","hl":[]},{"key":"D","text":"Kinh tế nhiều thành phần","hl":[]}],"answer":["D"],"note":""},{"id":"128","question":"Nội dung \"tập trung ưu tiên hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa\" được Đại hội Đảng lần thứ XIII xác định là:","qHighlight":[],"options":[{"key":"A","text":"Hoàn thiện hệ thống luật pháp, cơ chế, chính sách","hl":[]},{"key":"B","text":"Ưu tiên chính sách phát triển kinh tế tư nhân","hl":[]},{"key":"C","text":"Ưu tiên chính sách phát triển kinh tế nhà nước","hl":[]},{"key":"D","text":"Tạo lập môi trường đầu tư, kinh doanh thuận lợi, lành mạnh, công bằng cho mọi thành phần kinh tế","hl":[]}],"answer":["A"],"note":""},{"id":"129","question":"Đâu là hạn chế của Đảng trong quá trình lãnh đạo, chỉ đạo các hoạt động quân sự năm 1968?","qHighlight":[],"options":[{"key":"A","text":"Thiếu tính sáng tạo, bất ngờ, táo bạo","hl":[]},{"key":"B","text":"Có biểu hiện chủ quan trong việc đánh giá tình hình, đề ra yêu cầu chưa sát với thực tế","hl":["Có biểu hiện chủ quan trong"]},{"key":"C","text":"Các trận đánh không có ý nghĩa chiến lược","hl":[]},{"key":"D","text":"Không buộc địch phải xuống thang chiến tranh","hl":[]}],"answer":["B"],"note":""},{"id":"131","question":"Lê Hồng Phong được bầu làm Tổng bí thư tại Đại hội nào của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Đại hội đại biểu toàn quốc lần thứ II","hl":[]},{"key":"B","text":"Đại hội đại biểu toàn quốc lần thứ III","hl":[]},{"key":"C","text":"Đại hội đại biểu toàn quốc lần thứ I","hl":[]},{"key":"D","text":"Đại hội đại biểu toàn quốc lần thứ IV","hl":[]}],"answer":["C"],"note":""},{"id":"132","question":"Đâu là lực lượng tạo nên động lực cho cách mạng Việt Nam được nêu ra trong Chính cương của Đảng Lao động Việt Nam? Lực lượng tạo nên động lực cho cách mạng Việt Nam được nêu ra trong Chính cương của Đảng Lao động Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Công nhân, nông dân, tiểu tư sản, tư sản dân tộc, địa chủ yêu nước","hl":[]},{"key":"B","text":"Công nhân, nông dân, lao động trí thức","hl":[]},{"key":"C","text":"Công nhân, trí thức, tư sản dân tộc","hl":[]},{"key":"D","text":"Địa chủ, tư sản dân tộc e. Công nhân, nông dân, tiểu tư sản, tư sản dân tộc, đại địa chủ","hl":[]}],"answer":["A"],"note":""},{"id":"133","question":"Tổ chức Cộng sản nào ra đời đầu tiên ở Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"Hội Việt Nam cách mạng Thanh Niên","hl":[]},{"key":"B","text":"Đông Dương Cộng sản Đảng","hl":[]},{"key":"C","text":"An Nam Cộng sản đảng","hl":[]},{"key":"D","text":"Đông Dương Cộng sản liên đoàn","hl":[]}],"answer":["B"],"note":""},{"id":"134","question":"Giai cấp công nhân Việt Nam ra đời từ :","qHighlight":[],"options":[{"key":"A","text":"Cuộc khai thác thuộc địa lần thứ nhất của thực dân Pháp","hl":[]},{"key":"B","text":"Cuôc khai thác thuộc địa lần thứ hai của thực dân Pháp","hl":[]},{"key":"C","text":"Cuộc xâm lược lần thứ nhất của thực dân Pháp","hl":[]},{"key":"D","text":"Cuộc xâm lược lần thứ hai của thực dân Pháp","hl":[]}],"answer":["A"],"note":""},{"id":"135","question":"Sự kiện nào được Nguyễn Ái Quốc đánh giá \"Nó là quả trứng, mà từ đó nở ra con chim non Cộng sản\"?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng tháng Mười Nga bùng nổ và thắng lợi","hl":[]},{"key":"B","text":"Sự thành lập Đảng cộng sản Pháp","hl":[]},{"key":"C","text":"Vụ mưu sát tên toàn quyền Méc lanh (Pháp) của Phạm Hồng Thái","hl":[]},{"key":"D","text":"Sự thành lập Hội Việt Nam cách mạng thanh niên","hl":[]}],"answer":["D"],"note":""},{"id":"136","question":"Đâu là luận điểm sáng tạo của Hồ Chí Minh khi vận dụng chủ nghĩa Mác - Lênin về việc ra đời của Đảng Cộng sản Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"Đảng Cộng sản Việt Nam ra đời là tất yếu lịch sử, nó là sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào công nhân Việt Nam.","hl":[]},{"key":"B","text":"Đảng Cộng sản Việt Nam ra đời là tất yếu lịch sử, nó là sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào yêu nước Việt Nam.","hl":[]},{"key":"C","text":"Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước của nhân dân Việt Nam.","hl":[]},{"key":"D","text":"Đảng Cộng sản Việt Nam là sản phẩm của sự kết hợp phong trào công nhân và phong trào yêu nước Việt Nam.","hl":[]}],"answer":["C"],"note":""},{"id":"137","question":"Tổng bí thư đầu tiên của nước ta là :","qHighlight":[],"options":[{"key":"A","text":"Trần Phú","hl":[]},{"key":"B","text":"Nguyễn Văn Cừ","hl":[]},{"key":"C","text":"Trường Chinh","hl":[]},{"key":"D","text":"Lê Hồng Phong","hl":[]}],"answer":["A"],"note":""},{"id":"138","question":"Hội nghị Ban Chấp hành Trung ương Đảng Cộng sản Việt Nam (10-1930) đã đổi tên đảng thành :","qHighlight":[],"options":[{"key":"A","text":"Đông Dương Cộng sản Đảng","hl":[]},{"key":"B","text":"Đảng Lao động Việt Nam","hl":[]},{"key":"C","text":"Đảng Cộng sản Đông Dương","hl":[]},{"key":"D","text":"Đảng An Nam","hl":[]}],"answer":["C"],"note":""},{"id":"139","question":"Kết quả lớn nhất mà quân và dân ta đạt được trong chiến dịch Việt Bắc - Thu Đông 1947 là","qHighlight":[],"options":[{"key":"A","text":"Đánh bại âm mưu, kế hoạch đánh nhanh thắng nhanh của thực dân Pháp","hl":[]},{"key":"B","text":"Tiêu diệt bộ phận lớn sinh lực địch","hl":[]},{"key":"C","text":"Bộ đội chủ lực ta trưởng thành, lớn mạnh","hl":[]},{"key":"D","text":"Đẩy quân Pháp vào thế bị động trên chiến trường","hl":[]}],"answer":["A"],"note":""},{"id":"140","question":"Một trong những tổ chức Cộng sản ra đời ở Việt Nam năm 1929 là:","qHighlight":[],"options":[{"key":"A","text":"Hội Việt Nam cách mạng Thanh Niên","hl":[]},{"key":"B","text":"Việt Nam Quốc dân đảng","hl":[]},{"key":"C","text":"Tân Việt Cách mạng đảng","hl":[]},{"key":"D","text":"Đông Dương Cộng sản đảng","hl":[]}],"answer":["D"],"note":""},{"id":"141","question":"Trước sự xâm lược của thực dân Pháp, phong trào yêu nước do Việt Nam quốc dân Đảng khởi xướng theo khuynh hướng nào sau đây:","qHighlight":["của thực dân Pháp,"],"options":[{"key":"A","text":"Khuynh hướng phong kiến","hl":[]},{"key":"B","text":"Khuynh hướng vô sản","hl":[]},{"key":"C","text":"Khuynh hướng dân chủ tư sản","hl":[]},{"key":"D","text":"Khuynh hướng tiểu tư sản","hl":[]}],"answer":["C"],"note":""},{"id":"142","question":"Thành phần nào dưới đây trở thành giai cấp, tầng lớp bị trị dưới thời Pháp thuộc?","qHighlight":[],"options":[{"key":"A","text":"Công nhân và nông dân","hl":[]},{"key":"B","text":"Công nhân, nông dân, tiểu tư sản","hl":[]},{"key":"C","text":"Công nhân, nông dân, tiểu tư sản, tư sản dân tộc","hl":[]},{"key":"D","text":"Công nhân, nông dân, tiểu tư sản, tư sản dân tộc, địa chủ nhỏ và vừa","hl":["dân, tiểu tư sản, tư sản dân tộc, địa chủ nhỏ và vừa"]}],"answer":["D"],"note":""},{"id":"143","question":"Trong cuộc khai thác thuộc địa lần thứ nhất của thực dân Pháp (1897 - 1913) ở Việt Nam đã xuất hiện những giai cấp, tầng lớp mới nào?","qHighlight":["Trong"],"options":[{"key":"A","text":"Địa chủ và nông dân","hl":[]},{"key":"B","text":"Tư sản, tiểu tư sản và công nhân","hl":[]},{"key":"C","text":"Địa chủ, nông dân và công nhân","hl":[]},{"key":"D","text":"Nông dân và tiểu tư sản","hl":[]}],"answer":["B"],"note":""},{"id":"130","question":"Trước cuộc khai thác thuộc địa lần thứ nhất của thực dân Pháp (1897 - 1913) ở Việt Nam có những giai cấp nào?","qHighlight":["Trước"],"options":[{"key":"A","text":"Địa chủ và nông dân","hl":[]},{"key":"B","text":"Địa chủ, nông dân, tư sản, tiểu tư sản và công nhân","hl":[]},{"key":"C","text":"Địa chủ, nông dân và công nhân","hl":[]},{"key":"D","text":"Nông dân và tiểu tư sản","hl":[]}],"answer":["A"],"note":""},{"id":"144","question":"Ai là Tư lệnh Chiến dịch Hồ Chí Minh giải phóng Sài Gòn - Gia Định tháng 4/1975?","qHighlight":[],"options":[{"key":"A","text":"Lê Trọng Tấn","hl":[]},{"key":"B","text":"Văn Tiến Dũng","hl":[]},{"key":"C","text":"Trần Văn Trà","hl":[]},{"key":"D","text":"Hoàng Văn Thái","hl":[]}],"answer":["B"],"note":""},{"id":"145","question":"Hội nghị Trung ương 6 (8/1979) được coi là bước đột phá đầu tiên của Đảng trong lĩnh vực:","qHighlight":[],"options":[{"key":"A","text":"Đổi mới kinh tế","hl":[]},{"key":"B","text":"Đổi mới hệ thống chính trị","hl":[]},{"key":"C","text":"Đổi mới đường lối đối ngoại","hl":[]},{"key":"D","text":"Đổi mới đường lối văn hóa văn nghệ","hl":[]}],"answer":["A"],"note":""},{"id":"146","question":"Trong phong trào yêu nước chống Thực dân Pháp, giai cấp nào được coi là động lực của cách mạng?","qHighlight":[],"options":[{"key":"A","text":"Nông dân","hl":[]},{"key":"B","text":"Công nhân","hl":[]},{"key":"C","text":"Tư sản","hl":[]},{"key":"D","text":"Tiểu tư sản","hl":[]}],"answer":["A"],"note":""},{"id":"147","question":"Đảng Cộng sản Việt Nam ra đời là :","qHighlight":[],"options":[{"key":"A","text":"Tất yếu lịch sử, nó là sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào công nhân Việt Nam.","hl":[]},{"key":"B","text":"Sản phẩm kết hợp giữa chủ nghĩa Mác với phong trào yêu nước Việt Nam.","hl":[]},{"key":"C","text":"Sản phẩm của sự kết hợp chủ nghĩa Mác-Lênin với phong trào công nhân và phong trào yêu nước","hl":[]},{"key":"D","text":"Sự kết hợp phong trào công nhân và phong trào yêu nước Việt Nam.","hl":[]}],"answer":["C"],"note":""},{"id":"148","question":"Vào tháng 10/1923, Nguyễn Ái Quốc đến Liên Xô tham dự đại hội của :","qHighlight":[],"options":[{"key":"A","text":"Quốc tế Vô sản","hl":[]},{"key":"B","text":"Quốc tế Nông dân","hl":[]},{"key":"C","text":"Liên hiệp các nước thuộc địa","hl":[]}],"answer":["B"],"note":""},{"id":"149","question":"Nguyễn Ái Quốc đã thành lập Hội Việt Nam cách mạng thanh niên ở đâu?","qHighlight":[],"options":[{"key":"A","text":"Hương Cảng (Trung Quốc)","hl":[]},{"key":"B","text":"Quảng Châu (Trung Quốc)","hl":[]},{"key":"C","text":"Thượng Hải (Trung Quốc)","hl":[]},{"key":"D","text":"Cao Bằng (Việt Nam)","hl":[]}],"answer":["B"],"note":""},{"id":"150","question":"Sự kiện nào đánh dấu Nguyễn Ái Quốc bước đầu tìm thấy con đường cứu nước đúng đắn cho dân tộc?","qHighlight":[],"options":[{"key":"A","text":"Nguyễn Ái Quốc đưa yêu sách đến Hội nghị Véc-xai (18/6/1919).","hl":[]},{"key":"B","text":"Nguyễn Ái Quốc tham gia sáng lập Đảng Cộng sản Pháp (25/12/1925).","hl":[]},{"key":"C","text":"Nguyễn Ái Quốc đọc bản Sơ thảo lần thứ nhất những Luận cương về vấn đề dân tộc và vấn đề thuộc địa của Lênin (7/1920).","hl":[]},{"key":"D","text":"Nguyễn Ái Quốc thành lập tổ chức Hội Việt Nam Cách mạng Thanh niên (6/1925).","hl":[]}],"answer":["C"],"note":""},{"id":"151","question":"Sự kiện tháng 6-1924 gắn với hoạt động của Nguyễn Ái Quốc ở Liên Xô, đó là:","qHighlight":[],"options":[{"key":"A","text":"Người dự Đại hội Quốc tế Nông dân.","hl":[]},{"key":"B","text":"Người dự Đại hội lần thứ V của Quốc tế Cộng sản.","hl":[]},{"key":"C","text":"Người dự Đại hội Quốc tế Phụ nữ.","hl":[]},{"key":"D","text":"Người dự Đại hội lần thứ VII của Quốc tế Cộng sản.","hl":[]}],"answer":["B"],"note":""},{"id":"152","question":"Hoạt động của Phan Bội Châu, Phan Châu Trinh và một số người sống ở nước ngoài có tác dụng quan trọng nhất là:","qHighlight":[],"options":[{"key":"A","text":"Mở mang dân trí.","hl":[]},{"key":"B","text":"Tìm được con đường cứu nước cho dân tộc.","hl":[]},{"key":"C","text":"Góp phần cải thiện đời sống của nhân dân.","hl":[]},{"key":"D","text":"Cổ vũ, thức tỉnh lòng yêu nước của nhân dân ta.","hl":[]}],"answer":["D"],"note":""},{"id":"153","question":"Lực lượng chính của cách mạng được xác định trong Luận cương chính trị (10-1930) là :","qHighlight":[],"options":[{"key":"A","text":"Công nhân và nông dân","hl":[]},{"key":"B","text":"Toàn thể nhân dân","hl":[]},{"key":"C","text":"Nông dân và tiểu tư sản","hl":[]},{"key":"D","text":"Nông dân và tư sản dân tộc","hl":[]}],"answer":["A"],"note":""},{"id":"154","question":"Hoạt động chủ yếu nhất của Hội Việt Nam Cách mạng Thanh niên là :","qHighlight":[],"options":[{"key":"A","text":"Xuất bản báo Thanh niên làm cơ quan tuyên truyền của Hội","hl":[]},{"key":"B","text":"Thực hiện chủ trương \"vô sản hóa\"","hl":[]},{"key":"C","text":"Mở lớp huấn luyện chính trị, đào tạo cán bộ cách mạng.","hl":[]},{"key":"D","text":"Thành lập cơ sở trong nước.","hl":[]}],"answer":["C"],"note":""},{"id":"155","question":"Kẻ thù chủ yếu của xã hội Việt Nam trong thời kì 1930-1931 là :","qHighlight":[],"options":[{"key":"A","text":"Thực dân Pháp","hl":[]},{"key":"B","text":"Địa chủ phong kiến","hl":[]},{"key":"C","text":"Đế quốc và phong kiến","hl":[]},{"key":"D","text":"Địa chủ phong kiến, tư sản","hl":[]}],"answer":["C"],"note":""},{"id":"156","question":"Nhiệm vụ của cách mạng Việt Nam được xác định trong Luận cương chính trị tháng 10/1930 do Trần Phú soạn thảo là :","qHighlight":[],"options":[{"key":"A","text":"đánh đổ phong kiến và đế quốc","hl":[]},{"key":"B","text":"giải phóng dân tộc.","hl":[]},{"key":"C","text":"đánh đổ đế quốc và tay sai","hl":[]},{"key":"D","text":"đánh đổ đế quốc Pháp, phong kiến và tư sản phản cách mạng, làm cho nước Việt Nam độc lập tự do.","hl":[]}],"answer":["A"],"note":""},{"id":"157","question":"Mặt trận dân tộc thống nhất phản đế Đông Dương được thành lập vài thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"10-1930","hl":[]},{"key":"B","text":"5-1935","hl":[]},{"key":"C","text":"11-1939","hl":[]},{"key":"D","text":"5-1941","hl":[]}],"answer":["C"],"note":""},{"id":"158","question":"Điều kiện nào không tạo ra khả năng đấu tranh công khai, hợp pháp cho phong trào vận động dân chủ Đông Dương (1936- 1939)?","qHighlight":[],"options":[{"key":"A","text":"Nguy cơ chiến tranh thế giới, chủ trương của Quốc tế cộng sản và Mặt trận bình dân Pháp lên cầm quyền.","hl":[]},{"key":"B","text":"Chủ trương chuyển hướng chiến lược cách mạng của Quốc tế cộng sản và tình hình thế giới có nhiều thay đổi thuận lợi cho cách mạng.","hl":[]},{"key":"C","text":"Mặt trận nhân dân Pháp lên cầm quyền và những thay đổi trong xã hội Việt Nam.","hl":[]},{"key":"D","text":"Mặt trận nhân dân Pháp tan vỡ, chính quyền thực dân Pháp ở Việt Nam thi hành chính sách phát xít.","hl":[]}],"answer":["D"],"note":""},{"id":"159","question":"Ngày 18/3/1975, Bộ Chính trị quyết định:","qHighlight":[],"options":[{"key":"A","text":"Giải phóng miền Nam trong năm 1975","hl":[]},{"key":"B","text":"Giải phóng miền Nam trong hai năm 1975 - 1976","hl":[]},{"key":"C","text":"Giải phóng miền Nam trong tháng 4 năm 1975","hl":[]},{"key":"D","text":"Giải phóng miền Nam trước mùa mưa năm 1975","hl":[]}],"answer":["D"],"note":""},{"id":"160","question":"Nội dung nào sau đây nằm trong Cương lĩnh cách mạng đầu tiên của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Đánh đổ đế quốc chủ nghĩa Pháp và bọn phong kiến, làm cho nước Nam hoàn toàn độc lập","hl":[]},{"key":"B","text":"Tư sản dân quyền cách mạng là thời kỳ dự bị để làm xã hội cách mạng","hl":[]},{"key":"C","text":"Chỉ có giải phóng giai cấp vô sản mới giải phóng được dân tộc","hl":[]},{"key":"D","text":"Đảng có vững cách mạng mới thành công","hl":[]}],"answer":["A"],"note":""},{"id":"161","question":"Qua thực tế lãnh đạo phong trào cách mạng 1930-1931, Đảng ta đã trưởng thành nhanh chóng. Do đó, tháng 4/1931 Đảng ta được Quốc tế Cộng sản công nhận:","qHighlight":[],"options":[{"key":"A","text":"Là một chi bộ của Quốc tế Cộng sản","hl":[]},{"key":"B","text":"Là một bộ phận không thể tách rời của Quốc tế Cộng sản","hl":[]},{"key":"C","text":"Là một chính đảng của cách mạng Đông Dương","hl":[]},{"key":"D","text":"Là một Đảng của giai cấp công nhân Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"162","question":"Trong phong trào cách mạng nước ta, giai cấp nào sẽ là lực lượng lãnh đạo cách mạng?","qHighlight":[],"options":[{"key":"A","text":"Nông dân","hl":[]},{"key":"B","text":"Công nhân","hl":[]},{"key":"C","text":"Tư sản","hl":[]},{"key":"D","text":"Tiểu tư sản","hl":[]}],"answer":["B"],"note":""},{"id":"163","question":"Hạn chế lớn nhất của Luận cương chính trị tháng 10 năm 1930 là gì?","qHighlight":[],"options":[{"key":"A","text":"Đánh giá không đúng khả năng cách mạng của giai cấp nông dân","hl":[]},{"key":"B","text":"Không đưa ngọn cờ giải phóng dân tộc lên hàng đầu, nặng về đấu tranh giai cấp","hl":["Không đưa ngọn cờ giải phóng dân tộc lên hàng"]},{"key":"C","text":"Xác định động lực cách mạng là giai cấp công nhân, nông dân, tiểu tư sản trí thức","hl":[]},{"key":"D","text":"Cách mạng Đông Dương lúc đầu là cách mạng tư sản dân quyền bỏ qua thời kì tư bản chủ nghĩa, tiến thẳng lên con đường xã hội chủ nghĩa","hl":[]}],"answer":["B"],"note":"Mẹo nhớ: Hạn chế lớn nhất của Luận cương 10/1930 là KHÔNG đưa ngọn cờ giải phóng dân tộc lên hàng đầu"},{"id":"164","question":"Hội nghị trung ương VIII tháng 5/1941 đề ra chủ trương gì? Hội nghị trung ương VIII tháng 5/1941 chủ trương gì?","qHighlight":[],"options":[{"key":"A","text":"Thành lập nước Cộng hòa xã hội chủ nghĩa Việt Nam","hl":[]},{"key":"B","text":"Thành lập nước Việt Nam cộng hòa dân chủ","hl":[]},{"key":"C","text":"Thành lập nước dân chủ cộng hòa Việt Nam","hl":[]},{"key":"D","text":"Thành lập nước Việt Nam dân chủ cộng hòa","hl":[]}],"answer":["D"],"note":""},{"id":"165","question":"Sự kiện lịch sử nào dưới đây diễn ra trong phong trào dân tộc dân chủ ở Việt Nam từ 1925 đến 1930?","qHighlight":[],"options":[{"key":"A","text":"Bãi công của công nhân Ba Son","hl":[]},{"key":"B","text":"Bãi công của công nhân Vinh-Bến Thủy","hl":[]},{"key":"C","text":"Phong trào Đông Dương đại hội","hl":[]},{"key":"D","text":"Phong trào phá kho thóc của Nhật","hl":[]}],"answer":["A"],"note":"Bãi công công nhân Ba Son diễn ra tháng 8/1925 (thuộc giai đoạn 1925-1930)"},{"id":"166","question":"Nhân dân Việt Nam thực hiện nhiệm vụ chống chế độ phản động thuộc địa, chống phát xít, chống chiến tranh trong phong trào nào sau đây?","qHighlight":[],"options":[{"key":"A","text":"Phong trào cách mạng 1930-1931.","hl":[]},{"key":"B","text":"Phong trào dân chủ 1936-1939.","hl":[]},{"key":"C","text":"Phong trào dân tộc dân chù 1919-1925.","hl":[]},{"key":"D","text":"Phong trào dân tộc dân chù 1925-1930.","hl":[]}],"answer":["B"],"note":""},{"id":"167","question":"Hội nghị lần thứ 8 Ban chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) đã nhấn mạnh nhiệm vụ trọng tâm của toàn Đảng, toàn dân là :","qHighlight":[],"options":[{"key":"A","text":"Xây dựng lực lượng chính trị","hl":[]},{"key":"B","text":"Xây dựng lực lượng vũ trang","hl":[]},{"key":"C","text":"Chuẩn bị khởi nghĩa","hl":[]},{"key":"D","text":"Khởi nghĩa từng phần","hl":[]}],"answer":["C"],"note":""},{"id":"168","question":"Đảng Cộng sản Đông Dương quyết định chuyển hướng đấu tranh, đặt nhiệm vụ giải phóng dân tộc lên hàng đầu trong thời kì 1939-1945 là do :","qHighlight":[],"options":[{"key":"A","text":"Chiến tranh thế giới thứ hai bùng nổ","hl":[]},{"key":"B","text":"Pháp ra sức vơ vét, bóc lột nhân dân","hl":[]},{"key":"C","text":"Phát xít Nhật vào miền Bắc Việt Nam","hl":[]},{"key":"D","text":"Mâu thuẫn với Pháp-Nhật trở nên gay gắt","hl":[]}],"answer":["D"],"note":""},{"id":"169","question":"Hội nghị Ban chấp hành Trung ương Đảng Cộng sản Đông Dương (7-1936) đã chủ trương thành lập :","qHighlight":[],"options":[{"key":"A","text":"Mặt trận thống nhất dân chủ Đông Dương","hl":[]},{"key":"B","text":"Mặt trận Việt Nam độc lập Đồng minh","hl":[]},{"key":"C","text":"Mặt trận thống nhất dân tộc phản đế Đông Dương","hl":[]},{"key":"D","text":"Mặt trận thống nhất nhân dân phản đế Đông Dương","hl":[]}],"answer":["D"],"note":""},{"id":"170","question":"Nhiệm vụ cách mạng được cương lĩnh xác định là :","qHighlight":[],"options":[{"key":"A","text":"Đánh đổ phong kiến, đánh đổ đế quốc, 2 nhiệm vụ có quan hệ mật thiết khăng khít với nhau.","hl":[]},{"key":"B","text":"Đánh đổ đế quốc Pháp và tư sản phản cách mạng","hl":[]},{"key":"C","text":"Đánh đổ đế quốc Pháp, phong kiến, tư sản phản cách mạng làm cho nước nhà độc lập.","hl":["đổ đế quốc Pháp, phong"]},{"key":"D","text":"Đánh đuổi đế quốc Pháp","hl":[]}],"answer":["C"],"note":""},{"id":"171","question":"Lực lượng chủ yếu tham gia phong trào cách mạng 1930-1931 ở Việt Nam là :","qHighlight":[],"options":[{"key":"A","text":"Tiểu tư sản, công nhân","hl":[]},{"key":"B","text":"Nông dân, tiểu tư sản","hl":[]},{"key":"C","text":"Công nhân và nông dân","hl":[]},{"key":"D","text":"Nông dân, tư sản dân tộc.","hl":[]}],"answer":["C"],"note":""},{"id":"172","question":"Căn cứ địa cách mạng đầu tiên của Việt Nam trong giai đoạn 1939-1945 là :","qHighlight":[],"options":[{"key":"A","text":"Cao Bằng","hl":[]},{"key":"B","text":"Bắc Sơn - Võ Nhai","hl":["Sơn - Võ Nhai"]},{"key":"C","text":"Thái Nguyên","hl":[]},{"key":"D","text":"Tuyên Quang","hl":[]}],"answer":["B"],"note":""},{"id":"173","question":"Lực lượng cách mạng được nêu ra trong Luận cương chính trị (tháng 10-1930) của Đảng Cộng sản Đông Dương là :","qHighlight":[],"options":[{"key":"A","text":"Công nhân, nông dân và tư sản","hl":[]},{"key":"B","text":"Nông dân và tiểu tư sản","hl":[]},{"key":"C","text":"Công nhân, nông dân","hl":["nhân, nông dân"]},{"key":"D","text":"Công nhân, nông dân và trí thức","hl":[]}],"answer":["C"],"note":""},{"id":"174","question":"Trong phong trào dân chủ 1936-1939, Nhân dân Việt Nam thực hiện một trong những nhiệm vụ trực tiếp, trước mắt là đấu tranh chống :","qHighlight":[],"options":[{"key":"A","text":"Chế độ phản động thuộc địa","hl":[]},{"key":"B","text":"Đế quốc và chế độ phong kiến","hl":[]},{"key":"C","text":"Tư sản và địa chủ","hl":[]},{"key":"D","text":"Đế quốc và tư sản","hl":[]}],"answer":["A"],"note":""},{"id":"175","question":"Đường lối kháng chiến chống thực dân Pháp thể hiện tập trung trong ba văn kiện quan trọng, đó là:","qHighlight":[],"options":[{"key":"A","text":"Toàn dân kháng chiến, Lời kêu gọi toàn quốc kháng chiến, Kháng chiến nhất định thắng lợi","hl":[]},{"key":"B","text":"Nhật - Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc, Kháng chiến nhất định thắng lợi","hl":[]},{"key":"C","text":"Toàn dân kháng chiến, Nhật - Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc","hl":[]},{"key":"D","text":"Lời kêu gọi toàn quốc kháng chiến, Nhật - Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc","hl":[]}],"answer":["A"],"note":""},{"id":"176","question":"Một trong những nội dung của chương trình hành động của Đảng Cộng sản Đông Dương là :","qHighlight":[],"options":[{"key":"A","text":"Cải cách ruộng đất","hl":[]},{"key":"B","text":"Cải cách giáo dục","hl":[]},{"key":"C","text":"Đòi tự do, bình đẳng","hl":[]},{"key":"D","text":"Đòi quyền tự do: Phát ngôn, tự do đi lại v.v.","hl":[]}],"answer":["D"],"note":""},{"id":"177","question":"Nội dung Cương lĩnh chính trị đầu tiên (2/1930) của Đảng thể hiện trong:","qHighlight":[],"options":[{"key":"A","text":"2 văn kiện","hl":[]},{"key":"B","text":"3 văn kiện","hl":[]},{"key":"C","text":"4 văn kiện","hl":[]},{"key":"D","text":"5 văn kiện","hl":[]}],"answer":["C"],"note":""},{"id":"178","question":"Hội nghị lần thứ 8 Ban chấp hành Trung ương Đảng Cộng sản Đông Dương (5/1941) quyết định hình thức chính quyền sau cách mạng ở Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Chính phủ cách mạng lâm thời","hl":[]},{"key":"B","text":"Chính phủ Việt Nam Dân chủ Cộng hòa","hl":[]},{"key":"C","text":"Chính phủ Xô viết công-nông-binh","hl":[]},{"key":"D","text":"Chính phủ dân chủ Cộng hòa Đông Dương","hl":[]}],"answer":["B"],"note":""},{"id":"179","question":"Sự kiện nào dưới đây đánh dấu khuynh hướng cách mạng vô sản giành quyền lãnh đạo đối với cách mạng Việt Nam ?","qHighlight":[],"options":[{"key":"A","text":"Hội Việt Nam Cách mạng thanh niên ra đời","hl":[]},{"key":"B","text":"Tân Việt Cách mạng đảng bị phân hoá.","hl":[]},{"key":"C","text":"Sự ra đời của ba tổ chức cộng sản","hl":[]},{"key":"D","text":"Đảng Cộng sản Việt Nam được thành lập.","hl":["thành"]}],"answer":["D"],"note":""},{"id":"180","question":"Vì sao trong những năm 1939-1941 Đảng Cộng sản Đông Dương lại phải chuyển hướng chiến lược đấu tranh cách mạng?","qHighlight":[],"options":[{"key":"A","text":"Do sự biến đổi mau lẹ của tình hình thế giới","hl":[]},{"key":"B","text":"Do chính sách thống trị của Pháp - Nhật","hl":[]},{"key":"C","text":"Do yêu cầu của sự nghiệp giải phóng dân tộc đặt ra cấp thiết.","hl":["của sự nghiệp giải phóng dân tộc"]},{"key":"D","text":"Do yêu cầu giải quyết vấn đề dân tộc trong khuôn khổ từng nước Đông Dương","hl":[]}],"answer":["C"],"note":""},{"id":"181","question":"Vì sao trong thời kỳ đổi mới đất nước nhưng vẫn phải tiếp tục xây dựng giai cấp công nhân Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"Giai cấp công nhân là động lực phát triển kinh tế","hl":[]},{"key":"B","text":"Giai cấp công nhân đại diện cho phương thức sản xuất hiện đại","hl":[]},{"key":"C","text":"Giai cấp lãnh đạo cách mạng thông qua đội tiên phong là Đảng Cộng sản Việt Nam, là giai cấp đại diện cho phương thức sản xuất tiên bộ","hl":[]},{"key":"D","text":"Giai cấp s","hl":[]}],"answer":["D"],"note":"Lưu ý: Đáp án D trong bản gốc docx bị cắt chữ (\"Giai cấp s\") — xem câu 403 để đọc đầy đủ ý."},{"id":"182","question":"Sự khác biệt cơ bản giữa phong trào đấu tranh của nhân dân Việt Nam từ năm 1939 đến trước ngày 9-3-1945 với các phong trào cách mạng trước đó là gì?","qHighlight":[],"options":[{"key":"A","text":"Chống lại nền thống trị của đế quốc phát xít Pháp - Nhật","hl":[]},{"key":"B","text":"Nhiệm vụ giải phóng dân tộc đặt ra cấp thiết","hl":[]},{"key":"C","text":"Mâu thuẫn dân tộc phát triển gay gắt","hl":[]},{"key":"D","text":"Có sự liên kết với quốc tế","hl":[]}],"answer":["B"],"note":""},{"id":"183","question":"Tổng kết thành tựu 35 năm lãnh đạo công cuộc Đổi mới, Đại hội XIII của Đảng (1/2021) khẳng định:","qHighlight":[],"options":[{"key":"A","text":"Đất nước ta chưa bao giờ giàu mạnh như ngày nay","hl":[]},{"key":"B","text":"Đất nước ta đã cơ bản hoàn thành sự nghiệp công nghiệp hóa, hiện đại hóa","hl":[]},{"key":"C","text":"Đất nước ta chưa bao giờ có được cơ đồ, tiềm lực, vị thế và uy tín quốc tế như ngày nay","hl":[]},{"key":"D","text":"Đất nước ta đã trở thành một nước công nghiệp hiện đại, theo định hướng xã hội chủ nghĩa","hl":[]}],"answer":["C"],"note":""},{"id":"184","question":"Công lao to lớn đầu tiên của Nguyễn Ái Quốc đối với cách mạng Việt Nam là gì?","qHighlight":[],"options":[{"key":"A","text":"Tìm được con đường cứu nước đúng đắn","hl":[]},{"key":"B","text":"Thành lập Hội Việt Nam Cách mạng thanh niên","hl":[]},{"key":"C","text":"Chủ trì Hội nghị thành Đảng cộng sản Việt Nam","hl":[]},{"key":"D","text":"Thành lập một","hl":[]}],"answer":["A"],"note":""},{"id":"185","question":"Mối quan hệ giữa hai khẩu hiệu: \"Độc lập dân tộc và \"Ruộng đất cho dân cày được giải quyết như thế nào trong thời kì 1939 - 1945?","qHighlight":[],"options":[{"key":"A","text":"Tạm gác lại khẩu hiệu cách mạng ruộng đất.","hl":[]},{"key":"B","text":"Tạm gác lại khẩu hiệu cách mạng giải phóng dân tộc.","hl":[]},{"key":"C","text":"Tiếp tục thực hiện hai khẩu hiệu trên một cách đồng bộ.","hl":[]},{"key":"D","text":"Tạm gác lại việc thực hiện hai khẩu hiệu trên.","hl":[]}],"answer":["A"],"note":""},{"id":"186","question":"Nhận xét nào sau đây là phù hợp về Hội Việt Nam cách mạng Thanh niên (1925-1929)?","qHighlight":[],"options":[{"key":"A","text":"Một trong những tổ chức cộng sản đầu tiên ở Việt Nam","hl":[]},{"key":"B","text":"Là đội tiên phong của giai cấp công nhân Việt Nam","hl":[]},{"key":"C","text":"Là tổ chức tiền thân của Đảng Cộng sản Việt Nam","hl":[]},{"key":"D","text":"Đại diện tiêu biểu của giai cấp tiểu tư sản Việt Nam","hl":[]}],"answer":["C"],"note":""},{"id":"187","question":"Hiệp định Pari về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết (1973) đã cam kết:","qHighlight":[],"options":[{"key":"A","text":"Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam","hl":[]},{"key":"B","text":"Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam Dân chủ Cộng hòa","hl":[]},{"key":"C","text":"Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của nước Việt Nam Cộng hòa","hl":[]},{"key":"D","text":"Tôn trọng độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ của Cộng hòa Miền Nam Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"188","question":"Nhiệm vụ của cách mạng Việt Nam được xác định trong Cương lĩnh chính trị đầu tiên của Đảng là gì?","qHighlight":[],"options":[{"key":"A","text":"Đánh đổ đế quốc Pháp, làm cho nước Việt Nam hoàn toàn độc lập","hl":[]},{"key":"B","text":"Đánh đổ phong kiến, tay sai, phát triển theo con đường tư bản chủ nghĩa","hl":[]},{"key":"C","text":"Đánh đổ đế quốc Pháp, phong kiến và tư sản phản cách mạng làm cho Việt Nam được độc lập tự do","hl":[]},{"key":"D","text":"Đánh đổ đế quốc Pháp, phong kiến làm cho Việt Nam hoàn toàn độc lập","hl":[]}],"answer":["C"],"note":""},{"id":"189","question":"Chánh cương vắn tắt của Đảng, Sách lược vắn tắt của Đảng do Nguyễn Ái Quốc soạn thảo được thông qua tại Hội nghị thành lập Đảng được xem là:","qHighlight":[],"options":[{"key":"A","text":"Văn kiện của Đảng","hl":[]},{"key":"B","text":"Tài liệu chính trị đặc biệt của Đảng","hl":[]},{"key":"C","text":"Nghị quyết của Đảng Cộng sản Việt Nam","hl":[]},{"key":"D","text":"Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam","hl":[]}],"answer":["D"],"note":""},{"id":"190","question":"So với trước chiến tranh thế giới thứ nhất, phong trào yêu nước Việt Nam trong những năm 1919-1930 có những điểm mới nào sau đây?","qHighlight":["trong những năm 1919-1930 có những điểm mới nào sau đây?"],"options":[{"key":"A","text":"Có hai khuynh hướng cùng tồn tại và phát triển","hl":[]},{"key":"B","text":"Diễn ra dưới tác động của cuộc khai thác thuộc địa của thực dân Pháp","hl":[]},{"key":"C","text":"Giai cấp công nhân nắm lấy vai trò lãnh đạo cách mạng giải phóng dân tộc","hl":[]},{"key":"D","text":"Cách mạng Việt Nam nhận được sự ủng hộ, giúp đỡ của Liên Xô, Trung Quốc","hl":[]}],"answer":["A"],"note":""},{"id":"191","question":"Điểm khác biệt và độc đáo nhất của Nguyễn Ái Quốc trong hành trình tìm đường cứu nước so các tiền bối khác ?","qHighlight":[],"options":[{"key":"A","text":"Hướng đi và cách tiếp cận chân lý.","hl":[]},{"key":"B","text":"Từ yêu nước đến chủ nghĩa Mác -Lê nin.","hl":[]},{"key":"C","text":"Gắn độc lập dân tộc với vấn đề ruộng đất","hl":[]},{"key":"D","text":"Dự đoán chính xác thời cơ cách mạng.","hl":[]}],"answer":["A"],"note":""},{"id":"192","question":"So với phong trào 1930 - 1931, điểm khác biệt về phương pháp đấu tranh của thời kì 1936 - 1939 là kết hợp đấu tranh :","qHighlight":[],"options":[{"key":"A","text":"Chính trị và vũ trang","hl":[]},{"key":"B","text":"Nghị trường và đấu tranh báo chí.","hl":[]},{"key":"C","text":"Công khai và bí mật","hl":[]},{"key":"D","text":"Ngoại giao với vận động quần chúng","hl":[]}],"answer":["C"],"note":""},{"id":"193","question":"Khi nói về triển vọng của cuộc kháng chiến chống Pháp, Đảng xác định trong Đường lối kháng chiến là :","qHighlight":[],"options":[{"key":"A","text":"Mặc dù lâu dài, gian khổ, khó khăn song nhất định thắng lợi","hl":[]},{"key":"B","text":"Mặc dù phải hy sinh to lớn đến đâu nhưng nhất định sẽ thành công","hl":[]},{"key":"C","text":"Mặc dù bị bao vây và chưa được nước nào trên thế giới công nhận, song nhất định thắng lợi","hl":[]},{"key":"D","text":"Nhờ có sự hy sinh to lớn của dân tộc nên cuộc kháng chiến sẽ thành công","hl":[]}],"answer":["A"],"note":""},{"id":"194","question":"Nguyên nhân căn bản nhất dẫn đến sự thắng lợi của cuộc kháng chiến chống Pháp là :","qHighlight":[],"options":[{"key":"A","text":"Có sự lãnh đạo của Đảng với đường lối kháng chiến đúng.","hl":[]},{"key":"B","text":"Có lực lượng vũ trang gồm 3 thứ quân dũng cảm, mưu lược.","hl":[]},{"key":"C","text":"Có chính quyền dân chủ nhân dân tổ chức toàn dân kháng chiến và xây dựng chế độ mới.","hl":[]},{"key":"D","text":"Có liên minh đoàn kết chiến đấu Việt Nam, Lào, Campuchia","hl":[]}],"answer":["A"],"note":""},{"id":"195","question":"Đại hội Đảng lần thứ II xác định nhiệm vụ của cách mạng Việt Nam là :","qHighlight":[],"options":[{"key":"A","text":"Đánh đuổi bọn đế quốc xâm lược, xóa bỏ những di tích phong kiến và nửa phong kiến, phát triển chế độ dân chủ nhân dân","hl":[]},{"key":"B","text":"Đánh đuổi bọn đế quốc xâm lược, giành độc lập thống nhất thật sự cho dân tộc, gây cơ sở cho chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Đánh đuổi bọn đế quốc xâm lược, giành độc lập thống nhất thật sự cho dân tộc, làm cho người cày có ruộng, phát triển chế độ dân chủ nhân dân","hl":[]},{"key":"D","text":"Làm cho người cày có ruộng, gây cơ sở cho chủ nghĩa xã hội, phát triển chế độ dân chủ nhân dân","hl":[]}],"answer":["A"],"note":""},{"id":"196","question":"Tại Đại hội lần thứ II Đảng cộng sản Đông Dương quyết định tách ra thành ba Đảng cách mạng ở ba nước Đông Dương. Ở Việt Nam, Đảng ra hoạt động công khai lấy tên là :","qHighlight":[],"options":[{"key":"A","text":"Đảng Lao động Việt Nam","hl":[]},{"key":"B","text":"Đảng Dân chủ Việt Nam","hl":[]},{"key":"C","text":"Đảng Cách mạng Việt Nam","hl":[]},{"key":"D","text":"Đảng Xã hội Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"197","question":"Sự kiện nào đánh dấu Việt Nam thống nhất về mặt Nhà nước sau năm 1975?","qHighlight":[],"options":[{"key":"A","text":"Chiến dịch Hồ Chí Minh toàn thắng (4/1975)","hl":[]},{"key":"B","text":"Hội nghị Hiệp thương chính trị của hai đoàn đại biểu Nam - Bắc (11/1975)","hl":[]},{"key":"C","text":"Tổng tuyển cử bầu Quốc hội khóa VI (4/1976)","hl":[]},{"key":"D","text":"Đại hội Đảng toàn quốc lần thứ IV (12/1976)","hl":[]}],"answer":["C"],"note":""},{"id":"198","question":"Đường lối toàn quốc kháng chiến của Đảng vạch ra mục tiêu của kháng chiến là:","qHighlight":[],"options":[{"key":"A","text":"Đánh phản động thực dân Pháp xâm lược, giành thống nhất và độc lập","hl":["Pháp"]},{"key":"B","text":"Đánh phản động phát xít Nhật xâm lược, giành thống nhất và độc lập","hl":[]},{"key":"C","text":"Đánh phản động đế quốc Mỹ xâm lược, giành thống nhất và độc lập","hl":[]},{"key":"D","text":"Đánh phản động Trung Hoa Dân Quốc xâm lược, giành thống nhất và độc lập","hl":[]}],"answer":["A"],"note":""},{"id":"199","question":"Để thực hiện chính sách \"Tố cộng, diệt cộng\" Ngô Định Diệm đưa ra :","qHighlight":["\"Tố cộng, diệt cộng"],"options":[{"key":"A","text":"Luật 10/59","hl":[]},{"key":"B","text":"Luật nhân quyền","hl":[]},{"key":"C","text":"Luật bình định","hl":[]},{"key":"D","text":"Các phương án trả lời đều đúng","hl":[]}],"answer":["A"],"note":""},{"id":"200","question":"Hội nghị Trung ương Đảng lần thứ 11 tháng 03 năm 1965 và Hội nghị Trung ương Đảng lần thứ 12 tháng 12 năm 1965 đề ra khẩu hiệu chung của nhân dân cả nước là :","qHighlight":[],"options":[{"key":"A","text":"Tất cả để đánh thắng giặc Mỹ xâm lược","hl":[]},{"key":"B","text":"Tất cả để thống nhất nước nhà","hl":[]},{"key":"C","text":"Tất cả vì miền Nam ruột thịt","hl":[]},{"key":"D","text":"Các phương án trả lời đều đúng","hl":[]}],"answer":["A"],"note":""},{"id":"201","question":"Đâu là nhiệm vụ của cách mạng miền Bắc ngay sau khi hiệp định Giơ-ne-vơ năm 1954 về Đông Dương được ký kết? Nhiệm vụ của cách mạng miền bắc ngay sau khi Hiệp định Giơ-ne-vơ năm 1954 về Đông Dương được kí kết là :","qHighlight":[],"options":[{"key":"A","text":"Đấu tranh chống đế quốc Mĩ và chính quyền Ngô Đình Diệm","hl":[]},{"key":"B","text":"Xây dựng cơ sở vật chất kĩ thuật cho chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Hoàn thành cuộc cách mạng dân tộc dân chủ nhân dân","hl":[]},{"key":"D","text":"Hàn gắn vết thương chiến tranh, khôi phục kinh tế","hl":[]}],"answer":["D"],"note":""},{"id":"202","question":"Tại hội nghị nào, Ban Chấp hành Trung ương Đảng quyết định để nhân dân miền Nam sử dụng bạo lực cách mạng đánh đổ chính quyền Mĩ- Diệm?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị Trung ương lần thứ 15 (1-1959)","hl":[]},{"key":"B","text":"Hội nghị Trung ương lần thứ 11 (3-1965)","hl":[]},{"key":"C","text":"Hội nghị Trung ương lần thứ 12 (12-1965)","hl":[]},{"key":"D","text":"Hội nghị Trung ương lần thứ 21 (7/1973)","hl":[]}],"answer":["A"],"note":""},{"id":"203","question":"Đại hội II của Đảng Lao động Việt Nam vạch ra tính chất của xã hội Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Dân chủ nhân dân, một phần thuộc địa và nửa phong kiến","hl":[]},{"key":"B","text":"Dân chủ nhân dân, thuộc địa và nửa phong kiến","hl":[]},{"key":"C","text":"Dân chủ nhân dân và nửa phong kiến","hl":[]},{"key":"D","text":"Một phần thuộc địa và nửa phong kiến","hl":[]}],"answer":["A"],"note":""},{"id":"204","question":"Thắng lợi của cuộc kháng chiến chống Mỹ cứu nước đã cho ta nhiều bài học quý, bài học nào dưới đây là chưa phù hợp với thời kỳ chống Mỹ?","qHighlight":[],"options":[{"key":"A","text":"Giương cao ngọn cờ độc lập dân tộc và dân chủ.","hl":[]},{"key":"B","text":"Kiên định tư tưởng chiến lược tiến công quyết đánh và quyết thắng đế quốc Mỹ xâm lược.","hl":[]},{"key":"C","text":"Thực hiện chiến tranh nhân dân linh hoạt sáng tạo.","hl":[]},{"key":"D","text":"Coi trọng công tác tổ chức, công tác xây dựng Đảng.","hl":[]}],"answer":["A"],"note":""},{"id":"205","question":"Đại hội đại biểu toàn quốc lần thứ hai của Đảng họp tại đâu?","qHighlight":[],"options":[{"key":"A","text":"Cao Bằng","hl":[]},{"key":"B","text":"Bắc Kạn","hl":[]},{"key":"C","text":"Tuyên Quang","hl":[]},{"key":"D","text":"Thái Nguyên","hl":[]}],"answer":["C"],"note":""},{"id":"206","question":"Sự kiện nào mở đầu cho giai đoạn \"dàn hòa với Pháp\" để đẩy nhanh quân Tường về nước thời kỳ 1945 - 1946?","qHighlight":[],"options":[{"key":"A","text":"Pháp ngừng bắn ở Nam Bộ (10/1945)","hl":[]},{"key":"B","text":"Ký Hiệp định Sơ bộ Việt - Pháp (3/1946)","hl":[]},{"key":"C","text":"Chủ tịch Hồ Chí Minh thăm Pháp (5/1946)","hl":[]},{"key":"D","text":"Đàm phán chính thức Việt - Pháp ở Phôngtennơblô (7/1946)","hl":[]}],"answer":["B"],"note":""},{"id":"207","question":"Nhiệm vụ chống giặc dốt sau Cách mạng tháng Tám (1945) thể hiện qua phong trào nào sau đây?","qHighlight":[],"options":[{"key":"A","text":"Toàn dân đưa trẻ đến trường","hl":[]},{"key":"B","text":"Toàn dân tham gia xóa nạn mù chữ","hl":[]},{"key":"C","text":"Bình dân học vụ","hl":[]},{"key":"D","text":"Truyền bá quốc ngữ","hl":[]}],"answer":["C"],"note":""},{"id":"208","question":"Phong trào mà Đảng ta đã vận động nhân dân chống nạn mù chữ diễn ra sau cách mạng tháng Tám năm 1945 là :","qHighlight":[],"options":[{"key":"A","text":"Xây dựng nếp sống văn hoá mới","hl":[]},{"key":"B","text":"Bình dân học vụ","hl":[]},{"key":"C","text":"Bài trừ các tệ nạn xã hội","hl":[]},{"key":"D","text":"Xoá bỏ văn hoá thực dân nô dịch phản động","hl":[]}],"answer":["B"],"note":""},{"id":"209","question":"Để tránh sự chú ý và đàn áp của Pháp, Đảng ta đã tuyên bố tự giải tán vào ngày tháng năm nào và đổi tên là gì?","qHighlight":[],"options":[{"key":"A","text":"2-9-1945- Đảng Cộng sản Đông Dương","hl":[]},{"key":"B","text":"25-11-1945- Hội nghiên cứu Chủ nghĩa Mác-Lênin","hl":[]},{"key":"C","text":"3-2-1946- Đảng Lao động Việt Nam","hl":[]},{"key":"D","text":"11-11-1945- Hội nghiên cứu Chủ nghĩa Mác ở Đông Dương","hl":[]}],"answer":["D"],"note":""},{"id":"210","question":"Bản chỉ thị \"Kháng chiến, kiến quốc\" ngày 25/11/1945 của Trung ương Đảng đã xác định ai là kẻ thù chính của cách mạng Việt Nam lúc này?","qHighlight":[],"options":[{"key":"A","text":"Thực dân Pháp","hl":[]},{"key":"B","text":"Đế quốc Anh","hl":[]},{"key":"C","text":"Bọn quân phiệt quốc dân đảng Trung Hoa","hl":[]},{"key":"D","text":"Phát xít Nhật","hl":[]}],"answer":["A"],"note":""},{"id":"211","question":"Đại hội lần thứ III (9-1960), Đảng Lao động Việt Nam khẳng định nhiệm vụ cách mạng giữ vai trò quyết định nhất đối với sự phát triển cách mạng cả nước là :","qHighlight":[],"options":[{"key":"A","text":"Cách mạng xã hội chủ nghĩa ở miền Bắc","hl":[]},{"key":"B","text":"Cách mạng dân tộc dân chủ nhân dân ở miền Nam","hl":[]},{"key":"C","text":"Cách mạng hai miền đều quyết định như nhau","hl":[]},{"key":"D","text":"Các phương án trả lời đều sai","hl":[]}],"answer":["A"],"note":""},{"id":"213","question":"Sau khi Mỹ thực hiện chiến lược \"Chiến tranh cục bộ\", đảng nhận định tình hình :","qHighlight":[],"options":[{"key":"A","text":"Đây là cuộc chiến tranh xâm lược thực dân mới, buộc phải thực thi trong thế thua, thế thất bại và bị động cho nên nó chứa đựng đầy mâu thuẫn chiến lược","hl":[]},{"key":"B","text":"Đây là cuộc chiến tranh xâm lược thực dân cũ, buộc phải thực thi trong thế thua, thế thất bại và bị động cho nên nó chứa đựng đầy mâu thuẫn chiến lược","hl":[]},{"key":"C","text":"Đây là cuộc chiến tranh xâm lược thực dân hiện đại, buộc phải thực thi trong thế thua, thế thất bại và bị động cho nên nó chứa đựng đầy mâu thuẫn chiến lược","hl":[]}],"answer":["A"],"note":""},{"id":"214","question":"Đầu năm 1953, nhằm cứu vãn tình thế ngày càng xa lầy và tìm kiếm giải pháp chính trị có \"danh dự\", Pháp và Mỹ đã đưa một viên tướng Pháp sang làm tổng chỉ huy quân đội pháp ở Đông Dương và lập kế hoạch quân sự nào?","qHighlight":[],"options":[{"key":"A","text":"Nava","hl":[]},{"key":"B","text":"De Castries","hl":[]},{"key":"C","text":"Salan","hl":[]},{"key":"D","text":"Leclerc","hl":[]}],"answer":["A"],"note":""},{"id":"215","question":"Trong cương lĩnh thứ ba - Chính cương của Đảng Lao động Việt Nam (2/1951), Đảng ta đã khẳng định nhận thức của mình về triển vọng của cách mạng Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Đi tới xã hội cộng sản","hl":[]},{"key":"B","text":"Tiến tới chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Đi tới xã hội dân chủ","hl":[]},{"key":"D","text":"Tiến tới chủ nghĩa tư bản","hl":[]}],"answer":["B"],"note":""},{"id":"216","question":"Mỹ Ngụy không thực thi hiệp định Giơ-ne-vơ bằng cách :","qHighlight":[],"options":[{"key":"A","text":"Ngăn cản hiệp thương, tổng tuyển cử thống nhất đất nước","hl":[]},{"key":"B","text":"Ban hành Luật 10/59","hl":[]},{"key":"C","text":"Thực hiện chiến dịch lập ấp chiến lược","hl":[]},{"key":"D","text":"Các phương án trả lời đều đúng","hl":[]}],"answer":["D"],"note":""},{"id":"217","question":"Nghị quyết về đường lối cách mạng miền Nam được thông qua tại Đại hội nào của Đảng sau đây?","qHighlight":[],"options":[{"key":"A","text":"Đại hội II","hl":[]},{"key":"B","text":"Đại hội III","hl":[]},{"key":"C","text":"Đại hội IV","hl":[]},{"key":"D","text":"Đại hội I","hl":[]}],"answer":["B"],"note":""},{"id":"218","question":"Tình hình nước ta được ví như \"ngàn cân treo sợi tóc\" vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"Ngay sau cách mạng Tháng Tám 1945 thành công","hl":[]},{"key":"B","text":"Trước cách mạng Tháng 8","hl":[]},{"key":"C","text":"Ngay sau cuộc kháng chiến chống Mỹ thắng lợi 1975","hl":[]},{"key":"D","text":"Ngay sau khi Hiệp định Pari được ký kết 1973","hl":[]}],"answer":["A"],"note":""},{"id":"219","question":"Khối liên minh nhân dân ba nước Việt-Lào-Campuchia được thành lập khi nào?","qHighlight":[],"options":[{"key":"A","text":"Tháng 3 năm 1950","hl":[]},{"key":"B","text":"Tháng 3 năm 1953","hl":[]},{"key":"C","text":"Tháng 3 năm 1954","hl":[]},{"key":"D","text":"Tháng 3 năm 1951","hl":[]}],"answer":["D"],"note":""},{"id":"220","question":"Để tranh thủ thời gian chống Pháp, Đảng chủ trương quan hệ với quân Tưởng Giới Thạch theo khẩu hiệu :","qHighlight":[],"options":[{"key":"A","text":"Hoa Việt thân thiện","hl":[]},{"key":"B","text":"Hoa Việt bình đẳng","hl":[]},{"key":"C","text":"Hoa Việt tương trợ","hl":[]},{"key":"D","text":"Hoa Việt thân ái","hl":[]}],"answer":["A"],"note":""},{"id":"221","question":"Đại hội II Đảng Lao động Việt Nam vạch ra hai đối tượng của cách mạng Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Chủ nghĩa đế quốc xâm lược và phong kiến","hl":[]},{"key":"B","text":"Bọn can thiệp Mỹ và phong kiến phản động","hl":[]},{"key":"C","text":"Đế quốc Pháp và phong kiến phản động","hl":[]},{"key":"D","text":"Đế quốc Pháp và bọn can thiệp Mỹ","hl":[]}],"answer":["A"],"note":""},{"id":"222","question":"Chính cương của Đảng lao động Việt Nam đã nêu ra các nhiệm vụ cơ bản của cách mạng Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc, Xóa bỏ những di tích phong kiến và nửa phòng kiến, làm cho người cày có ruộng, Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","hl":[]},{"key":"B","text":"Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc, Xóa bỏ những di tích phong kiến và nửa phòng kiến, làm cho người cày có ruộng, Phát triển chế độ dân chủ nhân dân, gây cơ sở cho xã hội dân chủ.","hl":[]},{"key":"C","text":"Đánh đuổi bọn phong kiến, giành độc lập và thống nhất thật sự cho dân tộc, Xóa bỏ những di tích phong kiến và nửa phòng kiến, làm cho người cày có ruộng, Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","hl":[]},{"key":"D","text":"Đánh đuổi bọn đế quốc xâm lược, giành độc lập và thống nhất thật sự cho dân tộc, Xóa bỏ những di tích phong kiến và nửa phòng kiến, làm cho ngư","hl":[]}],"answer":["A"],"note":""},{"id":"223","question":"Sau cách mạng Tháng Tám năm 1945 thành công, Đảng Cộng sản Đông Dương xác định thực dân Pháp là kẻ thù như thế nào? Ngay sau khi cách mạng Tháng Tám 1945 thành công, Thực dân Pháp được Đảng coi là kẻ thù như thế nào?","qHighlight":[],"options":[{"key":"A","text":"Kẻ thù chính","hl":[]},{"key":"B","text":"Kẻ thù phụ","hl":[]},{"key":"C","text":"Không nguy hiểm","hl":[]},{"key":"D","text":"Chờ giải giáp của quân đồng minh","hl":[]}],"answer":["A"],"note":""},{"id":"224","question":"Đại hội III (9-1960) của Đảng đã thông qua đường lối nào?","qHighlight":[],"options":[{"key":"A","text":"Đánh đuổi thực dân Pháp và can thiệp Mỹ xâm lược, giành độc lập và thống nhất thật sự cho dân tộc","hl":[]},{"key":"B","text":"Cả nước quá độ đi lên chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","hl":[]},{"key":"D","text":"Đường lối cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam","hl":[]}],"answer":["D"],"note":""},{"id":"225","question":"Sau khi Mỹ thực hiện chiến lược \"chiến tranh cục bộ\", Đảng xác định nhiệm vụ cách mạng của miền Bắc là:","qHighlight":[],"options":[{"key":"A","text":"Chuyển hướng xây dựng kinh tế, bảo đảm tiếp tục xây dựng miền Bắc vững mạnh trong điều kiện có chiến tranh","hl":[]},{"key":"B","text":"Tiếp tục xây dựng kinh tế ở miền Bắc làm cho miền Bắc trở thành hậu phương lớn của cả nước","hl":[]},{"key":"C","text":"Không tiếp tục xây dựng kinh tế ở miền Bắc để tập trung cho phát triển lực lượng quốc phòng","hl":[]},{"key":"D","text":"Không chuyển hướng xây dựng kinh tế, tiếp tục phát triển kế hoạch 5 năm ở miền Bắc","hl":[]}],"answer":["A"],"note":""},{"id":"226","question":"Đại hội Đảng lần thứ II xác định con đường đi lên chủ nghĩa xã hội là một quá trình :","qHighlight":[],"options":[{"key":"A","text":"Đấu tranh lâu dài, đại thể trải qua ba giai đoạn","hl":[]},{"key":"B","text":"Đấu tranh kiên trì, đại thể trải qua bốn giai đoạn","hl":[]},{"key":"C","text":"Đấu tranh lâu dài, đại thể trải qua năm giai đoạn","hl":[]},{"key":"D","text":"Đấu tranh kiên trì, đại thể trải qua hai giai đoạn","hl":[]}],"answer":["A"],"note":""},{"id":"227","question":"Ngày 19/10/1946, Ban Thường vụ Trung ương Đảng mở Hội nghị quân sự toàn quốc lần thứ nhất, do Tổng Bí thư Trường Chinh chủ trì, Hội nghị xác định :","qHighlight":[],"options":[{"key":"A","text":"\"Không sớm thì muộn, Pháp sẽ đánh mình và mình nhất định phải đánh Pháp\"","hl":[]},{"key":"B","text":"\"Không sớm thì muộn, Pháp sẽ tấn công mình và mình nhất định phải đánh Pháp\"","hl":[]},{"key":"C","text":"\"Không sớm thì muộn, Pháp sẽ đánh chiếm mình và mình nhất định sẽ thắng Pháp\"","hl":[]}],"answer":["A"],"note":""},{"id":"228","question":"Cuộc kháng chiến chống Mỹ, cứu nước của nhân dân Việt Nam (1954-1975) kết thúc bằng thắng lợi của chiến dịch nào?","qHighlight":[],"options":[{"key":"A","text":"Hồ Chí Minh","hl":[]},{"key":"B","text":"Tây Nguyên","hl":[]},{"key":"C","text":"Huế - Đà Nẵng.","hl":[]},{"key":"D","text":"Đường 14 - Phước Long.","hl":[]}],"answer":["A"],"note":""},{"id":"229","question":"Đảng ta đã phát động phong trào gì để ủng hộ nhân lực cho Nam Bộ kháng chiến chống Pháp từ ngày 23-9-1945?","qHighlight":[],"options":[{"key":"A","text":"Vì miền Nam \"thành đồng Tổ quốc\"","hl":[]},{"key":"B","text":"Hướng về miền Nam ruột thịt","hl":[]},{"key":"C","text":"Nam tiến","hl":[]},{"key":"D","text":"Tất cả trên đúng.","hl":[]}],"answer":["C"],"note":""},{"id":"230","question":"Chủ trương nào không có trong Chỉ thị \"Nhật - Pháp bắn nhau và hành động của chúng ta\" (3/1945)?","qHighlight":[],"options":[{"key":"A","text":"Thông qua 10 chính sách lớn của Việt Minh","hl":[]},{"key":"B","text":"Thay khẩu hiệu \"đánh đuổi phát xít Nhật - Pháp\" bằng khẩu hiệu \"đánh đuổi phát xít Nhật\"","hl":[]},{"key":"C","text":"Nêu khẩu hiệu \"thành lập chính quyền cách mạng của nhân dân Đông Dương\"","hl":[]},{"key":"D","text":"Phát động một cao trào kháng Nhật cứu nước","hl":[]}],"answer":["A"],"note":""},{"id":"231","question":"Tình hình đất nước ta sau cách mạng tháng tám năm 1945 được ví như :","qHighlight":[],"options":[{"key":"A","text":"Nước sôi, lửa bỏng","hl":[]},{"key":"B","text":"Nhẹ như lông hồng","hl":[]},{"key":"C","text":"Ngàn cân treo sợi tóc","hl":[]},{"key":"D","text":"Trứng, nước","hl":[]}],"answer":["C"],"note":""},{"id":"232","question":"Đường lối toàn quốc kháng chiến tập trung trong ba văn kiện quan trọng đó là:","qHighlight":[],"options":[{"key":"A","text":"Toàn dân kháng chiến, Lời kêu gọi toàn quốc kháng chiến, Kháng chiến nhất định thắng lợi","hl":[]},{"key":"B","text":"Nhật Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc, Kháng chiến nhất định thắng lợi","hl":[]},{"key":"C","text":"Toàn dân kháng chiến, Nhật Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc","hl":[]},{"key":"D","text":"Lời kêu gọi toàn quốc kháng chiến, Nhật Pháp bắn nhau và hành động của chúng ta, Kháng chiến kiến quốc","hl":[]}],"answer":["A"],"note":""},{"id":"233","question":"Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh được phát ra vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"12-12-1946","hl":[]},{"key":"B","text":"22-12-1946","hl":[]},{"key":"C","text":"2-3-1946","hl":[]},{"key":"D","text":"19-12-1946","hl":[]}],"answer":["D"],"note":""},{"id":"234","question":"Thống nhất nước nhà về mặt Nhà nước sau năm 1975 là:","qHighlight":[],"options":[{"key":"A","text":"Thống nhất giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Chính phủ Việt Nam Cộng hòa","hl":[]},{"key":"B","text":"Thống nhất giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Chính phủ Cách mạng Lâm thời Cộng hòa Miền Nam Việt Nam","hl":[]},{"key":"C","text":"Thống nhất giữa Chính phủ Việt Nam Dân chủ Cộng hòa với Mặt trận Dân tộc Giải phóng Miền Nam Việt Nam","hl":[]},{"key":"D","text":"Thống nhất giữa Đảng Lao động Việt Nam với Đảng Nhân dân Cách mạng Miền Nam Việt Nam","hl":[]}],"answer":["B"],"note":""},{"id":"235","question":"Đại hội lần thứ III của Đảng họp tại thủ đô Hà Nội từ ngày 5 đến ngày 10/09/1960. Đại hội đã hoàn chỉnh đường lối chiến lược chung của cách mạng Việt Nam trong giai đoạn mới và vạch ra hai nhiệm vụ chiến lược đó là:","qHighlight":[],"options":[{"key":"A","text":"Tiến hành cách mạng xã hội chủ nghĩa ở miền Bắc. Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai, thực hiện thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước","hl":[]},{"key":"B","text":"Tiến hành cách mạng dân chủ nhân dân ở miền Bắc. Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai, thực hiện thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước","hl":[]},{"key":"C","text":"Tiến hành cách mạng dân tộc dân chủ ở miền Bắc. Giải phóng miền Nam khỏi ách thống trị của đế quốc Mỹ và bọn tay sai, thực hiện thống nhất nước nhà, hoàn thành độc lập và dân chủ trong cả nước","hl":[]}],"answer":["A"],"note":""},{"id":"236","question":"Mối quan hệ giữa hai nhiệm vụ cách mạng của hai miền được Đại hội III của Đảng xác định là:","qHighlight":[],"options":[{"key":"A","text":"Hai nhiệm vụ chiến lược ấy có quan hệ mật thiết với nhau và có tác dụng thúc đẩy lẫn nhau","hl":[]},{"key":"B","text":"Hai nhiệm vụ chiến lược ấy có quan hệ quyết định lẫn nhau","hl":[]},{"key":"C","text":"Hai nhiệm vụ chiến lược ấy có quan hệ mật thiết với nhau","hl":[]},{"key":"D","text":"Hai nhiệm vụ chiến lược ấy có quan hệ độc lập với nhau và có tác dụng thúc đẩy lẫn nhau","hl":[]}],"answer":["A"],"note":""},{"id":"237","question":"Ngày 23-9-1945 gắn với sự kiện lịch sử nào?","qHighlight":[],"options":[{"key":"A","text":"Pháp nổ súng xâm lược nước ta lần thứ 2.","hl":[]},{"key":"B","text":"Bác ra lời kêu gọi toàn quốc kháng chiến.","hl":[]},{"key":"C","text":"Nhật đảo chính Pháp độc chiếm Đông Dương.","hl":[]},{"key":"D","text":"Hội nghị quốc dân ở Tân Trào","hl":[]}],"answer":["A"],"note":""},{"id":"238","question":"Ta đã nhân nhượng với quân Trung Hoa Dân quốc như thế nào?","qHighlight":[],"options":[{"key":"A","text":"Chấp nhận mọi yêu cầu cải tổ Chính phủ, Quốc hội theo ý chúng Trung Hoa Dân quốc.","hl":[]},{"key":"B","text":"Chấp nhận tiêu tiền Trung Quốc, cung cấp một phần lương thực, thực phẩm cho quân Tưởng.","hl":[]},{"key":"C","text":"Chấp nhận tất cả mọi yêu cầu đảm bảo trật tự trị an, phương tiện đi lại của quân Tưởng.","hl":[]},{"key":"D","text":"Chấp nhận cung cấp toàn bộ lương thực thực phẩm cho quân Tưởng.","hl":[]}],"answer":["B"],"note":""},{"id":"239","question":"Nội dung nào dưới đây thuộc Hiệp định Sơ bộ (6 - 3 - 1946)?","qHighlight":[],"options":[{"key":"A","text":"Việt Nam là một quốc gia độc lập trong khối Liên hợp Pháp.","hl":[]},{"key":"B","text":"Việt Nam là một quốc gia tự trị trong khối Liên hợp Pháp.","hl":[]},{"key":"C","text":"Việt Nam là một quốc gia tự do trong khối Liên hợp Pháp.","hl":["quốc gia tự do"]},{"key":"D","text":"Việt Nam là một quốc gia tự chủ trong khối Liên hợp Pháp.","hl":[]}],"answer":["C"],"note":""},{"id":"240","question":"Để kéo dài thời gian chuẩn bị lực lượng cho cuộc kháng chiến toàn quốc chống Pháp, sau Hiệp định Sơ bộ (6/3/1946), Chính phủ nước Việt Nam Dân chủ Cộng hòa tiếp tục kí với Pháp bản","qHighlight":[],"options":[{"key":"A","text":"Hiệp định Giơnevơ.","hl":[]},{"key":"B","text":"Hòa ước.","hl":[]},{"key":"C","text":"Hiệp định Pari.","hl":[]},{"key":"D","text":"Tạm ước.","hl":[]}],"answer":["D"],"note":""},{"id":"241","question":"Hội nghị nào của Đảng mở đường cho phong trào \"Đồng khởi\" ở miền Nam năm 1960?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị Trung ương 12 khóa II của Đảng (3/1957)","hl":[]},{"key":"B","text":"Hội nghị Trung ương 1 khóa II của Đảng (12/1957)","hl":[]},{"key":"C","text":"Hội nghị Trung ương 14 khóa II của Đảng (11/1958)","hl":[]},{"key":"D","text":"Hội nghị Trung ương 15 khóa II của Đảng (1/1959)","hl":[]}],"answer":["D"],"note":""},{"id":"242","question":"Đường lối kháng chiến chống thực dân Pháp xâm lược của Đảng (1946-1954) là:","qHighlight":[],"options":[{"key":"A","text":"Toàn dân, toàn diện, lâu dài và tự lực cánh sinh","hl":[]},{"key":"B","text":"Toàn diện, lâu dài và tự lực cánh sinh","hl":[]},{"key":"C","text":"Chiến tranh nhân dân, toàn diện và tự lực cánh sinh","hl":[]},{"key":"D","text":"Chiến tranh nhân dân, toàn diện, lâu dài và tranh thủ ngoại lực","hl":[]}],"answer":["A"],"note":""},{"id":"243","question":"Đường lối kháng chiến \"Dựa vào sức mình là chính\" được Đảng xác định là :","qHighlight":[],"options":[{"key":"A","text":"\"Phải tự cấp, tự túc về mọi mặt\"","hl":[]},{"key":"B","text":"\"Phải đánh địch bằng sức mình\"","hl":[]},{"key":"C","text":"\"Phải tự vũ trang để thắng định về mọi mặt\"","hl":[]},{"key":"D","text":"\"Phải biết tranh thủ sự giúp đỡ của các nước\"","hl":[]}],"answer":["A"],"note":""},{"id":"245","question":"Từ tháng 9-1945 đến tháng 3-1946 ta chủ trương :","qHighlight":[],"options":[{"key":"A","text":"Hòa với Tưởng","hl":[]},{"key":"B","text":"Hòa với Pháp","hl":[]},{"key":"C","text":"Đánh Tưởng","hl":[]},{"key":"D","text":"Đánh Pháp","hl":[]}],"answer":["A"],"note":""},{"id":"246","question":"Sau cách mạng tháng Tám năm 1945, khó khăn lớn nhất đưa nước ta vào tình thế \"ngàn cân treo sợi tóc\" là gì?","qHighlight":[],"options":[{"key":"A","text":"Khó khăn về thù trong, giặc ngoài","hl":[]},{"key":"B","text":"Nạn đói, nạn dốt đe doạ nghiêm trọng đến nhân dân ta","hl":[]},{"key":"C","text":"Ngân sách nhà nước trống rỗng","hl":[]},{"key":"D","text":"Hơn 90% dân số không biết chữ","hl":[]}],"answer":["A"],"note":""},{"id":"247","question":"Với chính sách cai trị của thực dân Pháp, sau Cách mạng tháng Tám năm 1945, nước ta có khoảng bao nhiêu % dân số mù chữ? Sau Cách mạng tháng Tám năm 1945, tàn dư văn hóa lạc hậu của chế độ thực dân, phong kiến để lại hết sức nặng nề là :","qHighlight":[],"options":[{"key":"A","text":"Hơn 60% dân số không biết chữ","hl":[]},{"key":"B","text":"Hơn 70% dân số không biết chữ","hl":[]},{"key":"C","text":"Hơn 80% dân số không biết chữ","hl":[]},{"key":"D","text":"Hơn 90% dân số không biết chữ","hl":[]}],"answer":["D"],"note":""},{"id":"248","question":"\"Chúng ta thà hi sinh tất cả, chứ nhất định không chịu mất nước, nhất định không chịu làm nô lệ... \" là đoạn trích trong văn kiện nào?","qHighlight":[],"options":[{"key":"A","text":"Chỉ thị Toàn dân kháng chiến của Ban Thường vụ Trung ương Đảng","hl":[]},{"key":"B","text":"Lời kêu gọi toàn quốc kháng chiến của Chủ tịch Hồ Chí Minh","hl":[]},{"key":"C","text":"Tác phẩm Kháng chiến nhất định thắng lợi của Tổng Bí thư Trường Chinh","hl":[]},{"key":"D","text":"Chỉ thị sửa soạn khởi nghĩa của Tổng bộ Việt Minh","hl":[]}],"answer":["B"],"note":""},{"id":"249","question":"Sau Cách mạng tháng Tám đến 1954, kẻ thù chính của nhân dân Việt Nam là :","qHighlight":[],"options":[{"key":"A","text":"Pháp","hl":[]},{"key":"B","text":"Anh","hl":[]},{"key":"C","text":"Mĩ","hl":[]},{"key":"D","text":"Trung quốc","hl":[]}],"answer":["A"],"note":""},{"id":"250","question":"Căn cứ địa cách mạng của ta trong cuộc kháng chiến chống Pháp xâm lược lần thứ hai là :","qHighlight":[],"options":[{"key":"A","text":"Hà Nội","hl":[]},{"key":"B","text":"Biên Giới","hl":[]},{"key":"C","text":"Việt Bắc","hl":[]},{"key":"D","text":"Điện Biên Phủ","hl":[]}],"answer":["C"],"note":""},{"id":"251","question":"Ai là tác giả của tác phẩm Kháng chiến nhất định thắng lợi? Tác phẩm \"Kháng chiến nhất định thắng lợi\" là của ai?","qHighlight":[],"options":[{"key":"A","text":"Trường Chinh","hl":[]},{"key":"B","text":"Võ Nguyên Giáp","hl":[]},{"key":"C","text":"Hồ Chí Minh","hl":[]},{"key":"D","text":"Trần Phú","hl":[]}],"answer":["A"],"note":""},{"id":"252","question":"Ai được bầu làm Tổng Bí thư của Đảng tại Đại hội đại biểu lần thứ II (1951)?","qHighlight":[],"options":[{"key":"A","text":"Trần Phú","hl":[]},{"key":"B","text":"Hồ Chí Minh","hl":[]},{"key":"C","text":"Trường Chinh","hl":[]},{"key":"D","text":"Lê Hồng Phong","hl":[]}],"answer":["C"],"note":""},{"id":"253","question":"Đại hội nào sau đây được đánh dấu là \" Đại hội kháng chiến thắng lợi\" ?","qHighlight":[],"options":[{"key":"A","text":"Hội nghị thành lập Đảng 1930","hl":[]},{"key":"B","text":"Đại hội Quốc dân ở Tân Trào 1945","hl":[]},{"key":"C","text":"Đại hội lần thứ II của Đảng 1951","hl":[]},{"key":"D","text":"Đại hội Đại biểu lần thứ III của Đảng 1960","hl":[]}],"answer":["C"],"note":""},{"id":"254","question":"Kế hoạch quân sự được xem là lớn nhất trong quá trình xâm lược Việt Nam của Pháp từ 1945-1954?","qHighlight":[],"options":[{"key":"A","text":"Kế hoạch Rơve","hl":[]},{"key":"B","text":"Kế hoạch Nava","hl":[]},{"key":"C","text":"Kế hoạch \"đánh nhanh thắng nhanh\"","hl":[]},{"key":"D","text":"Kế hoạch Đờ Lát đơ Tátxinhi","hl":[]}],"answer":["B"],"note":""},{"id":"255","question":"Chiến thắng Phước Long (1/1975) có ý nghĩa như thế nào đối với việc Đảng đề ra quyết tâm chiến lược giải phóng miền Nam trong hai năm 1975 - 1976?","qHighlight":[],"options":[{"key":"A","text":"Đòn đánh quan trọng","hl":[]},{"key":"B","text":"Đòn đánh quyết định","hl":[]},{"key":"C","text":"Đòn thăm dò chiến lược","hl":[]},{"key":"D","text":"Đòn đánh mở màn","hl":[]}],"answer":["C"],"note":""},{"id":"256","question":"Chiến dịch Điện Biên Phủ được coi là một chiến dịch lịch sử của quân đội ta và được chia làm bao nhiêu đợt?","qHighlight":[],"options":[{"key":"A","text":"2 đợt","hl":[]},{"key":"B","text":"3 đợt","hl":[]},{"key":"C","text":"4 đợt","hl":[]},{"key":"D","text":"5 đợt","hl":[]}],"answer":["B"],"note":""},{"id":"257","question":"Thắng lợi nào của quân và dân ta trong cuộc kháng chiến chống Pháp đã làm phá sản hoàn toàn kế hoạch Nava?","qHighlight":[],"options":[{"key":"A","text":"Chiến thắng Biên giới Thu - Đông 1950","hl":[]},{"key":"B","text":"Chiến thắng Tây Bắc 1953","hl":[]},{"key":"C","text":"Chiến thắng Điện Biên Phủ 1954","hl":[]},{"key":"D","text":"Chiến thắng Thượng Lào 1954","hl":[]}],"answer":["C"],"note":""},{"id":"258","question":"Trưởng đoàn đại diện cho phái đoàn Chính phủ Việt Nam Dân chủ Cộng hòa tại Hội nghị Giơnevơ là ai?","qHighlight":[],"options":[{"key":"A","text":"Hồ Chí Minh","hl":[]},{"key":"B","text":"Trường Chinh","hl":[]},{"key":"C","text":"Phạm Văn Đồng","hl":[]},{"key":"D","text":"Võ Nguyên Giáp","hl":[]}],"answer":["C"],"note":""},{"id":"259","question":"Thắng lợi ngoại giao lớn nhất của ta trong cuộc kháng chiến chống Pháp từ 1945-1954 là :","qHighlight":[],"options":[{"key":"A","text":"Hiệp định Sơ bộ 1946","hl":[]},{"key":"B","text":"Tạm ước 1946","hl":[]},{"key":"C","text":"Hiệp định Giơnevơ 1954","hl":[]},{"key":"D","text":"Liên Xô, Trung Quốc đặt quan hệ ngoại giao với ta 1950","hl":[]}],"answer":["C"],"note":""},{"id":"260","question":"Quyền dân tộc cơ bản của Việt Nam trong Hiệp định Giơnevơ 1954 là gì?","qHighlight":[],"options":[{"key":"A","text":"Độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ","hl":[]},{"key":"B","text":"Các bên thực hiện cuộc tập kết, chuyển quân, chuyển giao khu vực","hl":[]},{"key":"C","text":"Việt Nam sẽ tiến hành tổng tuyển cử thống nhất đất nước","hl":[]},{"key":"D","text":"Các bên tham chiến thực hiện ngừng bắn, lập lại hòa bình ở Đông Dương","hl":[]}],"answer":["A"],"note":""},{"id":"261","question":"Chiến thắng nào của ta quyết định thắng lợi tại hội nghị Giơnevơ 1954?","qHighlight":[],"options":[{"key":"A","text":"Việt Bắc thu - đông 1947","hl":[]},{"key":"B","text":"Biên giới thu - dông 1950","hl":[]},{"key":"C","text":"Điện Biên Phủ 1954","hl":[]},{"key":"D","text":"Đông xuân 1953-1954","hl":[]}],"answer":["C"],"note":""},{"id":"262","question":"Chiến dịch lịch sử Điện Biên Phủ 1954 là đỉnh cao của :","qHighlight":[],"options":[{"key":"A","text":"Khởi nghĩa chống Pháp","hl":[]},{"key":"B","text":"Kháng chiến chống Pháp","hl":[]},{"key":"C","text":"Kháng chiến chống Mĩ","hl":[]},{"key":"D","text":"Chiến tranh chống Pháp","hl":[]}],"answer":["B"],"note":""},{"id":"263","question":"Được ghi vào lịch sử dân tộc như một Bạch Đằng, một Chi Lăng, một Đống Đa thế kỉ XX. Đó là ý nghĩa của chiến thắng nào?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng tháng Tám 1945","hl":[]},{"key":"B","text":"Chiến dịch Điện Biên Phủ 1954","hl":[]},{"key":"C","text":"Chiến dịch Huế- Đà Nẵng 1975","hl":[]},{"key":"D","text":"Chiến dịch Hồ Chí Minh 1975","hl":[]}],"answer":["B"],"note":""},{"id":"264","question":"Hiệp định Giơnevơ 1954, quy định việc di chuyển, tập kết quân đội ở hai miền Nam - Bắc với giới tuyến quân sự tạm thời là :","qHighlight":[],"options":[{"key":"A","text":"Vĩ tuyến 17","hl":[]},{"key":"B","text":"Vĩ tuyến 18","hl":[]},{"key":"C","text":"Vĩ tuyến 19","hl":[]},{"key":"D","text":"Vĩ tuyến 20","hl":[]}],"answer":["A"],"note":""},{"id":"265","question":"Đại hội đại biểu toàn quốc lần thứ III của Đảng được tổ chức tại :","qHighlight":[],"options":[{"key":"A","text":"Sài Gòn","hl":[]},{"key":"B","text":"Hà Nội","hl":[]},{"key":"C","text":"Tân Trào","hl":[]},{"key":"D","text":"Hóc môn","hl":[]}],"answer":["B"],"note":""},{"id":"267","question":"Chiến thắng Điện Biên Phủ năm 1954 của quân dân Việt Nam đã:","qHighlight":[],"options":[{"key":"A","text":"Đánh dấu mốc thắng lợi của cuộc kháng chiến chống Pháp","hl":[]},{"key":"B","text":"Làm phá sản hoàn toàn kế hoạch Nava của thực dân Pháp.","hl":[]},{"key":"C","text":"Buộc Pháp phải ngồi vào đàm phán tại Giơnevơ.","hl":[]},{"key":"D","text":"Bước đầu làm phá sản kế hoạch Nava của thực dân Pháp.","hl":[]}],"answer":["B"],"note":""},{"id":"268","question":"Ngày 12/12/1946, Ban Thường vụ Trung ương Đảng đã ra","qHighlight":[],"options":[{"key":"A","text":"Quân lệnh số 1.","hl":[]},{"key":"B","text":"Lời kêu gọi Tổng khởi nghĩa.","hl":[]},{"key":"C","text":"Chỉ thị Toàn dân kháng chiến.","hl":[]},{"key":"D","text":"Lời kêu gọi toàn quốc kháng chiến.","hl":[]}],"answer":["C"],"note":""},{"id":"269","question":"Pháp chấp nhận đàm phán với Việt Nam ở Hội nghị Giơnevơ năm 1954 về Đông Dương vì:","qHighlight":[],"options":[{"key":"A","text":"Sức ép của Liên Xô","hl":[]},{"key":"B","text":"Bị thất bại ở Điện Biên Phủ","hl":[]},{"key":"C","text":"Dư luận nhân dân thế giới phản đối","hl":[]},{"key":"D","text":"Pháp sợ Trung Quốc đưa quân sang giúp đỡ Việt Nam","hl":[]}],"answer":["B"],"note":""},{"id":"270","question":"Hiệp định sơ bộ được Hồ Chí Minh ký với Sanh-tơ-ny vào thời gian nào sau đây?","qHighlight":["h-tơ-ny vào"],"options":[{"key":"A","text":"6/3/1946","hl":[]},{"key":"B","text":"14/9/1946","hl":[]},{"key":"C","text":"19/12/1946","hl":[]},{"key":"D","text":"10/12/1946","hl":[]}],"answer":["A"],"note":""},{"id":"271","question":"Đường lối chung xây dựng XHCN ở miền Bắc (1954-1975) được đề cập ở Đại hội lần thứ mấy của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Đại hội II","hl":[]},{"key":"B","text":"Đại hội III","hl":[]},{"key":"C","text":"Đại hội IV","hl":[]},{"key":"D","text":"Đại hội V","hl":[]}],"answer":["B"],"note":""},{"id":"272","question":"Vận mệnh của dân tộc Việt Nam ngay sau khi Cách mạng tháng Tám thành công được Chủ tịch Hồ Chí Minh đánh giá:","qHighlight":[],"options":[{"key":"A","text":"Có những thách thức to lớn","hl":[]},{"key":"B","text":"Vô cùng khó khăn, nguy hiểm","hl":[]},{"key":"C","text":"Vô cùng hiểm nghèo","hl":[]},{"key":"D","text":"Ngàn cân treo sợi tóc","hl":[]}],"answer":["D"],"note":""},{"id":"273","question":"Đảng ta đã lựa chọn giải pháp gì trong mối quan hệ với thực dân Pháp sau ngày Pháp và Tưởng ký hiệp ước Trùng Khánh (28-2-1946)?","qHighlight":[],"options":[{"key":"A","text":"Kháng chiến chống thực dân Pháp","hl":[]},{"key":"B","text":"Chống cả quân đội Tưởng và Pháp","hl":[]},{"key":"C","text":"Nhân nhượng với quân đội Tưởng","hl":[]},{"key":"D","text":"Thương lượng và hoà hoãn với Pháp","hl":["Thương lượng và hoà hoãn"]}],"answer":["D"],"note":""},{"id":"274","question":"Cuộc kháng chiến chống thực dân Pháp xâm lược của nhân dân Đông Dương (1953 - 1954) kết thúc bằng giải pháp","qHighlight":[],"options":[{"key":"A","text":"chính trị","hl":[]},{"key":"B","text":"quân sự","hl":[]},{"key":"C","text":"kinh tế","hl":[]},{"key":"D","text":"văn hóa","hl":[]}],"answer":["A"],"note":""},{"id":"275","question":"Đại hội XII của Đảng (2016) nêu rõ mục tiêu, nhiệm vụ tổng quát phát triển đất nước 5 năm 2016 - 2020 là:","qHighlight":[],"options":[{"key":"A","text":"Đổi mới thể chế kinh kế","hl":[]},{"key":"B","text":"Đổi mới mô hình tăng trưởng","hl":[]},{"key":"C","text":"Đổi mới hệ thống chính trị","hl":[]},{"key":"D","text":"Đưa nước ta trở thành nước công nghiệp theo hướng hiện đại vào năm 2020","hl":[]}],"answer":["D"],"note":""},{"id":"276","question":"Pháp thực hiện rút quân khỏi miền Nam Việt Nam trong bối cảnh nào ?","qHighlight":[],"options":[{"key":"A","text":"Tất cả mọi điều khoản được quy định tại Hiệp định đã được hoàn tất.","hl":[]},{"key":"B","text":"Pháp đã hoàn tất chuyển giao mọi trách nhiệm thi hành Hiệp định Giơ-ne-vơ cho chính quyền Bửu Lộc.","hl":[]},{"key":"C","text":"Pháp đã xúc tiến mọi việc cho công cuộc thống nhất đất nước bằng con đường tổng tuyển cử hai miền.","hl":[]},{"key":"D","text":"Rất nhiều điều khoản trong Hiệp định Giơ-ne-vơ chưa được hoàn tất.","hl":[]}],"answer":["D"],"note":""},{"id":"277","question":"Một trong những sự kiện làm bùng nổ phong trào Đồng khởi năm 1960 là :","qHighlight":[],"options":[{"key":"A","text":"Ngăn cản hiệp thương, tổng tuyển cử thống nhất đất nước","hl":["thương, tổng tuyển cử thống nhất đất nước"]},{"key":"B","text":"Ban hành Luật 10/59","hl":[]},{"key":"C","text":"Lập ấp chiến lược","hl":[]},{"key":"D","text":"Các phương án trả lời đều đúng","hl":[]}],"answer":["B"],"note":""},{"id":"278","question":"Hình thức khởi nghĩa chống lại ách thống trị của Mĩ - Diệm đã diễn ra đầu tiên ở đâu ?","qHighlight":[],"options":[{"key":"A","text":"Bến Tre.","hl":[]},{"key":"B","text":"Bình Định.","hl":[]},{"key":"C","text":"Quảng Ngãi.","hl":[]},{"key":"D","text":"Tây Ninh.","hl":[]}],"answer":["B"],"note":""},{"id":"279","question":"Nội dung nào không phản ánh thành tựu của kế hoạch Nhà nước 5 năm (1961 - 1965)?","qHighlight":[],"options":[{"key":"A","text":"Giá trị sản lượng công nghiệp nặng năm 1965 tăng 3 lần so với năm 1960.","hl":[]},{"key":"B","text":"Công nghiệp quốc doanh chiếm tỉ trọng 93% trong tổng giá trị sản lượng ngành công nghiệp toàn miền Bắc.","hl":[]},{"key":"C","text":"Công nghiệp nhẹ, tiểu thủ công nghiệp đã giải quyết được 80% hàng tiêu dùng thiết yếu cho nhân dân.","hl":[]},{"key":"D","text":"Thương nghiệp tư nhân được Nhà nước ưu tiên phát triển nên đã chiếm lĩnh được thị trường.","hl":[]}],"answer":["D"],"note":""},{"id":"280","question":"Theo quan điểm của Đại hội Đảng lần thứ IV (12/1976), đặc điểm nào sau đây là lớn nhất, quy định nội dung, hình thức, bước đi của cách mạng xã hội chủ nghĩa ở nước ta trong giai đoạn mới?","qHighlight":[],"options":[{"key":"A","text":"Tổ quốc ta đã hòa bình, độc lập, thống nhất, cả nước tiến lên chủ nghĩa xã hội","hl":[]},{"key":"B","text":"Cách mạng xã hội chủ nghĩa ở nước ta tiến hành trong hoàn cảnh quốc tế thuận lợi","hl":[]},{"key":"C","text":"Nước ta đang ở trong quá trình từ một xã hội mà nền kinh tế còn phổ biến là sản xuất nhỏ tiến thẳng lên chủ nghĩa xã hội, bỏ qua giai đoạn phát triển tư bản chủ nghĩa","hl":[]},{"key":"D","text":"Đất nước còn đối mặt nhiều khó khăn do hậu quả của chiến tranh và tàn dư của chủ nghĩa thực dân","hl":[]}],"answer":["C"],"note":""},{"id":"281","question":"Nội dung nào trong Hiệp định Sơ bộ 6-3-1946 tạo điều kiện cho ta có thời gian để chuẩn bị lực lượng đối phó lâu dài với Pháp?","qHighlight":[],"options":[{"key":"A","text":"Pháp công nhận Việt Nam là một quốc gia tự do trong khối liên hiệp Pháp.","hl":[]},{"key":"B","text":"Pháp được đưa 15 ngàn quân ra miền Bắc thay thế quân Tưởng","hl":[]},{"key":"C","text":"Hai bên ngừng bắn ở Nam Bộ","hl":[]},{"key":"D","text":"Hai bên thực hiện tập kết, chuyển quân","hl":[]}],"answer":["C"],"note":""},{"id":"282","question":"Một trong những khó khăn của nước ta trong những năm 1953-1954 là :","qHighlight":[],"options":[{"key":"A","text":"Chủ nghĩa đế quốc xâm lược và phong kiến","hl":[]},{"key":"B","text":"Bọn can thiệp Mỹ và phong kiến phản động","hl":[]},{"key":"C","text":"Đế quốc Pháp và phong kiến","hl":[]},{"key":"D","text":"Đế quốc Pháp và bọn can thiệp Mỹ","hl":[]}],"answer":["D"],"note":""},{"id":"212","question":"Sau khi lên cầm quyền (1969), Tổng thống Mỹ R. Ních xơn chủ trương thay chiến lược Chiến tranh cục bộ ở miền Nam bằng chiến lược:","qHighlight":[],"options":[{"key":"A","text":"Chiến tranh tổng lực","hl":[]},{"key":"B","text":"Chiến tranh đơn phương","hl":[]},{"key":"C","text":"Chiến tranh đặc biệt","hl":[]},{"key":"D","text":"Việt Nam hóa chiến tranh","hl":[]}],"answer":["D"],"note":""},{"id":"95","question":"Trong giai đoạn 1965 - 1968, ở miền Nam, Mỹ đã thực hiện chiến lược chiến tranh nào?","qHighlight":[],"options":[{"key":"A","text":"Chiến tranh đơn phương","hl":[]},{"key":"B","text":"Chiến tranh đặc biệt","hl":[]},{"key":"C","text":"Chiến tranh cục bộ","hl":[]},{"key":"D","text":"Việt Nam hóa chiến tranh","hl":[]}],"answer":["C"],"note":""},{"id":"266","question":"Từ 1961-1965, Mĩ thực hiện loại hình chiến lược nào ở miền Nam Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"Chiến tranh đơn phương","hl":[]},{"key":"B","text":"Chiến tranh đặc biệt","hl":[]},{"key":"C","text":"Chiến tranh cục bộ","hl":[]},{"key":"D","text":"Việt Nam hóa chiến tranh","hl":[]}],"answer":["B"],"note":""},{"id":"283","question":"Sau thất bại của Chiến tranh đặc biệt, Mỹ chuyển sang loại hình chiến lược chiến tranh nào?","qHighlight":[],"options":[{"key":"A","text":"Chiến tranh đơn phương.","hl":[]},{"key":"B","text":"Chiến tranh cục bộ.","hl":[]},{"key":"C","text":"Việt Nam hóa chiến tranh.","hl":[]},{"key":"D","text":"Đông Dương hóa chiến tranh.","hl":[]}],"answer":["B"],"note":""},{"id":"286","question":"Phong trào Đồng khởi làm thất bại loại hình chiến lược chiến tranh nào của Mỹ?","qHighlight":[],"options":[{"key":"A","text":"Chiến tranh đơn phương,","hl":[]},{"key":"B","text":"Chiến tranh đặc biệt","hl":[]},{"key":"C","text":"Chiến tranh cục bộ","hl":[]},{"key":"D","text":"Việt Nam hóa chiến tranh","hl":[]}],"answer":["A"],"note":""},{"id":"284","question":"Đặc điểm nổi bật của nước ta sau 1954 là :","qHighlight":[],"options":[{"key":"A","text":"Đánh đuổi thực dân Pháp và can thiệp Mỹ xâm lược, giành độc lập dân tộc","hl":[]},{"key":"B","text":"Cả nước quá độ đi lên chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Phát triển chế độ dân chủ nhân dân, gây cơ sở cho chủ nghĩa xã hội","hl":[]},{"key":"D","text":"Tiến hành động thời cách mạng xã hội chủ nghĩa ở miền Bắc và cách mạng dân tộc dân chủ nhân dân ở miền Nam","hl":[]}],"answer":["D"],"note":""},{"id":"285","question":"Quan điểm nào sau đây của Đảng về nhiệm vụ và mối quan hệ giữa hai miền sau khi Mỹ thực hiện \"chiến tranh cục bộ\"?","qHighlight":[],"options":[{"key":"A","text":"Trong cuộc chiến tranh chống Mỹ của nhân dân cả nước, miền Nam là tiền tuyến lớn, miền Bắc là hậu phương lớn. Bảo vệ miền Bắc là nhiệm vụ của cả nước.","hl":[]},{"key":"B","text":"Trong cuộc chiến tranh chống Mỹ của nhân dân cả nước, miền Nam là hậu phương lớn, miền Bắc là tiền tuyến lớn. Bảo vệ miền Bắc là nhiệm vụ của cả nước.","hl":[]},{"key":"C","text":"Trong cuộc chiến tranh chống Mỹ của nhân dân cả nước, miền Nam là tiền tuyến lớn, miền Bắc là hậu phương lớn. Bảo vệ miền Bắc là nhiệm vụ của miền Bắc.","hl":[]},{"key":"D","text":"Trong cuộc chiến tranh chống Mỹ của nhân dân cả nước, miền Nam là tiền tuyến lớn, miền Bắc là hậu phương lớn. Bảo vệ miền Bắc là nhiệm vụ của miền Nam.","hl":[]}],"answer":["A"],"note":""},{"id":"287","question":"Mặt trận Dân tộc giải phóng miền Nam Việt Nam được thảnh lập ở đâu?","qHighlight":[],"options":[{"key":"A","text":"Bến Tre","hl":[]},{"key":"B","text":"Tây Ninh","hl":[]},{"key":"C","text":"Bình Định","hl":[]},{"key":"D","text":"Tây Nguyên","hl":[]}],"answer":["B"],"note":""},{"id":"288","question":"Mặt trận Dân tộc giải phóng miền Nam Việt Nam được thành lập do ai làm chủ tịch?","qHighlight":[],"options":[{"key":"A","text":"Nguyễn Hữu Thọ","hl":[]},{"key":"B","text":"Nguyễn Thị Định","hl":[]},{"key":"C","text":"Võ Nguyên Giáp","hl":[]},{"key":"D","text":"Trường Chinh","hl":[]}],"answer":["A"],"note":""},{"id":"289","question":"Âm mưu của Mỹ trong chiến lược chiến tranh đặc biệt là :","qHighlight":[],"options":[{"key":"A","text":"Dùng người Việt đánh người Việt","hl":[]},{"key":"B","text":"Dùng người Mỹ đánh người Việt","hl":[]},{"key":"C","text":"Dùng người Đông Dương đánh người đông Dương","hl":[]},{"key":"D","text":"Dùng người Việt đánh người Việt và dùng người Đông Dương đánh người đông Dương","hl":[]}],"answer":["A"],"note":""},{"id":"290","question":"Ý nghĩa quan trọng của phong trào Đồng khởi là :","qHighlight":[],"options":[{"key":"A","text":"Chuyển cách mạng miền Nam từ thế giữ gìn lực lượng sang thế tiến công","hl":[]},{"key":"B","text":"Lật đổ chính quyền Mỹ- Diệm","hl":[]},{"key":"C","text":"Mỹ phải ngồi vào bàn đàm phán","hl":[]},{"key":"D","text":"Mỹ phải kí hiệp định Pari","hl":[]}],"answer":["A"],"note":""},{"id":"291","question":"Nhận xét nào là phù hợp khi nói về mối quan hệ của hai miền đất nước trong cuộc kháng chiến chống Mỹ?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng hai miền có mối quan hệ mật thiết với nhau và có tác dụng thúc đẩy lẫn nhau","hl":[]},{"key":"B","text":"Cách mạng hai miền có quan hệ quyết định lẫn nhau","hl":[]},{"key":"C","text":"Cách mạng hai miền có quan hệ mật thiết với nhau","hl":[]},{"key":"D","text":"Cách mạng hai miền có quan hệ độc lập với nhau và có tác dụng thúc đẩy lẫn nhau","hl":[]}],"answer":["A"],"note":""},{"id":"292","question":"Tại sao, cuộc tổng tiến công nổi dậy Mậu Thân 1968 bị thất bại vừa mất đất, mất dân, hy sinh nhiều nhưng Đảng ta vẫn đánh giá thành công?","qHighlight":[],"options":[{"key":"A","text":"Chúng ta đã giáng đòn lớn và mạnh buộc Mỹ ngồi vào bàn đàm phán.","hl":[]},{"key":"B","text":"Chúng ta đã giáng đòn lớn và mạnh buộc Mỹ kí hiệp định Pari.","hl":[]},{"key":"C","text":"Buộc Mỹ phải thừa nhận thất bại của chiến lược Việt Nam hóa chiến tranh.","hl":[]},{"key":"D","text":"Mỹ buộc phải rút quân về nước.","hl":[]}],"answer":["A"],"note":""},{"id":"293","question":"Cuộc kháng chiến chống Mĩ, cứu nước của nhân dân ta là một cuộc đụng đầu lịch sử vì:","qHighlight":[],"options":[{"key":"A","text":"Đây là cuộc đấu tranh của một dân tộc nhược tiểu chống lại một đế quốc số một thế giới.","hl":[]},{"key":"B","text":"Đây là một cuộc chiến tranh xâm lược, phi nghĩa đứng về phía Mĩ - một đại diện cho chủ nghĩa đế quốc.","hl":[]},{"key":"C","text":"Đây là một cuộc chiến phản ánh tập trung những mâu thuẫn cơ bản của thời đại.","hl":[]},{"key":"D","text":"Đây là một cuộc chiến tranh chống chủ nghĩa thực dân mới của Mĩ, thực hiện giải phóng dân tộc, thống nhất đất nước đầu tiên giành thắng lợi.","hl":[]}],"answer":["C"],"note":""},{"id":"294","question":"Nét nổi bật nhất về tình hình chính trị ở Việt Nam sau khi Hiệp định Giơnevơ về Đông Dương được ký kết là:","qHighlight":[],"options":[{"key":"A","text":"Hà Nội được giải phóng","hl":[]},{"key":"B","text":"Pháp rút quân khỏi Miền Bắc","hl":[]},{"key":"C","text":"Đất nước bị chia cắt thành hai miền với hai chế độ chính trị - xã hội khác nhau.","hl":[]},{"key":"D","text":"Nhân dân hai miền tiến hành tổ chức hiệp thương tổng tuyển cử thống nhất đất nước","hl":[]}],"answer":["C"],"note":""},{"id":"295","question":"Hội nghị Trung ương VII khóa XII đã ban hành Nghị quyết số 36 - NQ/TW ngày 22/10/2018 về:","qHighlight":[],"options":[{"key":"A","text":"Chiến lược phát triển bền vững kinh tế biển Việt Nam đến năm 2030, tầm nhìn đến năm 2045","hl":[]},{"key":"B","text":"Đổi mới mục tiêu, con đường đi lên xã hội chủ nghĩa","hl":[]},{"key":"C","text":"Đổi mới nội dung, phương thức hoạt động, tổ chức cán bộ và quan hệ giữa các tổ chức trong hệ thống chính trị","hl":[]},{"key":"D","text":"Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới","hl":[]}],"answer":["A"],"note":""},{"id":"296","question":"Định hướng phát triển đất nước đến năm 2030 mà Đại hội XIII của Đảng xác định là:","qHighlight":[],"options":[{"key":"A","text":"Nước đang phát triển có công nghiệp theo hướng hiện đại vượt qua mức thu nhập trung bình thấp","hl":[]},{"key":"B","text":"Nước đang phát triển có công nghiệp hiện đại thu nhập trung bình cao","hl":[]},{"key":"C","text":"Nước đang phát triển có công nghiệp theo hướng hiện đại","hl":[]},{"key":"D","text":"Nước phát triển có thu nhập cao","hl":[]}],"answer":["B"],"note":""},{"id":"297","question":"Tại sao cần cải cách chính sách tiền lương, bảo hiểm xã hội và trợ cấp ưu đãi người có công giai đoạn 2008 - 2012?","qHighlight":[],"options":[{"key":"A","text":"Việc trả lương đúng cho người lao động là thực hiện đầu tư cho phát triển, tạo động lực cho phát triển kinh tế - xã hội","hl":[]},{"key":"B","text":"Việc trả lương đúng cho người lao động sẽ khuyến khích người giỏi hăng say lao động và có động lực phát triển đất nước","hl":[]},{"key":"C","text":"Việc trả lương đúng cho người lao động là thực hiện đầu tư cho phát triển kinh tế - xã hội, góp phần làm trong sạch và nâng cao hiệu lực, hiệu quả hoạt động của bộ máy nhà nước","hl":["kinh tế - xã hội,"]},{"key":"D","text":"Sẽ tạo động lực cho phát triển kinh tế - xã hội, góp phần làm trong sạch và nâng cao hiệu lực, hiệu quả hoạt động của bộ máy nhà nước","hl":[]}],"answer":["C"],"note":""},{"id":"298","question":"Nội dung nào phản ánh điểm tương đồng về nội dung giữa Hiệp định Giơ-ne-vơ năm 1954 về Đông Dương và Hiệp định Pari năm 1973 về Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"Hiệp định có sự tham gia của 5 cường quốc trong hội đồng bảo an Liên Hợp quốc","hl":[]},{"key":"B","text":"Các bên thừa nhận miền Nam có 2 chính quyền, 2 quân đội, 2 vùng kiểm soát và 3 lực lượng chính trị","hl":[]},{"key":"C","text":"Các nước đều cam kết tôn trọng những quyền dân tộc cơ bản của nhân dân Việt Nam","hl":[]},{"key":"D","text":"Thỏa thuận các bên ngừng bắn để thực hiện chuyển quân, tập kết, chuyển giao khu.","hl":[]}],"answer":["C"],"note":""},{"id":"299","question":"Từ năm 1954 đến năm 1975, Mỹ đã thực hiện mấy loại hình chiến tranh ở Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"2 loại hình chiến tranh","hl":[]},{"key":"B","text":"3 loại hình chiến tranh","hl":[]},{"key":"C","text":"4 loại hình chiến tranh","hl":[]},{"key":"D","text":"5 loại hình chiến tranh","hl":[]}],"answer":["C"],"note":""},{"id":"300","question":"So với chiến dịch Điện Biên Phủ 1954 với chiến dịch Hồ Chí Minh 1975 có khác gì về kết quả và ý nghĩa?","qHighlight":[],"options":[{"key":"A","text":"Đã đập tan hoàn toàn kế hoạch quân sự của địch, buộc địch phải kí kết hiệp định và rút quân về nước","hl":[]},{"key":"B","text":"Giải phóng hoàn toàn miền Bắc tạo tiền đề hoàn thành cuộc cách mạng dân chủ nhân dân trong cả nước","hl":[]},{"key":"C","text":"Làm xoay chuyển cục diện chiến tranh, tạo điều kiện thuận lợi để giành thắng lợi cuối cùng","hl":[]},{"key":"D","text":"Là dấu mốc kết thúc cuộc chiến tranh giải phóng dân tộc, bảo vệ Tổ quốc, chấm dứt ách thống trị của thực dân đế quốc","hl":[]}],"answer":["D"],"note":""},{"id":"301","question":"Điều kiện trực tiếp mở ra Phong trào dân chủ 1936 - 1939 do Đảng lãnh đạo là:","qHighlight":[],"options":[{"key":"A","text":"Khủng hoảng kinh tế thế giới 1929 - 1933","hl":[]},{"key":"B","text":"Quốc tế Cộng sản thay đổi chủ trương","hl":[]},{"key":"C","text":"Đảng Cộng sản Đông Dương ban hành chính sách mới","hl":[]},{"key":"D","text":"Chính phủ Mặt trận nhân dân lên cầm quyền ở Pháp","hl":[]}],"answer":["D"],"note":""},{"id":"302","question":"Nhiệm vụ kinh tế trọng tâm ở miền Bắc sau tháng 7/1954 được Đảng xác định:","qHighlight":[],"options":[{"key":"A","text":"Khôi phục và phát triển sản xuất nông nghiệp","hl":[]},{"key":"B","text":"Khôi phục và phát triển sản xuất công nghiệp","hl":[]},{"key":"C","text":"Khôi phục và phát triển tiểu thủ công nghiệp","hl":[]},{"key":"D","text":"Khôi phục và phát triển thương nghiệp","hl":[]}],"answer":["A"],"note":""},{"id":"303","question":"Ở Việt Nam, cuộc kháng chiến chống Mĩ, cứu nước (1954-1975) có điểm mới nào sau đây so với cuộc kháng chiến chống thực dân Pháp (1945-1954)?","qHighlight":[],"options":[{"key":"A","text":"Hoàn thành đồng thời nhiệm vụ kháng chiến và gây dựng cơ sở cho chế độ mới.","hl":[]},{"key":"B","text":"Thực hiện tư tưởng tiến công bằng sức mạnh của lực lượng vũ trang ba thứ quân.","hl":[]},{"key":"C","text":"Kết hợp khởi nghĩa từng phần của quần chúng nhân dân với chiến tranh cách mạng.","hl":[]},{"key":"D","text":"Tiến hành tuần tự hai cuộc cách mạng ở hai miền đất nước với mục tiêu thống nhất.","hl":[]}],"answer":["C"],"note":""},{"id":"304","question":"Trong thời kỳ 1954-1975, cuộc cách mạng dân tộc dân chủ nhân dân ở miền Nam Việt Nam có vai trò quyết định trực tiếp đối với sự nghiệp giải phóng miền Nam vì cuộc cách mạng này","qHighlight":[],"options":[{"key":"A","text":"bảo vệ vững chắc hậu phương miền Bắc xã hội chủ nghĩa.","hl":[]},{"key":"B","text":"làm thất bại hoàn toàn chiến lược toàn cầu của Mỹ.","hl":[]},{"key":"C","text":"trực tiếp xóa bỏ ách áp bức, bóc lột của địa chủ và tư sản miền Nam.","hl":[]},{"key":"D","text":"trực tiếp đánh đổ ách thống trị của Mỹ và chính quyền Sài Gòn.","hl":[]}],"answer":["D"],"note":""},{"id":"305","question":"Lãnh tụ Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên (1925) là sự chuẩn bị cho sự ra đời của Đảng Cộng sản Việt Nam về mặt:","qHighlight":[],"options":[{"key":"A","text":"Tổ chức","hl":[]},{"key":"B","text":"Tư tưởng","hl":[]},{"key":"C","text":"Chính trị","hl":[]},{"key":"D","text":"Đường lối chính sách","hl":[]}],"answer":["A"],"note":""},{"id":"306","question":"Nhân tố hàng đầu đảm bảo thắng lợi của cuộc kháng chiến chống Mĩ, cứu nước (1954-1975) là sự lãnh đạo của Đảng Cộng sản Việt Nam vì Đảng","qHighlight":[],"options":[{"key":"A","text":"tranh thủ được sự giúp đỡ của các nước xã hội chủ nghĩa.","hl":[]},{"key":"B","text":"có đường lối cách mạng đúng đắn, sáng tạo, độc lập tự chủ.","hl":[]},{"key":"C","text":"lãnh đạo xây dựng miền Bắc thành hậu phương vững mạnh. đã kết hợp sức mạnh toàn dân tộc với sức mạnh của thời đại.","hl":[]}],"answer":["B"],"note":""},{"id":"307","question":"Khẩu hiệu được Đảng đề ra trong giai đoạn giữ vững và củng cố chính quyền cách mạng 1945 - 1946 là:","qHighlight":[],"options":[{"key":"A","text":"Việt Nam độc lập muôn năm","hl":[]},{"key":"B","text":"Dân tộc trên hết, Tổ quốc trên hết","hl":["Dân tộc trên hết, Tổ quốc"]},{"key":"C","text":"Đoàn kết, đoàn kết, đại đoàn kết","hl":[]},{"key":"D","text":"Mặt trận Việt Minh muôn năm","hl":[]}],"answer":["B"],"note":""},{"id":"308","question":"Thực tiễn 30 năm chiến tranh cách mạng Việt Nam (1945 - 1975) cho thấy: Hậu phương của chiến tranh nhân dân","qHighlight":[],"options":[{"key":"A","text":"không thể phân biệt rạch ròi với tiền tuyến chỉ bằng yếu tố không gian.","hl":[]},{"key":"B","text":"ở phía sau và phân biệt rạch ròi với tiền tuyến bằng yếu tố không gian.","hl":[]},{"key":"C","text":"luôn ở phía sau và bảo đảm cung cấp sức người, sức của cho tiền tuyến.","hl":[]},{"key":"D","text":"là đối xứng của tiền tuyến, thực hiện nhiệm vụ chi viện cho tiền tuyến.","hl":[]}],"answer":["A"],"note":""},{"id":"309","question":"Hội nghị Trung ương 8 (5/1941) đã bầu ai làm Tổng Bí thư của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Nguyễn Ái Quốc","hl":[]},{"key":"B","text":"Nguyễn Văn Cừ","hl":[]},{"key":"C","text":"Trường Chinh","hl":[]},{"key":"D","text":"Lê Duẩn","hl":[]}],"answer":["C"],"note":""},{"id":"310","question":"Sau năm 1975, đất nước ta bước vào thời kì","qHighlight":[],"options":[{"key":"A","text":"kinh tế thị trường xã hội chủ nghĩa.","hl":[]},{"key":"B","text":"đất nước ta đã hòa bình, độc lập thống nhất, cả nước quá độ lên chủ nghĩa xã hội.","hl":[]},{"key":"C","text":"xây dựng xã hội chủ nghĩa.","hl":[]},{"key":"D","text":"công nghiệp hóa, hiện đại hóa.","hl":[]}],"answer":["B"],"note":""},{"id":"311","question":"Nhiệm vụ nào được đặt ra một cách bức thiết sau năm 1975?","qHighlight":[],"options":[{"key":"A","text":"Điều chỉnh các chủ thể kinh tế, các hành vi sản xuất kinh doanh và các quan hệ kinh tế.","hl":[]},{"key":"B","text":"Phát triển các đạo luật, các quy chế, chuẩn mực về kinh tế.","hl":[]},{"key":"C","text":"Thống nhất đất nước về mặt nhà nước.","hl":[]},{"key":"D","text":"Khôi phục kinh tế sau chiến tranh.","hl":[]}],"answer":["C"],"note":""},{"id":"312","question":"Đoàn đại biểu miền Nam do ai dẫn đầu để thống nhất hiệp thương với miền Bắc sau năm 1975?","qHighlight":[],"options":[{"key":"A","text":"Phạm Hùng","hl":[]},{"key":"B","text":"Châu Văn Liêm","hl":[]},{"key":"C","text":"Trường Chinh","hl":[]},{"key":"D","text":"Phạm Hữu Thọ","hl":[]}],"answer":["A"],"note":""},{"id":"313","question":"Sau đại thắng mùa xuân 1975, đất nước độc lập thống nhất, Chủ tịch nước là:","qHighlight":[],"options":[{"key":"A","text":"Phạm Hùng","hl":[]},{"key":"B","text":"Tôn Đức Thắng","hl":[]},{"key":"C","text":"Phạm Văn Đồng","hl":[]},{"key":"D","text":"Nguyễn Văn Linh","hl":[]}],"answer":["B"],"note":""},{"id":"314","question":"Tại Đại hội lần thứ V của Đảng đã bầu chức vụ Tổng Bí Thư Đảng là:","qHighlight":[],"options":[{"key":"A","text":"Lê Duẩn","hl":[]},{"key":"B","text":"Trường Chinh","hl":[]},{"key":"C","text":"Phạm Hùng","hl":[]},{"key":"D","text":"Nguyễn Hữu Thọ","hl":[]}],"answer":["A"],"note":""},{"id":"315","question":"Tổ chức tổng tuyển cử trên toàn lãnh thổ Việt Nam bầu ra Quốc hội chung cho cả nước vào đầu năm 1976 theo nguyên tắc nào?","qHighlight":[],"options":[{"key":"A","text":"Dân chủ, phổ thông, bình đẳng, trực tiếp và bỏ phiếu kín.","hl":[]},{"key":"B","text":"Hoàn thiện thể chế về chính trị và ổn định về kinh tế.","hl":[]},{"key":"C","text":"Hoàn thiện thể chế đảm bảo đồng bộ các yếu tố thị trường và phát triển đồng bộ các loại thị trường.","hl":[]},{"key":"D","text":"Hoàn thiện thể chế gắn tăng trưởng kinh tế với tiến bộ, công bằng xã hội và bảo vệ môi trường.","hl":[]}],"answer":["A"],"note":""},{"id":"316","question":"Đảng Cộng sản Việt Nam xác định thành phần kinh tế nhà nước có vai trò như thế nào trong nền kinh tế? Đảng xác định vai trò của thành phần kinh tế nhà nước là :","qHighlight":[],"options":[{"key":"A","text":"Giữ vai trò chủ đạo","hl":[]},{"key":"B","text":"Giữ vai trò đặc biệt","hl":[]},{"key":"C","text":"Giữ vai trò điều phối","hl":[]},{"key":"D","text":"Giữ vai trò thứ yếu","hl":[]}],"answer":["A"],"note":""},{"id":"317","question":"Mô hình kinh tế tổng quát của nước ta trong thời kỳ quá độ lên chủ nghĩa xã hội được Đại hội IX của Đảng (2001) xác định là:","qHighlight":[],"options":[{"key":"A","text":"Kinh tế thị trường tự do","hl":[]},{"key":"B","text":"Kinh tế hàng hóa nhiều thành phần","hl":[]},{"key":"C","text":"Kinh tế thị trường định hướng xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Kinh tế nhà nước và kinh tế tập thể","hl":[]}],"answer":["C"],"note":""},{"id":"318a","question":"Mô hình kinh tế thị trường định hướng xã hội chủ nghĩa ở nước ta được chính thức nêu ra ở Đại hội nào của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Đại hội VI (1986)","hl":[]},{"key":"B","text":"Đại hội VII (1991)","hl":[]},{"key":"C","text":"Đại hội VIII (1996)","hl":[]},{"key":"D","text":"Đại hội IX (2001)","hl":[]}],"answer":["D"],"note":"Khái niệm kinh tế thị trường định hướng XHCN được đưa vào văn kiện lần đầu tiên ở Đại hội IX (2001)"},{"id":"318b","question":"Cơ chế thị trường trong nền kinh tế Việt Nam từ 1986 - 1991 được xem là:","qHighlight":[],"options":[{"key":"A","text":"Chưa đầy đủ","hl":[]},{"key":"B","text":"Đầy đủ","hl":[]},{"key":"C","text":"Hoàn hảo","hl":[]},{"key":"D","text":"Hoàn thiện","hl":[]}],"answer":["A"],"note":""},{"id":"319","question":"Chiến lược \"Chiến tranh đặc biệt\" của Mỹ là gì?","qHighlight":[],"options":[{"key":"A","text":"Một hình thức mới của chủ nghĩa thực dân cũ, dựa trên nền tảng lực lượng quân nguỵ, dưới sự chỉ huy của cố vấn Mỹ, bằng phương tiện chiến tranh Mỹ","hl":[]},{"key":"B","text":"Một hình thức chiến tranh của chủ nghĩa thực dân mới, được tiến hành bằng quân đội viễn chinh Mỹ và quân chư hầu","hl":[]},{"key":"C","text":"Một hình thức chiến tranh của chủ nghĩa thực dân cũ, được tiến hành bằng Quân đội lính đánh thuê, dưới sự chỉ huy của cố vấn Mỹ, phương tiện chiến tranh Mỹ","hl":[]},{"key":"D","text":"Một hình thức chiến tranh của chủ nghĩa thực dân mới, được tiến hành bằng quân đội tay sai, dưới sự chỉ huy của cố vấn Mỹ, bằng phương tiện chiến tranh Mỹ","hl":[]}],"answer":["D"],"note":""},{"id":"320","question":"Điền thêm từ còn thiếu trong câu trích từ Nghị quyết Hội nghị ban chấp hành Trung ương Đảng lần 24 (1975) : \".... đất nước vừa là nguyện vọng tha thiết của nhân dân cả nước, vừa là quy luật khách quan cửa sự phát triển cách mạng Việt Nam, của lịch sử dân tộc Việt Nam\"","qHighlight":[],"options":[{"key":"A","text":"Độc lập","hl":[]},{"key":"B","text":"Thống nhất","hl":[]},{"key":"C","text":"Giải phóng","hl":[]},{"key":"D","text":"Độc lập và Thống nhất","hl":[]}],"answer":["B"],"note":""},{"id":"321","question":"Một trong những bài học trong 10 năm đổi mới đất nước 1986-1996 là :","qHighlight":[],"options":[{"key":"A","text":"Kinh tế thị trường nói chung và kinh tế thị trường định hướng XHCN khác nhau hoàn toàn","hl":[]},{"key":"B","text":"Kinh tế thị trường nói chung và kinh tế thị trường định hướng XHCN giống nhau về bản chất chỉ khác về hình thức","hl":[]},{"key":"C","text":"Kinh tế thị trường nói chung và kinh tế thị trường định hướng XHCN giống nhau hoàn toàn.","hl":[]},{"key":"D","text":"Xây dựng nền KT hàng hóa nhiều thành phần vận hành cơ chế thị trường, tăng cường quản lý Nhà nước theo định hướng XHCN. Tăng trưởng KT gắn tiến bộ công bằng XH, giữ và phát huy bản sắc văn hóa dân tộc, bảo vệ môi trường sinh thái.","hl":[]}],"answer":["D"],"note":""},{"id":"322","question":"Đâu là một trong những nội dung của Đại hội lần thứ IV của Đảng (12/1976)? Một trong những nội dung của Đại hội lần thứ 4 của Đảng (12-1976) là :","qHighlight":[],"options":[{"key":"A","text":"Kế hoạch nhà nước 5 năm 1976 - 1980","hl":[]},{"key":"B","text":"Phương hướng đổi mới đất nước","hl":[]},{"key":"C","text":"Tổng kết 10 năm đổi mới đất nước","hl":[]},{"key":"D","text":"Hàn gắn vết tHương chiến tranh","hl":[]}],"answer":["A"],"note":""},{"id":"323","question":"Đại hội Đảng lần thứ 8 họp tại Hà Nội từ ngày 28/6 - 1/7/1996 diễn ra trong bối cảnh nào?","qHighlight":[],"options":[{"key":"A","text":"Cách mạng khoa học và công nghệ phát triển với trình độ cao, chủ nghĩa xã hội hiện thực lâm vào thoái trào.","hl":[]},{"key":"B","text":"Thời kỳ quá độ lên chủ nghĩa xã hội đạt nhiều thành tựu to lớn,","hl":[]},{"key":"C","text":"Cách mạng khoa học và công nghệ phát triển với trình độ cao","hl":[]},{"key":"D","text":"Phong trào giải phóng dân tộc phát triển mạnh","hl":[]}],"answer":["A"],"note":""},{"id":"324","question":"Đại hội lần thứ IV của Đảng họp từ 14 - 20/12/1976 tại Hà Nội quyết định đổi tên Đảng thành :","qHighlight":[],"options":[{"key":"A","text":"Đảng Lao động Việt Nam","hl":[]},{"key":"B","text":"Đảng Cộng sản Đông Dương","hl":[]},{"key":"C","text":"Đảng Cộng sản Việt Nam","hl":[]},{"key":"D","text":"Đảng Cộng sản Hồ Chí Minh","hl":[]}],"answer":["C"],"note":""},{"id":"325","question":"Một trong những nhận thức mới của Đảng về chủ nghĩa xã hội là :","qHighlight":[],"options":[{"key":"A","text":"Phát tiển các doanh nghiệp nhà nước","hl":[]},{"key":"B","text":"Các tài sản thuộc sở hữu toàn dân","hl":[]},{"key":"C","text":"Các quỹ dự trữ quốc gia, quỹ bảo hiểm nhà nước","hl":[]},{"key":"D","text":"Xây dựng con người mới XHCN","hl":[]}],"answer":["D"],"note":""},{"id":"326","question":"Nhiệm vụ trung tâm của thời kỳ quá độ xây dựng đất nước là:","qHighlight":[],"options":[{"key":"A","text":"Đẩy mạnh Công nghiệp hóa xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Hợp tác xã nông nghiệp theo định hướng xã hội chủ nghĩa","hl":[]},{"key":"C","text":"Kinh tế thị trường định hướng xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Nắm vững các quy luật kinh tế của chủ nghĩa xã hội.","hl":[]}],"answer":["A"],"note":""},{"id":"328","question":"Ngày 17/2/1979, quân đội nước nào tấn công phía Bắc biên giới nước ta?","qHighlight":[],"options":[{"key":"A","text":"Mỹ","hl":[]},{"key":"B","text":"Khơme đỏ","hl":[]},{"key":"C","text":"Trung Quốc","hl":[]},{"key":"D","text":"Pháp","hl":[]}],"answer":["C"],"note":""},{"id":"329","question":"Một trong những mục tiêu của kế hoạch phát triển kinh tế và văn hóa 5 năm lần thứ 2 từ 1976 - 1980 của cả nước là:","qHighlight":[],"options":[{"key":"A","text":"Đổi mới tổ chức và phương thức hoạt động của Đảng","hl":[]},{"key":"B","text":"Đổi mới tổ chức và phương thức hoạt động của Nhà nước","hl":[]},{"key":"C","text":"Đổi mới tổ chức và phương thức hoạt động kinh tế xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Bảo đảm nhu cầu đời sống của nhân dân, tích lũy để xây dựng cơ sở vật chất kỹ thuật của chủ nghĩa xã hội","hl":[]}],"answer":["D"],"note":""},{"id":"330","question":"Trong mười năm từ 1979 - 1989, quan hệ Việt Nam- Trung Quốc trong tình hình :","qHighlight":[],"options":[{"key":"A","text":"Thân thiện","hl":[]},{"key":"B","text":"Phức tạp","hl":[]},{"key":"C","text":"Đóng băng","hl":[]},{"key":"D","text":"Bình thường hóa","hl":[]}],"answer":["B"],"note":""},{"id":"331","question":"Một trong những quan điểm của Đảng ta về Công nghiệp hóa- hiện đại hóa đất nước là:","qHighlight":[],"options":[{"key":"A","text":"Tập hợp, vận động, đoàn kết rộng rãi các tầng lớp nhân dân","hl":[]},{"key":"B","text":"Đại diện cho quyền và lợi ích hợp pháp của nhân dân","hl":[]},{"key":"C","text":"Đề xuất các chủ trương, chính sách về kinh tế, văn hóa, an ninh, quốc phòng","hl":[]},{"key":"D","text":"Lấy việc phát huy nguồn lực con người là yếu tố cơ bản cho sự phát triển nhanh và bền vững.","hl":[]}],"answer":["D"],"note":""},{"id":"332","question":"Mục tiêu xây dựng chủ nghĩa xã hội ở Việt Nam là:","qHighlight":[],"options":[{"key":"A","text":"Mở rộng quan hệ hợp tác với các nước trên thế giới","hl":[]},{"key":"B","text":"Kinh tế tư bản nhà nước","hl":[]},{"key":"C","text":"Kinh tế có vốn đầu tư nước ngoài theo định hướng xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Dân giàu, nước mạnh, xã hội công bằng, văn minh","hl":[]}],"answer":["D"],"note":""},{"id":"333","question":"Một trong những nhiệm vụ chiến lược mà Đại hội lần thứ V của Đảng khẳng định là :","qHighlight":[],"options":[{"key":"A","text":"Đảm bảo quyền lực thuộc về nhân dân","hl":[]},{"key":"B","text":"Xây dựng lực lượng cho Đảng Cộng sản Việt Nam","hl":[]},{"key":"C","text":"Bảo vệ vững chắc Tổ quốc Việt Nam xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Xây dựng nhà nước pháp quyền Việt Nam xã hội chủ nghĩa","hl":[]}],"answer":["C"],"note":""},{"id":"334","question":"Đại hội lần thứ V của Đảng (1982) đã coi lĩnh vực nào là Mặt trận hàng đầu?","qHighlight":[],"options":[{"key":"A","text":"Công nghiệp","hl":[]},{"key":"B","text":"Nông nghiệp","hl":[]},{"key":"C","text":"Thương nghiệp","hl":[]},{"key":"D","text":"Dịch vụ","hl":[]}],"answer":["B"],"note":""},{"id":"335","question":"Đaị hội nào được đánh giá là Đại hội đổi mới đất nước?","qHighlight":[],"options":[{"key":"A","text":"Đại hội IV 1976","hl":[]},{"key":"B","text":"Đại hội V 1982","hl":[]},{"key":"C","text":"Đại hội VI 1986","hl":[]},{"key":"D","text":"Đại hội VII 1991","hl":[]}],"answer":["C"],"note":""},{"id":"336","question":"Trọng tâm của đổi mới kinh tế tại Đại hội VI (1986) là :","qHighlight":[],"options":[{"key":"A","text":"Đổi mới cơ chế quản lý, xóa bỏ cơ chế tập trung quan liêu hành chính, bao cấp.","hl":[]},{"key":"B","text":"Đổi mới tổ chức và phương thức hoạt động của nhà nước","hl":[]},{"key":"C","text":"Đổi mới tổ chức và phương thức hoạt động của các tổ chức tư nhân","hl":[]},{"key":"D","text":"Đổi mới tổ chức và phương thức hoạt động của Mặt trận tổ quốc Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"337","question":"Ba chương trình kinh tế lớn của ta sau đổi mới kinh tế là:","qHighlight":[],"options":[{"key":"A","text":"Lương thực - thực phẩm, hàng tiêu dùng và hàng xuất khẩu","hl":[]},{"key":"B","text":"Lương thực - thực phẩm, hàng tiêu dùng","hl":[]},{"key":"C","text":"Nông-công nghiệp, dịch vụ","hl":[]},{"key":"D","text":"Công nghiệp, thương nghiệp, dịch vụ","hl":[]}],"answer":["A"],"note":""},{"id":"338","question":"Một trong những nội dung phát triển kinh tế mà Đại hôi Đảng lần thứ VI đề ra là :","qHighlight":[],"options":[{"key":"A","text":"Mở rộng và nâng cao hiệu quả kinh tế thị trường","hl":[]},{"key":"B","text":"Phát triển kinh tế tư nhân","hl":[]},{"key":"C","text":"Mở rộng và nâng cao hiệu quả kinh tế đối ngoại.","hl":[]},{"key":"D","text":"Mở rộng phất triển kinh tế hợp tác xã","hl":[]}],"answer":["C"],"note":""},{"id":"339","question":"Từ ngày 15 - 21/11/1975, Hội nghị Hiệp thương chính trị của 2 đoàn đại biểu miền Bắc - Nam đã họp tại:","qHighlight":["của 2 đoàn đại biểu"],"options":[{"key":"A","text":"Sài Gòn","hl":[]},{"key":"B","text":"Huế","hl":[]},{"key":"C","text":"Đà Nẵng","hl":[]},{"key":"D","text":"Hà Nội","hl":[]}],"answer":["A"],"note":""},{"id":"340","question":"Sự lãnh đạo toàn diện và tuyệt đối của Đảng là điểm cốt lõi của cơ sở chính trị trong hệ thống gì:","qHighlight":[],"options":[{"key":"A","text":"Hệ thống chính trị Chuyên chính vô sản","hl":[]},{"key":"B","text":"Hệ thống chính trị Dân chủ nhân dân","hl":[]},{"key":"C","text":"Hệ thống chính trị thời kỳ đổi mới","hl":[]}],"answer":["A"],"note":""},{"id":"341","question":"Chủ trương trong quan hệ quốc tế của Việt Nam được Đại hội Đảng lần thứ IX đưa ra là:","qHighlight":[],"options":[{"key":"A","text":"Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển.","hl":["sẵn sàng"]},{"key":"B","text":"Việt Nam muốn là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển.","hl":[]},{"key":"C","text":"Việt Nam là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển.","hl":[]},{"key":"D","text":"Việt Nam mong là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình độc lập và phát triển.","hl":[]}],"answer":["A"],"note":""},{"id":"342","question":"Trong quá trình đổi mới mới đất nước, Đảng cộng sản Việt Nam đóng vai trò là :","qHighlight":["ảng cộng sản Việt Nam"],"options":[{"key":"A","text":"Không tham gia trong hệ thống chính trị","hl":[]},{"key":"B","text":"Đóng vai trò trụ cột","hl":[]},{"key":"C","text":"Thực hiện vai trò một cách hạn chế trong hệ thống chính trị","hl":[]},{"key":"D","text":"Đóng vai trò thứ yếu","hl":[]}],"answer":["B"],"note":""},{"id":"343","question":"Một trong những bài học về đổi mới đất nước (1986-1996 ) là:","qHighlight":[],"options":[{"key":"A","text":"Kết hợp chặt chẽ đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm, từng bước đổi mới chính trị.","hl":[]},{"key":"B","text":"Đổi mới tư duy và phương thức hoạt động của các bộ phận cấu thành hệ thống.","hl":[]},{"key":"C","text":"Đổi mới nhận thức và phương thức hoạt động của các bộ phận cấu thành hệ thống.","hl":[]},{"key":"D","text":"Đổi mới tư tưởng và phương thức hoạt động của các bộ phận cấu thành hệ thống.","hl":[]}],"answer":["A"],"note":""},{"id":"344","question":"Nghị quyết Trung ương 4, khóa 8 tháng 12/1997 bầu ai làm Tổng bí thư của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Lê Khả Phiêu","hl":[]},{"key":"B","text":"Trường Chinh","hl":[]},{"key":"C","text":"Đỗ Mười","hl":[]},{"key":"D","text":"Nguyễn Văn Linh","hl":[]}],"answer":["A"],"note":""},{"id":"345","question":"Năm 1998, Việt Nam trở thành thành viên của :","qHighlight":[],"options":[{"key":"A","text":"ASEAN","hl":[]},{"key":"B","text":"APEC","hl":[]},{"key":"C","text":"Liên Hợp Quốc","hl":[]},{"key":"D","text":"WTO","hl":[]}],"answer":["B"],"note":""},{"id":"346","question":"Đường lối đối ngoại \"Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình, độc lập và phát triển\" được đưa ra ở Đại hội nào của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Đại hội VII (1991)","hl":[]},{"key":"B","text":"Đại hội VIII (1996)","hl":[]},{"key":"C","text":"Đại hội IX (2001)","hl":[]},{"key":"D","text":"Đại hội X (2006)","hl":[]}],"answer":["C"],"note":""},{"id":"347","question":"Trong quan hệ đối ngoại Đại hội 9 đưa ra chủ trương:","qHighlight":[],"options":[{"key":"A","text":"Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình, độc lập và phát triển.","hl":["bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế, phấn đấu vì hòa bình, độc lập và phát triển."]},{"key":"B","text":"Việt Nam sẵn sàng là bạn, là đối tác tin cậy của các nước trong cộng đồng quốc tế,","hl":[]},{"key":"C","text":"Việt Nam sẵn sàng là bạn của tất cả các nước.","hl":[]},{"key":"D","text":"Việt Nam sẵn sàng là bạn và ủng hộ phong trào hòa bình thế giới.","hl":[]}],"answer":["A"],"note":""},{"id":"348","question":"Hội nghị Trung ương 8 khóa 9 tháng 7/2003 đã ban hành:","qHighlight":[],"options":[{"key":"A","text":"Thực hiện dân chủ xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Kết hợp chặt chẽ ngay từ đầu đổi mới kinh tế với đổi mới chính trị","hl":[]},{"key":"C","text":"Đổi mới hệ thống chính trị một cách toàn diện, đồng bộ","hl":[]},{"key":"D","text":"Chiến lược bảo vệ Tổ quốc trong tình hình mới.","hl":[]}],"answer":["D"],"note":""},{"id":"349","question":"Hội nghị Trung ương 7 khóa 9 tháng 3/2003 đã thống nhất coi:","qHighlight":[],"options":[{"key":"A","text":"Đất đai là tài nguyên quốc gia vô cùng quý giá, là tư liệu đặc biệt, là nguồn nội lực và nguồn vốn to lớn của đất nước.","hl":[]},{"key":"B","text":"Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị làm cho nó phù hợp với đường lối đổi mới toàn diện, đồng bộ đất nước.","hl":[]},{"key":"C","text":"Đổi mới hệ thống chính trị một cách toàn diện, đồng bộ có kế thừa, có bước đi hình thức và cách làm phù hợp.","hl":[]},{"key":"D","text":"Đổi mới quan hệ giữa các bộ phận cấu thành của hệ thống chính trị với nhau và với xã hội là rất quan trọng.","hl":[]}],"answer":["A"],"note":""},{"id":"350","question":"Đường lối Đổi mới được Đảng đề ra tại Đại hội VI (1986) nhằm:","qHighlight":[],"options":[{"key":"A","text":"Thay đổi mục tiêu xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Làm cho mục tiêu xã hội chủ nghĩa được thực hiện tốt hơn","hl":["chủ nghĩa được thực hiện tốt hơn"]},{"key":"C","text":"Từ bỏ những nguyên lý của chủ nghĩa Mác - Lênin","hl":[]},{"key":"D","text":"Thực hiện đa nguyên chính trị, đa đảng đối lập","hl":[]}],"answer":["B"],"note":""},{"id":"351","question":"Chủ đề của Đại hội Đảng lần thứ 10 từ ngày 18 - 25/4/2006 tại Hà Nội là :","qHighlight":[],"options":[{"key":"A","text":"Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phát huy sức mạnh toàn dân tộc","hl":[]},{"key":"B","text":"Nâng cao năng lực lãnh đạo, phát triển công nghiệp hóa- hiện đại hóa đất nước.","hl":[]},{"key":"C","text":"Phát triển và hội nhập quốc tế","hl":[]},{"key":"D","text":"Nâng cao năng lực lãnh đạo và sức chiến đấu của Đảng, phát huy sức mạnh toàn dân tộc, đẩy mạnh toàn diện công cuộc đổi mới sớm đưa nước ta ra khỏi tình trạng kém phát triển.","hl":[]}],"answer":["D"],"note":""},{"id":"352","question":"Quan điểm mới nổi bật của Đại hội Đảng lần thứ X (2006) là đã cho phép:","qHighlight":[],"options":[{"key":"A","text":"Đảng viên làm kinh tế tư nhân","hl":[]},{"key":"B","text":"Đảng viên tự ứng cử và đề cử","hl":[]},{"key":"C","text":"Đảng viên được tự do xuất cảnh","hl":[]},{"key":"D","text":"Đảng viên được tự do kết hôn với người nước ngoài","hl":[]}],"answer":["A"],"note":""},{"id":"353","question":"Chủ trương cho phép đảng viên làm kinh tế tư nhân được Đảng chính thức thông qua tại Đại hội lần thứ mấy?","qHighlight":["353: Chủ trương"],"options":[{"key":"A","text":"Đại hội IX (2001)","hl":[]},{"key":"B","text":"Đại hội X (2006)","hl":[]},{"key":"C","text":"Đại hội XI (2011)","hl":[]},{"key":"D","text":"Đại hội XII (2016)","hl":[]}],"answer":["B"],"note":""},{"id":"354","question":"Một trong những nội dung mới của Đại hội Đảng lần thứ X là:","qHighlight":[],"options":[{"key":"A","text":"Xây dựng, chỉnh đốn Đảng là nhiệm vụ then chốt hàng đầu và cho phép đảng viên làm kinh tế tư nhân.","hl":[]},{"key":"B","text":"Xây dựng chủ nghĩa xã hội","hl":[]},{"key":"C","text":"Xây dựng hệ thống chính trị","hl":[]},{"key":"D","text":"Xây dựng kinh tế tư nhân","hl":[]}],"answer":["A"],"note":""},{"id":"355","question":"Đâu không phải là bài học kinh nghiệm mà Đại hội Đảng lần thứ X đã rút ra?","qHighlight":[],"options":[{"key":"A","text":"Đổi mới toàn diện,đồng bộ có kế thừa, bước đi, hình thức cách làm phù hợp","hl":[]},{"key":"B","text":"Đổi mới phải vì lợi ích của nhân dân, dựa vào dân, phát huy vai trò chủ động, sáng tạo của nhân dân, xuất phát từ thực tiễn, nhạy bén với cái mới.","hl":[]},{"key":"C","text":"Phát huy cao độ nội lực, ra sức khai thác ngoại lực, kết hợp sức mạnh dân tộc và thời đại trong điều kiện mới.","hl":[]},{"key":"D","text":"Lấy đổi mới chính trị làm thứ yếu, đồng thời từng bước đổi mới kinh tế.","hl":[]}],"answer":["D"],"note":""},{"id":"356","question":"Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội được Đại hội Đảng lần thứ VII (1991) thông qua xác định xã hội chủ nghĩa mà nhân dân ta xây dựng có mấy đặc trưng cơ bản?","qHighlight":[],"options":[{"key":"A","text":"4","hl":[]},{"key":"B","text":"5","hl":[]},{"key":"C","text":"6","hl":[]},{"key":"D","text":"7","hl":[]}],"answer":["C"],"note":""},{"id":"357","question":"Hội nghị Trung ương 5 khóa 10 tháng 7/2007 ban hành Nghị quyết số14- NQ/TW về :","qHighlight":[],"options":[{"key":"A","text":"Tăng cường công tác kiểm tra, giám sát của Đảng","hl":[]},{"key":"B","text":"Tăng cường công tác kiểm tra, giám sát của đoàn thể","hl":[]},{"key":"C","text":"Cương lĩnh xây dựng đất nước","hl":[]},{"key":"D","text":"Thay đổi hệ thống chính trị","hl":[]}],"answer":["A"],"note":""},{"id":"358","question":"Cương lĩnh Đại hội Đảng lần thứ 11 diễn ra từ 12 - 19/1/2011 nêu rõ: Xã hội xã hội chủ nghĩa mà nhân dân ta xây dựng là một xã hội:","qHighlight":[],"options":[{"key":"A","text":"Của dân, do dân, vì dân","hl":[]},{"key":"B","text":"Của dân, do dân, vì dân có nền kinh tế phát triển","hl":[]},{"key":"C","text":"Dân giàu, nước mạnh, dân chủ, công bằng, văn minh","hl":[]},{"key":"D","text":"Dân giàu, nước mạnh, dân chủ, công bằng, văn minh do nhân dân làm chủ","hl":["mạnh, dân chủ, công bằng, văn minh do nhân dân làm chủ"]}],"answer":["D"],"note":""},{"id":"359","question":"Đại hội lần thứ 11 đề ra chiến lược phát triển kinh tế- xã hội 2011-2020 là :","qHighlight":[],"options":[{"key":"A","text":"Phát triển nhanh gắn liền với phát triển bền vững","hl":[]},{"key":"B","text":"Phát tiển gắn với xây dựng","hl":[]},{"key":"C","text":"Đẩy mạnh hội nhập quốc tế","hl":[]},{"key":"D","text":"Xây dựng nền kinh tế tựu chủ","hl":[]}],"answer":["A"],"note":""},{"id":"360","question":"Năm 2012 có bao nhiêu nước công nhận cơ chế kinh tế thị trường của Việt Nam?","qHighlight":[],"options":[{"key":"A","text":"36 nước","hl":[]},{"key":"B","text":"38 nước","hl":[]},{"key":"C","text":"40 nước","hl":[]},{"key":"D","text":"44 nước","hl":[]}],"answer":["A"],"note":""},{"id":"361","question":"Việt Nam gia nhập tổ chức ASEAN năm nào?","qHighlight":[],"options":[{"key":"A","text":"1993","hl":[]},{"key":"B","text":"1994","hl":[]},{"key":"C","text":"1995","hl":[]},{"key":"D","text":"1997","hl":[]}],"answer":["C"],"note":""},{"id":"362","question":"Đại hội đại biểu toàn quốc lần thứ XIII Đảng Cộng sản Việt Nam họp từ ngày nào?","qHighlight":[],"options":[{"key":"A","text":"từ ngày 23.1-1.2.2021","hl":[]},{"key":"B","text":"từ ngày 25.1-1.2.2021","hl":[]},{"key":"C","text":"từ ngày 26.1-1.2.2021","hl":[]},{"key":"D","text":"từ ngày 24.1-1.2.2021","hl":[]}],"answer":["B"],"note":""},{"id":"363","question":"Về Kết quả thực hiện Nghị quyết Đại hội XII, Đại hội XIII đánh giá lĩnh vực nào dưới đây chưa trở thành động lực then chốt thúc đẩy phát triển kinh tế - xã hội?","qHighlight":[],"options":[{"key":"A","text":"Giáo dục và đào tạo, khoa học và công nghệ","hl":[]},{"key":"B","text":"Khoa học và công nghệ","hl":[]},{"key":"C","text":"Văn hóa xã hội","hl":[]},{"key":"D","text":"Giáo dục và đào tạo","hl":[]}],"answer":["A"],"note":""},{"id":"364","question":"Tháng 11/2006, Bộ Chính trị khóa 10 ra Chỉ thị số 3-NQ/TW là quyết định tổ chức cuộc vận động :","qHighlight":["3-NQ/TW"],"options":[{"key":"A","text":"Nói đi đôi với làm","hl":[]},{"key":"B","text":"Phát triển kinh tế tăng trưởng ổn định, hiệu quả.","hl":[]},{"key":"C","text":"Thi đua lập thành tích chào mừng Đại hội","hl":[]},{"key":"D","text":"Học tập và làm theo tấm gương đạo đức Hồ Chí Minh.","hl":[]}],"answer":["D"],"note":""},{"id":"365","question":"Tác hại nào do cơ chế quản lý kinh tế tập trung, quan liêu, bao cấp vẫn tồn tại đến ngày nay và rất khó xóa bỏ?","qHighlight":[],"options":[{"key":"A","text":"Không tạo được động lực phát triển.","hl":[]},{"key":"B","text":"Không thúc đẩy sản xuất phát triển","hl":[]},{"key":"C","text":"Làm giảm năng suất, chất lượng, hiệu quả.","hl":[]},{"key":"D","text":"Nhiều hiện tượng tiêu cực trong xã hội.","hl":[]}],"answer":["D"],"note":""},{"id":"366","question":"Khẩu hiệu của Đại hội lần thứ XII của Đàng là :","qHighlight":[],"options":[{"key":"A","text":"Đoàn kết-Dân chủ-Kỷ cương- Đổi mới","hl":[]},{"key":"B","text":"Đẩy mạnh toàn diện đồng bộ công cuộc đổi mới","hl":[]},{"key":"C","text":"Tăng cường khối Đại đoàn kết toàn dân tộc","hl":[]},{"key":"D","text":"Xây dựng Đảng trong sạch, vững mạnh","hl":[]}],"answer":["A"],"note":""},{"id":"367","question":"Bộ Chính trị ban hành Chỉ thị số 5-CT/TW ngày 15/5/2016 về:","qHighlight":[],"options":[{"key":"A","text":"Thống nhất nhận thức về kinh tế thị trường định hướng XHCN.","hl":[]},{"key":"B","text":"Hoàn thiện thể chế về sở hữu và các thành phần kinh tế.","hl":[]},{"key":"C","text":"Học tập và làm theo tư tưởng Hồ Chí Minh.","hl":[]},{"key":"D","text":"Đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh.","hl":[]}],"answer":["D"],"note":""},{"id":"368","question":"Thời gian từ tháng 3 năm 1946 đến ngày 19/12/1946, Đảng lãnh đạo nhân dân thực hiện chủ trương chiến lược:","qHighlight":[],"options":[{"key":"A","text":"Hòa để tiến","hl":[]},{"key":"B","text":"Đối đầu với quân đội Pháp","hl":[]},{"key":"C","text":"Đối đầu với quân đội Tưởng","hl":[]},{"key":"D","text":"Giải giáp quân đội Nhật","hl":[]}],"answer":["A"],"note":""},{"id":"369","question":"Mở rộng các lĩnh vực kinh tế thuộc độc quyền nhà nước là vi phạm nguyên tắc","qHighlight":[],"options":[{"key":"A","text":"Hoàn thiện thể chế gắn tăng trưởng kinh tế với tiến bộ, công bằng xã hội và bảo vệ môi trường.","hl":[]},{"key":"B","text":"Hoàn thiện thể chế về sở hữu và các thành phần kinh tế.","hl":[]},{"key":"C","text":"Hoàn thiện thể chế đảm bảo đồng bộ các yếu tố thị trường và phát triển đồng bộ các loại thị trường.","hl":[]},{"key":"D","text":"Hoàn thiện thể chế chính trị","hl":[]}],"answer":["B"],"note":""},{"id":"370","question":"Hội nghị Trung ương 5 khóa 12, tháng 5/2017 chủ trương:","qHighlight":[],"options":[{"key":"A","text":"Chủ trương phát triển kinh tế thị trường định hướng XHCN","hl":[]},{"key":"B","text":"Chủ trương phát triển kinh tế thị trường tư bản chủ nghĩa","hl":[]},{"key":"C","text":"Chủ trương phát triển kinh tế chỉ huy","hl":[]},{"key":"D","text":"Hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa.","hl":["kinh tế thị trường định hướng xã hội chủ nghĩa"]}],"answer":["D"],"note":""},{"id":"371","question":"Hội nghị Trung ương 7 khóa 12 đã ban hành Nghị quyết số 27-NQ/TW ngày 21/5/2018 về:","qHighlight":[],"options":[{"key":"A","text":"Cải cách chính sách tiền lương đối với cán bộ, công viên chức, lực lượng vũ trang và người lao động trong doanh nghiệp.","hl":[]},{"key":"B","text":"Xây dựng văn hóa trong tình hình mới","hl":[]},{"key":"C","text":"Hội nhập trong tình hình mới","hl":[]},{"key":"D","text":"Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới.","hl":[]}],"answer":["A"],"note":""},{"id":"372","question":"Hội nghị Trung ương 7 khóa 12 đã ban hành Nghị quyết số 28-NQ/TW ngày 23/5/2018 về:","qHighlight":[],"options":[{"key":"A","text":"Đổi mới mục tiêu, con đường đi lên xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Đổi mới nội dung, phương thức hoạt động, tổ chức cán bộ và quan hệ giữa các tổ chức trong hệ thống chính trị","hl":[]},{"key":"C","text":"Tăng cường công tác bảo vệ, chăm sóc và nâng cao sức khỏe nhân dân trong tình hình mới","hl":[]},{"key":"D","text":"Cải cách chính sách bảo hiểm xã hội.","hl":[]}],"answer":["D"],"note":""},{"id":"373","question":"Hội nghị trung ương VI khoá 6 (tháng 3 năm 1989) lần đầu tiên đưa ra thuật ngữ gì?","qHighlight":[],"options":[{"key":"A","text":"Kinh tế thị trường định hướng xã hội chủ nghĩa","hl":[]},{"key":"B","text":"Hệ thống chính trị","hl":[]},{"key":"C","text":"Nhà nước pháp quyền xã hội chủ nghĩa","hl":[]},{"key":"D","text":"Đảng lãnh đạo, nhà nước quản lý, nhân dân làm chủ","hl":[]}],"answer":["B"],"note":""},{"id":"374","question":"Xây dựng Đảng ngang tầm với thời kì Công nghiệp hóa- Hiện đại hóa đất nước đòi hỏi :","qHighlight":[],"options":[{"key":"A","text":"Thực hiện tốt hơn dân chủ xã hội chủ nghĩa, phát huy đầy đủ quyền làm chủ của nhân dân.","hl":[]},{"key":"B","text":"Thực hiện tốt hơn dân chủ xã hội chủ nghĩa, phát huy đầy đủ quyền tự do của nhân dân.","hl":[]},{"key":"C","text":"Thực hiện tốt hơn dân chủ xã hội chủ nghĩa, phát huy đầy đủ quyền giám sát của nhân dân.","hl":[]},{"key":"D","text":"Đảng phải tiếp tục tự đổi mới, tự chỉnh đốn, nâng cao hơn nữa sức chiến đấu và năng lực lãnh đạo của mình, khắc phục cho được các biểu hiện tiêu cực và yếu kém.","hl":[]}],"answer":["D"],"note":""},{"id":"375","question":"Đại hội XIII đã đề ra mấy đột phá chiến lược để phát triển đất nước?","qHighlight":[],"options":[{"key":"A","text":"3 đột phá","hl":[]},{"key":"B","text":"4 đột phá","hl":[]},{"key":"C","text":"5 đột phá","hl":[]},{"key":"D","text":"6 đột phá","hl":[]}],"answer":["A"],"note":""},{"id":"376","question":"Một trong những đột phá chiến lược mà Đại hội XIII đề ra là:","qHighlight":[],"options":[{"key":"A","text":"Xây dựng hệ thống kết cấu hạ tầng đồng bộ, hiện đại cả về kinh tế- xã hội","hl":["kinh tế- xã hội"]},{"key":"B","text":"Đổi mới chính trị, đồng thời, từng bước đổi mới hệ thống chính trị","hl":[]},{"key":"C","text":"Đổi mới tư duy an ninh quốc phòng, đồng thời, từng bước đổi mới hệ thống chính trị","hl":[]},{"key":"D","text":"Đổi mới an sinh xã hội, đồng thời, từng bước đổi mới hệ thống chính trị","hl":[]}],"answer":["A"],"note":""},{"id":"377","question":"Mọi công việc của Đảng, Nhà nước phải quán triệt sâu sắc lấy dân làm gốc, dân làm trung tâm, kiên trì thực hiện phương châm:","qHighlight":[],"options":[{"key":"A","text":"Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát, dân thụ hưởng","hl":[]},{"key":"B","text":"Dân biết, dân bàn, dân làm, dân kiểm tra, dân giám sát","hl":[]},{"key":"C","text":"Dân biết, dân bàn, dân làm, dân kiểm tra","hl":[]},{"key":"D","text":"Của dân, do dân và vì dân","hl":[]}],"answer":["A"],"note":""},{"id":"244","question":"Sau khi giành chính quyền, Đảng chủ trương mở rộng mặt trận nào sau đây để tập trung ngọn lửa đấu tranh chống Pháp?","qHighlight":[],"options":[{"key":"A","text":"Mặt trận Việt Minh","hl":[]},{"key":"B","text":"Mặt trận Liên Việt","hl":[]},{"key":"C","text":"Mặt trận Dân chủ","hl":[]},{"key":"D","text":"Mặt trận tổ quốc Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"327","question":"Mặt trận Tổ quốc Việt Nam, Đoàn thanh niên Lao động HCM, Tổng Công đoàn Việt Nam, Hội Liên hiệp phụ nữ Việt Nam v.v. được gọi là :","qHighlight":[],"options":[{"key":"A","text":"Đảng cộng sản Việt Nam.","hl":[]},{"key":"B","text":"Các tổ chức đoàn thể","hl":[]},{"key":"C","text":"Mặt trận tổ quốc Việt Nam","hl":[]},{"key":"D","text":"Các tổ chức chính trị - xã hội","hl":[]}],"answer":["D"],"note":""},{"id":"378","question":"\"Đại diện cho quyền và lợi ích hợp pháp của nhân dân\" là vai trò của tổ chức nào?","qHighlight":[],"options":[{"key":"A","text":"Đảng Cộng sản Việt Nam","hl":[]},{"key":"B","text":"Đoàn thanh niên Cộng sản Hồ Chí Minh","hl":[]},{"key":"C","text":"Nhà Nước Việt Nam","hl":[]},{"key":"D","text":"Mặt trận Tổ quốc Việt Nam và các tổ chức chính trị - xã hội","hl":[]}],"answer":["D"],"note":""},{"id":"390","question":"Nghị quyết Trung ương III, tháng 6/1997 đã chú trọng nội dung nào sau đây? Nội dung nào của Nghị quyết Trung ương 3, tháng 6/1997 về phát huy quyền ?","qHighlight":[],"options":[{"key":"A","text":"Làm chủ của nhân dân","hl":[]},{"key":"B","text":"Lãnh đạo của Đảng","hl":[]},{"key":"C","text":"Của các tổ chức chính trị-xã hội","hl":[]},{"key":"D","text":"Của Mặt trận tổ quốc","hl":[]}],"answer":["A"],"note":""},{"id":"379","question":"Việt Nam hoàn thành nhiệm vụ thống nhất đất nước về mặt nhà nước vào","qHighlight":[],"options":[{"key":"A","text":"tháng 5/1975.","hl":[]},{"key":"B","text":"tháng 9/1975","hl":[]},{"key":"C","text":"tháng 7/1976.","hl":[]},{"key":"D","text":"tháng 12/1976.","hl":[]}],"answer":["C"],"note":""},{"id":"380","question":"Một trong những bài học về kinh tế mà Đảng rút ra trong 10 năm đổi mới đất nước 1986 - 1996 là gì?","qHighlight":[],"options":[{"key":"A","text":"Xây dựng kinh tế bao cấp","hl":[]},{"key":"B","text":"Xây dựng kinh tế Hợp tác xã","hl":[]},{"key":"C","text":"Xây dựng kinh tế tư nhân","hl":[]},{"key":"D","text":"Xây dựng nền kinh tế hàng hóa nhiều thành phần vận hành theo cơ chế thị trường","hl":[]}],"answer":["D"],"note":""},{"id":"381","question":"Một trong những bài học kinh nghiệm được rút ra trong 10 năm đổi mới đất nước (1986-1996) là:","qHighlight":[],"options":[{"key":"A","text":"Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị là nhằm thay đổi cách lãnh đạo của Đảng, hiệu lực quản lý của nhà nước, phát huy quyền làm chủ của nhân dân.","hl":[]},{"key":"B","text":"Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị là nhằm tăng cường vai trò lãnh đạo của Đảng, hiệu lực quản lý của nhà nước, phát huy quyền làm chủ của nhân dân.","hl":[]},{"key":"C","text":"Kết hợp chặt chẽ đổi mới kinh tế với đổi mới chính trị, lấy đổi mới kinh tế làm trọng tâm, từng bước đổi mới chính trị.","hl":[]},{"key":"D","text":"Đổi mới tổ chức và phương thức hoạt động của hệ thống chính trị là nhằm giảm bớt vai trò lãnh đạo của Đảng, hiệu lực quản lý của nhà nước, phát huy quyền làm chủ của nhân dân.","hl":[]}],"answer":["C"],"note":""},{"id":"382","question":"Quan điểm quan trọng về giải quyết các vấn đề xã hội thời kỳ đổi mới là:","qHighlight":[],"options":[{"key":"A","text":"Ưu tiên mục tiêu xã hội trên mục tiêu kinh tế","hl":[]},{"key":"B","text":"Kết hợp các mục tiêu kinh tế với các mục tiêu xã hội","hl":[]},{"key":"C","text":"Chú trọng các mục tiêu kinh tế, từng bước thực hiện mục tiêu xã hội","hl":[]},{"key":"D","text":"Thực hiện mục tiêu xã hội trên cơ sở thực hiện thắng lợi các mục tiêu kinh tế","hl":[]}],"answer":["B"],"note":""},{"id":"383","question":"Tên gọi \"Nước Cộng hoà xã hội chủ nghĩa Việt Nam\" có từ khi nào ?","qHighlight":[],"options":[{"key":"A","text":"Ngày 2/9/1945.","hl":[]},{"key":"B","text":"Ngày 2/7/1976.","hl":[]},{"key":"C","text":"Ngày 12/2/1951.","hl":[]},{"key":"D","text":"Ngày 2/7/1975.","hl":[]}],"answer":["B"],"note":""},{"id":"384","question":"Trong 10 năm đổi mới đất nước vấn đề tăng cường vai trò lãnh đạo của Đảng, coi xây dựng Đảng là :","qHighlight":[],"options":[{"key":"A","text":"Nhiệm vụ then chốt","hl":[]},{"key":"B","text":"Nhiệm vụ quan trọng","hl":[]},{"key":"C","text":"Động lực phát triển","hl":[]},{"key":"D","text":"Gắn liền với phát triển kinh tế","hl":[]}],"answer":["A"],"note":""},{"id":"385","question":"Công nghiệp hóa- Hiện đại hóa đất nước là sự nghiệp của :","qHighlight":["nghiệp hóa- Hiện"],"options":[{"key":"A","text":"Toàn dân","hl":[]},{"key":"B","text":"Đảng Cộng sản Việt Nam","hl":[]},{"key":"C","text":"Cơ quan quản lý nhà nước về văn hóa","hl":[]},{"key":"D","text":"Nhà nước Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"386","question":"Đại hội lần thứ VIII của Đảng chủ trương tăng trưởng kinh tế gắn liền với tiến bộ và công bằng xã hội trong điều kiện nào?","qHighlight":[],"options":[{"key":"A","text":"Trong cả thời kỳ quá độ và suốt quá trình phát triển","hl":[]},{"key":"B","text":"Trong từng bước và suốt quá trình phát triển","hl":[]},{"key":"C","text":"Trong riêng thời kỳ quá độ và suốt quá trình phát triển","hl":[]},{"key":"D","text":"Trong từng bước và suốt quá trình xây dựng thể chế kinh tế thị trường","hl":[]}],"answer":["B"],"note":""},{"id":"387","question":"Hội nghị Trung ương 2, khóa 8, tháng12/1996 nhận định phát triển khoa học và công nghệ là :","qHighlight":[],"options":[{"key":"A","text":"Ưu tiên phát triển hàng đầu trong quá trình công nghiệp hóa- hiện đại hóa đất nước","hl":["hàng đầu trong quá trình công nghiệp hóa- hiện đại hóa đất nước"]},{"key":"B","text":"Quan trọng nhất trong quá trình đổi mới đất nước.","hl":[]},{"key":"C","text":"Ưu tiên phát triển hàng đầu trong quá trình hội nhập","hl":[]},{"key":"D","text":"Nhân tố quyết định tăng trưởng kinh tế xã hội","hl":[]}],"answer":["A"],"note":""},{"id":"388","question":"Nội dung nào không đúng trong đặc trưng chủ yếu của đường lối công nghiệp hoá thời kỳ trước đổi mới?","qHighlight":[],"options":[{"key":"A","text":"Nóng vội, giản đơn, duy ý chí, ham làm nhanh, làm lớn, không quan tâm đến hiệu quả kinh tế - xã hội.","hl":[]},{"key":"B","text":"Công nghiệp hóa theo mô hình nền kinh tế khép kín hướng nội và thiên về phát triển công nghiệp nặng.","hl":[]},{"key":"C","text":"Chủ lực thực hiện công nghiệp hóa là Nhà nước và các doanh nghiệp nhà nước.","hl":[]},{"key":"D","text":"Công nghiệp hóa được thực hiện thông qua cơ chế thị trường định hướng xã hội chủ nghĩa.","hl":["Công nghiệp hóa"]}],"answer":["D"],"note":""},{"id":"389","question":"Hội nghị Trung ương 3, khóa 8 Đảng đã chủ trương: Hội nghị Trung ương III, khóa VIII (1997) của Đảng đã chủ trương:","qHighlight":[],"options":[{"key":"A","text":"Thực hiện thắng lợi sự nghiệp công nghiệp hóa, hiện đại hóa","hl":[]},{"key":"B","text":"Xây dựng đội ngũ cán bộ các cấp có phẩm chất và năng lực, có bản lĩnh chính trị vững vàng","hl":[]},{"key":"C","text":"Xây dựng đội ngũ cán bộ các cấp có phẩm chất và năng lực, có bản lĩnh chính trị vững vàng, đủ về số lượng, đồng bộ về cơ cấu","hl":[]},{"key":"D","text":"Liên minh công nhân, nông dân và tầng lớp trí thức","hl":[]}],"answer":["C"],"note":""},{"id":"391","question":"Hội nghị Trung ương 5 khóa 9 tháng 3/2002 đã thống nhất nhận thức về sự cần thiết phát triển kinh tế tập thể và thảo luận, thống nhất nhận thức coi:","qHighlight":[],"options":[{"key":"A","text":"Kinh tế tư nhân đã phát triển rộng khắp trong cả nước, đóng góp quan trọng vào phát triển kinh tế","hl":[]},{"key":"B","text":"Kinh tế nhà nước đã phát triển rộng khắp trong cả nước, đóng góp quan trọng vào phát triển kinh tế","hl":[]},{"key":"C","text":"Sự lãnh đạo của Đảng quyết định sự phát triển kinh tế đất nước","hl":[]},{"key":"D","text":"Chủ nghĩa Mác Lênin, tư tưởng Hồ Chí Minh ngày càng giữ vai trò chủ đạo","hl":[]}],"answer":["A"],"note":""},{"id":"392","question":"Đại hội VIII đưa ra luận điểm quan trọng về công nghiệp hóa là","qHighlight":[],"options":[{"key":"A","text":"Giai đoạn chuẩn bị các tiền đề công nghiệp hóa đất nước đã cơ bản hoàn thành, cho phép ta chuyển sang giai đọan đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước.","hl":["ta chuyển sang giai đọan đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước"]},{"key":"B","text":"Công nghiệp hóa được nhận thức là \"công nghiệp hóa - hiện đại hóa\".","hl":[]},{"key":"C","text":"Công nghiệp hóa được nhận thức là \"công nghiệp hóa- hiện đại hóa gắn với phát triển kinh tế tri thức\".","hl":[]},{"key":"D","text":"Công nghiệp hóa được nhận thức là \"công nghiệp hóa- hiện đại hóa gắn với phát triển kinh tế tri thức trong cơ chế thị trường định hướng XHCN và hội nhập kinh tế quốc tế\".","hl":[]}],"answer":["A"],"note":""},{"id":"393","question":"Sự kiện lịch sử nào mở ra tiền đề để Việt Nam thúc đẩy quan hệ với khu vực và cộng đồng quốc tế?","qHighlight":[],"options":[{"key":"A","text":"Bình thường hóa quan hệ với Trung Quốc","hl":[]},{"key":"B","text":"Việt Nam tham gia ký Hiệp định Pari (23/10/1991) về một giải pháp toàn diện cho vấn đề Campuchia","hl":[]},{"key":"C","text":"Bình thường hóa quan hệ với Hoa Kỳ","hl":[]},{"key":"D","text":"Việt Nam gia nhập hiệp hội các nước Đông Nam Á (Asean)","hl":[]}],"answer":["B"],"note":""},{"id":"394","question":"\"Tranh thủ được nguồn viện trợ đáng kể, góp phần khôi phục đất nước sau chiến tranh\" là một trong những ý nghĩa của ngoại giao Việt Nam thời kỳ nào?","qHighlight":[],"options":[{"key":"A","text":"Sau đổi mới (1975-1985)","hl":[]},{"key":"B","text":"Trước đổi mới (1945-1985)","hl":[]},{"key":"C","text":"Sau đổi mới (1985 - 1995)","hl":[]},{"key":"D","text":"Trước đổi mới (1975-1985)","hl":[]}],"answer":["D"],"note":""},{"id":"395","question":"Điền vào chỗ trống. Mục tiêu cụ thể được nêu trong đại hội lần thứ XIII của Đảng đó là: \"Đến năm 2025, kỷ niệm 50 năm giải phóng hoàn toàn miền Nam, thống nhất đất nước: là nước đang phát triển, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập....\"","qHighlight":[],"options":[{"key":"A","text":"Trung bình thấp","hl":[]},{"key":"B","text":"Trung bình cao","hl":[]},{"key":"C","text":"Trung bình","hl":[]},{"key":"D","text":"Trung bình kém phát triển","hl":[]}],"answer":["A"],"note":""},{"id":"396","question":"Hội nghị Trung ương 8 khóa 9 đã ban hành Nghị quyết số 36-NQ/TW ngày 26/3/2004 về công tác đối với :","qHighlight":[],"options":[{"key":"A","text":"Biến đổi khí hậu","hl":[]},{"key":"B","text":"Công nghiệp hóa, hiện đại hóa","hl":[]},{"key":"C","text":"Người Việt Nam ở nước ngoài","hl":[]},{"key":"D","text":"Phát triển giáo dục","hl":[]}],"answer":["C"],"note":""},{"id":"397","question":"Việt Nam và Trung Quốc bình thường hóa quan hệ vào thời gian nào?","qHighlight":[],"options":[{"key":"A","text":"11-1-2007","hl":[]},{"key":"B","text":"13-7-2001","hl":[]},{"key":"C","text":"10-11-1991","hl":[]},{"key":"D","text":"12-7-1995","hl":[]}],"answer":["C"],"note":""},{"id":"398","question":"Hội nghị Trung ương 3 khóa 10 ban hành Nghị quyết số 04-NQ/TW ngày 21/8/2006 về:","qHighlight":[],"options":[{"key":"A","text":"Mở rộng thị trường, trao đổi hàng hóa tăng mạnh đã thúc đẩy sản xuất hàng hóa của các nước","hl":[]},{"key":"B","text":"Nguồn vốn, khoa học công nghệ, kinh nghiệm quản lý cùng các hình thức đầu tư, hợp tác mang lại lợi ích cho các bên.","hl":[]},{"key":"C","text":"Tăng cường sự lãnh đạo của Đảng với công tác đấu tranh phòng, chống tham nhũng lãng phí.","hl":[]},{"key":"D","text":"Các nước công nghiệp phát triển thao túng, chi phối quá trình toàn cầu hóa tạo ra sự bất bình đẳng trong quan hệ quốc tế và làm gia tăng sự phân cực giữa nước giàu và nghèo.","hl":[]}],"answer":["C"],"note":""},{"id":"399","question":"Một trong những nhiệm vụ trọng tâm trong nhiệm kỳ đại hội đã được Đại hội Đảng lần thứ XIII nêu ra là :","qHighlight":[],"options":[{"key":"A","text":"Tiếp tục đẩy mạnh xây dựng, chỉnh đốn Đảng, xây dựng Nhà nước pháp quyền xã hội chủ nghĩa và hệ thống chính trị toàn diện, trong sạch, vững mạnh. Đổi mới phương thức lãnh đạo, cầm quyền của Đảng","hl":[]},{"key":"B","text":"Ưu tiên phát triển công nghiệp công nghệ trung bình, công nghiệp chế tác, công nghiệp phần mềm và công nghiệp bổ trợ có lợi thế cạnh tranh","hl":[]},{"key":"C","text":"Tập trung phát triển công nghiệp nặng, công nghiệp chế tác, công nghiệp phần mềm và công nghiệp bổ trợ có lợi thế cạnh tranh","hl":[]},{"key":"D","text":"Khuyến khích phát triển tiểu thủ công nghiệp, công nghiệp chế tác, công nghiệp phần mềm và công nghiệp bổ trợ có lợi thế cạnh tranh","hl":[]}],"answer":["A"],"note":""},{"id":"400","question":"Tại Đại hội đại biểu toàn quốc lần thứ IV (1976), chủ trương, nhận định nào của Đảng ta được đánh giá là chủ quan, nóng vội? Chủ trương, nhận định nào là hạn chế của Đảng tại Đại hội lần thứ IV (1976)?","qHighlight":[],"options":[{"key":"A","text":"Hoàn thành về cơ bản quá trình đưa nền kinh tế nước ta từ sản xuất nhỏ lên sản xuất lớn xã hội chủ nghĩa trong khoảng 20 năm","hl":[]},{"key":"B","text":"Quá độ lên chủ nghĩa xã hội ở nước ta là thời kỳ khó khăn, phức tạp, lâu dài, phải trải qua nhiều chặng đường","hl":[]},{"key":"C","text":"Nước ta đã thống nhất, cả nước tiến lên chủ nghĩa xã hội","hl":[]},{"key":"D","text":"Nước ta đang ở trong quá trình từ một xã hội kinh tế sản xuất nhỏ tiến thẳng lên chủ nghĩa xã hội","hl":[]}],"answer":["A"],"note":""},{"id":"401","question":"Trung ương nhận định như thế nào về Chiến lược kinh tế Biển ở thế kỉ XXI ?","qHighlight":[],"options":[{"key":"A","text":"Biển là tiềm năng kinh tế to lớn của đất nước","hl":[]},{"key":"B","text":"Việt Nam phải là quốc gia mạnh về biển.","hl":[]},{"key":"C","text":"Việt Nam phải trở thành quốc gia mạnh về biển, làm giàu từ biển","hl":[]},{"key":"D","text":"Việt Nam phải trở thành quốc gia mạnh về biển, làm giàu từ biển, trên cơ sở phát huy mọi tiềm năng từ biển, phát triển toàn diện các ngành, nghề biển.","hl":[]}],"answer":["D"],"note":""},{"id":"402","question":"Tại sao phải Tăng cường công tác kiểm tra, giám sát của Đảng?","qHighlight":[],"options":[{"key":"A","text":"Đảng là nhân tố hàng đầu lãnh đạo cách mạng Việt Nam thắng lợi.","hl":[]},{"key":"B","text":"Kiểm tra, giám sát là nội dung rất quan trọng trong lãnh đạo của Đảng.","hl":[]},{"key":"C","text":"Kiểm tra, giám sát là nội dung rất quan trọng trong lãnh đạo của Đảng, điều kiện để xây dựng Đảng trong sạch vững mạnh.","hl":[]},{"key":"D","text":"Kiểm tra, giám sát là nội dung rất quan trọng trong lãnh đạo của Đảng, là nhiệm vụ thường xuyên của toàn Đảng, trước hết là cấp ủy và người đứng đầu cấp ủy.","hl":[]}],"answer":["D"],"note":""},{"id":"403","question":"Vì sao đất nước đã độc lập vẫn xây dựng giai cấp công nhân Việt Nam trong thời kỳ đẩy mạnh công nghiệp hóa- hiện đại hóa đất nước?","qHighlight":[],"options":[{"key":"A","text":"Giai cấp công nhân là động lực phát triển kinh tế","hl":[]},{"key":"B","text":"Giai cấp công nhân đại diện cho phương thức sản xuất hiện đại.","hl":[]},{"key":"C","text":"Giai cấp lãnh đạo cách mạng thông qua đội tiền phong là Đảng Cộng sản Việt Nam , là giai cấp đại diện cho phương thức sản xuất tiên bộ.","hl":[]},{"key":"D","text":"Giai cấp lãnh đạo cách mạng thông qua đội tiền phong là Đảng Cộng sản Việt Nam, là giai cấp đại diện cho phương thức sản xuất tiên tiến, tiên phong đi đầu trong sự nghiệp công nghiệp hóa- hiện đại hóa đất nước.","hl":[]}],"answer":["D"],"note":""},{"id":"404","question":"Tại sao, Đại hội 5 - 1982 lại nhận thức và coi nông nghiệp là mặt trận hàng đầu?","qHighlight":[],"options":[{"key":"A","text":"Phù hợp với thời kỳ quá độ xây dựng xã hội chủ nghĩa.","hl":[]},{"key":"B","text":"Phù hợp với thời kỳ quá độ xây dựng xã hội chủ nghĩa, hội nhập quốc tế.","hl":[]},{"key":"C","text":"Nhận thức đó phù hợp với nước ta để khai thác thế mạnh, tiềm năng của đất nước về lao động, đất đai, ngành nghề v.v, tạo tiền đề cho những chặng đường tiếp theo.","hl":[]},{"key":"D","text":"Nhận thức đó phù hợp với nước ta để khai thác thế mạnh, tiềm năng của đất nước về lao động, đất đai, ngành nghề , động lực phát triển công nghiệp hóa-hiện đại hóa đất nước.","hl":[]}],"answer":["C"],"note":""},{"id":"405","question":"Tại sao, cần cải cách chính sách tiền lương, bảo hiểm xã hội và trợ cấp ưu đãi người có công giai đoạn 2008 - 2012?","qHighlight":[],"options":[{"key":"A","text":"Việc trả lương đúng cho người lao động là thực hiện đầu tư cho phát triển, tạo động lực cho phát triển kinh tế-xã hội.","hl":[]},{"key":"B","text":"Việc trả lương đúng cho người lao động sẽ khuyến khích người giỏi hăng say lao động và đó động lực phát triển đất nước.","hl":[]},{"key":"C","text":"Việc trả lương đúng cho người lao động là thực hiện đầu tư cho phát triển, tạo động lực cho phát triển kinh tế-xã hôi, góp phần làm trong sạch và nâng cao hiệu lực, hiệu quả hoạt động của bộ máy nhà nước","hl":[]},{"key":"D","text":"Sẽ tạo động lực cho phát triển kinh tế-xã hôi, góp phần làm trong sạch và nâng cao hiệu lực, hiệu quả hoạt động của bộ máy nhà nước","hl":[]}],"answer":["C"],"note":""},{"id":"406","question":"Đảng đánh giá như thế nào về bộ phận công chức nhà nước hiện nay?","qHighlight":[],"options":[{"key":"A","text":"Tình trạng quan liêu, hách dịch, nhũng nhiễu của một bộ phận công chức chưa được khắc phục","hl":[]},{"key":"B","text":"Tình trạng quan liêu, hách dịch, nhũng nhiễu của tất cả công chức còn phổ biến.","hl":[]},{"key":"C","text":"Tình trạng quan liêu, hách dịch, nhũng nhiễu của một bộ phận công chức đã được khắc phục.","hl":[]},{"key":"D","text":"Tình trạng quan liêu, hách dịch, nhũng nhiễu của tất cả công chức chưa được khắc phục.","hl":[]}],"answer":["A"],"note":""},{"id":"407","question":"Nhận xét nào là đúng về hạn chế của nước ta sau 10 năm đổi mới 1986-1996?","qHighlight":[],"options":[{"key":"A","text":"Việt Nam vẫn là nước nghèo, kém phát triển, xã hội còn nhiều tiêu cực và nhiều vấn đề phải giải quyết.","hl":[]},{"key":"B","text":"Việt Nam vẫn là nước nghèo, kém phát triển, xã hội còn nhiều tiêu cực","hl":[]},{"key":"C","text":"Việt Nam vẫn là nước nghèo, phát triển còn mất cân đối","hl":[]},{"key":"D","text":"Việt Nam vẫn là nước nghèo nàn, lạc hậu","hl":[]}],"answer":["A"],"note":""},{"id":"408","question":"Đại hội lần thứ VII Quốc tế Cộng sản (7/1935) xác định kẻ thù nguy hiểm trước mắt của nhân dân thế giới là:","qHighlight":[],"options":[{"key":"A","text":"Chủ nghĩa phát xít","hl":[]},{"key":"B","text":"Chủ nghĩa đế quốc","hl":[]},{"key":"C","text":"Chủ nghĩa tư bản","hl":[]},{"key":"D","text":"Chủ nghĩa Tờ rốt kít","hl":[]}],"answer":["A"],"note":""},{"id":"409","question":"Đổi mới không phải là thay đổi mục tiêu chủ nghĩa xã hội mà phải","qHighlight":[],"options":[{"key":"A","text":"làm cho chủ nghĩa xã hội ngày càng tốt đẹp hơn.","hl":[]},{"key":"B","text":"làm cho mục tiêu ấy được thực hiện có hiệu quả.","hl":["làm cho mục tiêu ấy được thực hiện"]},{"key":"C","text":"làm cho mục tiêu đã đề ra nhanh chóng được thực hiện.","hl":[]},{"key":"D","text":"làm cho mục tiêu đã đề ra phù hợp với thực tiễn đất nước.","hl":[]}],"answer":["B"],"note":""},{"id":"410","question":"Một trong những nhiệm vụ trọng tâm mà Đại hội XII đã nêu (2011-2016)","qHighlight":[],"options":[{"key":"A","text":"Đẩy mạnh công nghiệp hóa xã hội chủ nghĩa, xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội, đưa nền kinh tế nước ta từ sản xuất lớn lên sản xuất đại quy mô xã hội chủ nghĩa.","hl":[]},{"key":"B","text":"Sự nghiệp của nhà nước và các doanh nghiệp liên doanh","hl":[]},{"key":"C","text":"Sự nghiệp của toàn dân, của mọi thành phần kinh tế, trong đó kinh tế nhà nước là chủ đạo","hl":[]},{"key":"D","text":"Tập trung thực hiện các giải pháp nâng cao chất lượng tăng trưởng, năng suất lao động và sức cạnh tranh của nền kinh tế.","hl":[]}],"answer":["D"],"note":""},{"id":"411","question":"Trong đường lối Chiến lược phát triển kinh tế- xã hội 2011-2020 Đảng ta chú trọng phát triển vấn đề nào sau đây?","qHighlight":[],"options":[{"key":"A","text":"Phát triển công nghiệp hóa xã hội chủ nghĩa, xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội","hl":[]},{"key":"B","text":"Phát triển công nghiệp hóa hiện đại hóa nông nghiệp nông thôn...","hl":[]},{"key":"C","text":"Đẩy mạnh công nghiệp hóa xã hội chủ nghĩa, xây dựng cơ sở vật chất - kỹ thuật của chủ nghĩa xã hội, đưa nền kinh tế nước ta từ sản xuất lớn lên sản xuất đại quy mô xã hội chủ nghĩa.","hl":[]},{"key":"D","text":"Phát triển nhanh nguồn nhân lực, nhất là nguồn nhân lực chất lượng cao.","hl":["lực, nhất là nguồn nhân lực chất lượng cao."]}],"answer":["D"],"note":""},{"id":"412","question":"Tháng 6-1925 gắn với sự ra đời của tổ chức nào?","qHighlight":[],"options":[{"key":"A","text":"Hội Việt Nam cách mạng thanh niên","hl":[]},{"key":"B","text":"Cộng sản Đảng","hl":[]},{"key":"C","text":"Quốc dân Đảng","hl":[]},{"key":"D","text":"Đảng cộng sản Việt Nam","hl":[]}],"answer":["A"],"note":""},{"id":"413","question":"Hội nghị thành lập Đảng Cộng sản Việt Nam được tổ chức ở đâu?","qHighlight":[],"options":[{"key":"A","text":"Hà Nội","hl":[]},{"key":"B","text":"Chiêm Hóa (Tuyên Quang)","hl":[]},{"key":"C","text":"Cửu Long- Hương Cảng-Trung Quốc","hl":[]},{"key":"D","text":"Quảng Châu- Trung Quốc","hl":[]}],"answer":["C"],"note":""}],"tips":[{"id":"tip-1","group":"Giai đoạn 1911–1945","icon":"🏛️","title":"Xã hội VN thời Pháp thuộc & Phong trào yêu nước đầu TK XX","summary":"Nắm chắc tính chất xã hội, 2 cuộc khai thác thuộc địa, sự phân hóa giai cấp TRƯỚC vs TRONG khai thác và các khuynh hướng yêu nước.","bullets":["Tính chất xã hội: <b>Thuộc địa nửa phong kiến</b>; Mâu thuẫn chủ yếu: <b>Dân tộc VN ↔ Đế quốc Pháp</b>.","Pháp tiến hành <b>2 cuộc khai thác thuộc địa</b> → làm cơ cấu kinh tế mất cân đối, lạc hậu.","<b>TRƯỚC</b> khai thác lần 1: chỉ có <b>Địa chủ + Nông dân</b>. <b>TRONG/SAU</b> khai thác: xuất hiện thêm <b>Công nhân, Tiểu tư sản, Tư sản dân tộc</b>.","<b>Phan Châu Trinh</b> = xu hướng cải cách; <b>VN Quốc dân Đảng</b> = dân chủ tư sản; <b>Công nhân</b> = lực lượng lãnh đạo, <b>Nông dân</b> = động lực cách mạng."],"questionIds":["14","22","23","62","63","72","76","130","134","141","142","143","146","152","162","190"]},{"id":"tip-2","group":"Giai đoạn 1911–1945","icon":"⭐","title":"Hành trình Nguyễn Ái Quốc & Thành lập Đảng (1919–1930)","summary":"Ghép chính xác từng mốc năm, tờ báo/tác phẩm với mặt chuẩn bị (Tư tưởng – Chính trị – Tổ chức) và 3 tổ chức cộng sản 1929.","bullets":["<b>1919</b>: Quốc tế III (Quốc tế Cộng sản) thành lập + NAQ gia nhập Đảng Xã hội Pháp.","<b>7/1920</b>: Đọc Sơ thảo Luận cương Lênin trên báo <b>Nhân đạo</b> → tìm ra con đường cứu nước (công lao đầu tiên).","<b>10/1923</b>: Dự Đại hội <b>Quốc tế Nông dân</b> | <b>6/1924</b>: Dự <b>ĐH V Quốc tế Cộng sản</b>.","3 mặt chuẩn bị: <b>Báo Người cùng khổ (Le Paria)</b> = <i>Tư tưởng</i> | <b>Đường Kách Mệnh</b> = <i>Tư tưởng chính trị</i> | <b>Hội VNCMTN (6/1925, Quảng Châu)</b> = <i>Tổ chức</i> (\"quả trứng nở ra con chim non Cộng sản\", mở lớp huấn luyện cán bộ).","<b>1929</b>: Hội VNCMTN phân hóa thành <b>Đông Dương CSĐ</b> (ra đời đầu tiên) + <b>An Nam CSĐ</b>.","<b>Đầu 1930 (Cửu Long – Hương Cảng)</b>: <b>Đông Dương CS Liên đoàn</b> <i>KHÔNG</i> tham dự! Thông qua 3 văn kiện (thể hiện trong 4 văn kiện). ĐCSVN = <b>Mác-Lênin + PT Công nhân + PT Yêu nước</b>."],"questionIds":["1","3","36","38","61","64","65","67","94","106a","114","121","123","133","135","136","140","147","148","149","150","151","154","165","177","179","184","186","191","305","412","413"]},{"id":"tip-3","group":"Giai đoạn 1911–1945","icon":"⚖️","title":"So sánh Cương lĩnh 2/1930 vs Luận cương 10/1930","summary":"Cặp văn kiện kinh điển cực hay ra câu phân biệt đúng/sai và hạn chế!","bullets":["<b>Giống nhau</b>: Đều khẳng định vai trò lãnh đạo của Đảng Cộng sản.","<b>Cương lĩnh 2/1930 (Nguyễn Ái Quốc — Chánh cương, Sách lược vắn tắt)</b>: Đặt <b>chống đế quốc / giải phóng dân tộc</b> lên hàng đầu; đánh đổ đế quốc, phong kiến, tư sản phản cách mạng; tập hợp rộng rãi nhiều tầng lớp; động lực: <b>Công nhân + Nông dân</b>.","<b>Luận cương 10/1930 (Trần Phú — Tổng Bí thư đầu tiên)</b>: Đổi tên thành <b>ĐCS Đông Dương</b>; <b>Hạn chế lớn nhất</b> là <i>KHÔNG đưa ngọn cờ giải phóng dân tộc lên hàng đầu</i>, nặng về đấu tranh giai cấp, chỉ xác định lực lượng công – nông."],"questionIds":["20","28","30","66","68","69","103","108","116","120","137","138","153","156","160","163","170","173","188","189"]},{"id":"tip-4","group":"Giai đoạn 1911–1945","icon":"🔥","title":"Phong trào 1930–1931, Phục hồi 1932–1935 & Dân chủ 1936–1939","summary":"Phân biệt nhanh 3 giai đoạn trước Thế chiến II bằng khẩu hiệu, tên Mặt trận và phương pháp đấu tranh.","bullets":["<b>1930–1931 (Tập dượt thứ nhất)</b>: Xô Viết Nghệ Tĩnh (1/5/1930); 2 khẩu hiệu <i>\"Độc lập dân tộc\"</i> + <i>\"Ruộng đất dân cày\"</i>; Mặt trận: <b>Hội phản đế Đông Dương</b>; Biểu tình có vũ trang tự vệ; 4/1931 là chi bộ QTCS; Ảnh hưởng khủng hoảng kinh tế 1929–1933.","<b>1932–1935</b>: Phục hồi tổ chức Đảng; tuyên truyền bằng <b>bút chiến công khai</b>; <b>ĐH I (3/1935, Ma Cao)</b> bầu <b>Lê Hồng Phong</b>; <b>ĐH VII QTCS (7/1935)</b> xác định kẻ thù trước mắt là <b>Chủ nghĩa phát xít</b>.","<b>1936–1939 (Phong trào dân chủ)</b>: Nhờ Mặt trận Nhân dân cầm quyền ở Pháp → kết hợp <b>công khai và bí mật</b>; Mục tiêu trước mắt: <b>tự do, dân chủ, cơm áo, hòa bình (các quyền dân chủ đơn sơ)</b>; Kẻ thù: phản động thuộc địa, phát xít, chiến tranh; Mặt trận: 7/1936 (<i>Thống nhất nhân dân phản đế ĐD</i>) → 1938 (<i>Mặt trận Dân chủ ĐD</i>)."],"questionIds":["55","70","71","73","80","81","82","86","98","99","102","106b","107","111","112","118","124","131","155","158","161","166","169","171","174","176","192","301","408"]},{"id":"tip-5","group":"Giai đoạn 1911–1945","icon":"🚩","title":"Chuyển hướng 1939–1945 & Tổng khởi nghĩa Tháng Tám","summary":"Nhớ quy tắc \"6 mở đầu – 7 tiếp tục – 8 hoàn thiện\" và các mốc dẫn tới ngày 2/9/1945.","bullets":["<b>HNTW 6 (11/1939)</b>: <b>BẮT ĐẦU</b> chuyển hướng chiến lược (sau khi Thế chiến II nổ ra 1939), lập <i>Mặt trận dân tộc thống nhất phản đế ĐD</i>.","<b>HNTW 8 (5/1941)</b>: <b>HOÀN THIỆN</b> chuyển hướng; bầu <b>Trường Chinh</b> làm TBT; giải phóng dân tộc bức thiết nhất, <b>tạm gác</b> khẩu hiệu ruộng đất; lập <b>Mặt trận Việt Minh (19/5/1941)</b>; trọng tâm: <b>chuẩn bị khởi nghĩa</b>; chủ trương nước <b>VN Dân chủ Cộng hòa (Cộng hòa dân chủ)</b>.","<b>22/9/1940</b>: Nhật xâm lược VN | Căn cứ địa đầu tiên: <b>Bắc Sơn – Võ Nhai</b>.","<b>12/3/1945</b>: <b>Ban Thường vụ TW Đảng</b> ra Chỉ thị <i>\"Nhật – Pháp bắn nhau và hành động của chúng ta\"</i>.","<b>Quốc dân ĐH Tân Trào</b> (do <b>Tổng bộ Việt Minh</b> triệu tập) → Ủy ban DTGP VN → Chính phủ lâm thời; Khởi nghĩa quyết định ở <b>Hà Nội</b> → <b>2/9/1945</b> Tuyên ngôn Độc lập (CM giải phóng dân tộc)."],"questionIds":["16","17","19","25","29","32","50","74","75","77","78","79","84","85","88","89","91","92","96","97","101","104","105","110","113","125","157","164","167","168","172","178","180","182","185","230","309"]},{"id":"tip-6","group":"Kháng chiến 1945–1975","icon":"🕊️","title":"Giai đoạn \"Ngàn cân treo sợi tóc\" (1945–1946): Hòa Tưởng → Hòa Pháp","summary":"Phân biệt mốc thời gian sách lược ngoại giao cực kỳ linh hoạt ngay sau Cách mạng Tháng Tám.","bullets":["Tình thế: <b>\"Ngàn cân treo sợi tóc\"</b>, khó khăn lớn nhất là <b>thù trong, giặc ngoài</b>; >90% mù chữ → phong trào <b>Bình dân học vụ</b>; Phiên họp đầu 3/9/1945: <b>3 nhiệm vụ lớn</b>; Khẩu hiệu: <i>\"Dân tộc trên hết, Tổ quốc trên hết\"</i>.","<b>23/9/1945</b>: Pháp nổ súng xâm lược lần 2 → phong trào <b>Nam tiến</b>; <b>11/11/1945</b>: Đảng tự giải tán → <i>Hội nghiên cứu CN Mác ở ĐD</i>.","<b>Chỉ thị Kháng chiến kiến quốc (25/11/1945)</b>: Kẻ thù chính = <b>Thực dân Pháp</b>; Nhiệm vụ bao trùm = <b>Củng cố, bảo vệ chính quyền</b>; Đối ngoại = <i>ít kẻ thù hơn hết, nhiều bạn đồng minh hơn hết</i>.","<b>9/1945 – 3/1946</b>: <b>Hòa với Tưởng</b> (<i>\"Hoa Việt thân thiện\"</i>, tiêu tiền TQ, cấp lương thực) để đánh Pháp.","<b>3/1946 – 19/12/1946</b>: <b>Hòa với Pháp để đuổi Tưởng</b> (<i>\"Hòa để tiến\"</i>) → <b>Hiệp định Sơ bộ (6/3/1946)</b> (VN là quốc gia tự do trong khối Liên hợp Pháp, ngừng bắn Nam Bộ) + <b>Tạm ước</b>."],"questionIds":["44","60","117","122","206","207","208","209","210","218","220","223","227","229","231","237","238","239","240","244","245","246","247","249","270","272","273","281","307","368"]},{"id":"tip-7","group":"Kháng chiến 1945–1975","icon":"⚔️","title":"Toàn quốc kháng chiến chống Pháp, Đại hội II & Điện Biên Phủ (1946–1954)","summary":"Trọn bộ đường lối kháng chiến, 3 văn kiện gốc, Đại hội II (1951), Điện Biên Phủ và Giơnevơ.","bullets":["<b>3 văn kiện Đường lối kháng chiến</b>: <i>Chỉ thị Toàn dân kháng chiến (12/12/1946)</i> + <i>Lời kêu gọi toàn quốc kháng chiến (19/12/1946 — Hồ Chí Minh)</i> + <i>Kháng chiến nhất định thắng lợi (Trường Chinh)</i>.","Phương châm: <b>Toàn dân, toàn diện, lâu dài, tự lực cánh sinh</b> (<i>tự cấp, tự túc về mọi mặt</i>). Căn cứ địa: <b>Việt Bắc</b> (Thu-Đông 1947 đánh bại kế hoạch \"đánh nhanh thắng nhanh\").","<b>Đại hội II (2/1951, Tuyên Quang)</b> — <i>\"Đại hội kháng chiến thắng lợi\"</i>: TBT <b>Trường Chinh</b>; đổi tên thành <b>Đảng Lao động Việt Nam</b>, lập đảng riêng ở Lào & Campuchia; 3/1951 lập Liên minh VN-Lào-Campuchia.","<b>Điện Biên Phủ (13/3 – 7/5/1954)</b>: <b>3 đợt</b>, phương châm <b>\"Đánh chắc, tiến chắc\"</b>, phá sản hoàn toàn <b>Kế hoạch Nava</b>, ví như <i>Bạch Đằng, Chi Lăng, Đống Đa TK XX</i>.","<b>Hiệp định Giơnevơ (7/1954)</b>: Trưởng đoàn <b>Phạm Văn Đồng</b>; giải pháp <b>chính trị</b>; giới tuyến <b>Vĩ tuyến 17 (sông Bến Hải)</b>; cam kết <b>4 quyền dân tộc cơ bản</b>."],"questionIds":["4","21","26","58","115","132","139","175","193","194","195","196","198","203","205","214","215","219","221","222","226","232","233","242","243","248","250","251","252","253","254","256","257","258","259","260","261","262","263","264","267","268","269","274","276","282","298","300"]},{"id":"tip-8","group":"Kháng chiến 1945–1975","icon":"🎯","title":"4 Chiến lược chiến tranh của Mỹ (1954–1975) — Bảng nhớ siêu tốc!","summary":"Mẹo thuộc lòng 4 giai đoạn chiến tranh của Mỹ (từ ảnh ghi chú trong file gốc) kèm bước ngoặt ứng với từng giai đoạn.","bullets":["<b>1954–1960: Chiến tranh đơn phương</b> (Luật 10/59 \"Tố cộng, diệt cộng\") → <b>HNTW 15 (1/1959)</b> cho dùng bạo lực cách mạng → <b>Đồng Khởi (1960)</b> (khởi nghĩa đầu tiên ở <b>Bình Định</b>, chuyển sang <b>thế tiến công</b>, lập MTDTGP miền Nam ở <b>Tây Ninh</b>, CT <b>Nguyễn Hữu Thọ</b>).","<b>1961–1965: Chiến tranh đặc biệt</b> — Âm mưu <i>\"Dùng người Việt đánh người Việt\"</i>, quân tay sai + cố vấn & vũ khí Mỹ, ấp chiến lược.","<b>1965–1968: Chiến tranh cục bộ</b> — HNTW 11 & 12 (1965): <i>\"Tất cả để đánh thắng giặc Mỹ xâm lược\"</i>; HNTW 13 (1/1967) mở <b>mặt trận ngoại giao</b> → <b>Mậu Thân 1968</b> đánh bại ý chí xâm lược, buộc Mỹ ngừng ném bom miền Bắc lần 1 & đàm phán.","<b>1969–1973: Việt Nam hóa chiến tranh</b> (Tổng thống R. Ních-xơn) → <b>Hiệp định Paris (1/1973)</b> buộc Mỹ rút quân, cam kết 4 quyền dân tộc cơ bản."],"questionIds":["13","18","24","39","57","95","119","126","129","187","199","200","202","212","213","216","225","241","266","277","278","283","285","286","287","288","289","290","292","299","319"]},{"id":"tip-9","group":"Kháng chiến 1945–1975","icon":"🏆","title":"Đại hội III (1960), Đường lối 2 miền & Đại thắng Mùa Xuân 1975","summary":"Phân biệt vai trò quyết định nhất (Bắc) vs quyết định trực tiếp (Nam) và chuỗi mốc chiến dịch Xuân 1975.","bullets":["<b>Sau 7/1954</b>: Đất nước chia 2 miền, 2 chế độ; Miền Bắc làm hậu phương lớn, khôi phục kinh tế (trọng tâm <b>nông nghiệp</b>); Đường Trường Sơn mở năm <b>1959</b>.","<b>Đại hội III (9/1960, Hà Nội)</b>: <b>2 chiến lược cách mạng</b> mật thiết thúc đẩy nhau: Miền Bắc (<b>XHCN</b>) = <b>quyết định nhất</b> (trung tâm: CNH XHCN) | Miền Nam (<b>DTDCND</b>) = <b>quyết định trực tiếp</b>. Hạn chế: nhận thức về CNXH còn giản đơn.","<b>Xuân 1975</b>: Đề ra <b>2 kế hoạch</b>; <b>Phước Long (1/1975)</b> = <i>đòn thăm dò chiến lược</i>; Mở màn = <b>Chiến dịch Tây Nguyên (3/1975)</b>; 18/3/1975 quyết giải phóng <b>trước mùa mưa 1975</b>; Lệnh <i>\"Thần tốc...\"</i> = <b>Võ Nguyên Giáp</b>; Kết thúc = <b>Chiến dịch Hồ Chí Minh (4/1975)</b>, Tư lệnh <b>Văn Tiến Dũng</b>."],"questionIds":["9","10","15","31","33","37","47","54","83","93","100","144","159","201","204","211","217","224","228","235","236","255","265","271","279","284","291","293","294","302","303","304","306","308"]},{"id":"tip-10","group":"Thống nhất & Đổi mới","icon":"🇻🇳","title":"Thống nhất đất nước (1975–1976) & Đại hội IV (1976), V (1982)","summary":"Các mốc thống nhất về mặt Nhà nước, biên giới 1979–1988 và đặc trưng Đại hội IV, V.","bullets":["<b>Thống nhất Nhà nước (1975–1976)</b>: HNTW 24: <i>Thống nhất đất nước</i>; Hiệp thương 11/1975 tại <b>Sài Gòn</b> (Đoàn miền Nam: <b>Phạm Hùng</b>); Tổng tuyển cử <b>4/1976</b>; Quốc hội khóa VI đặt tên <b>CHXHCN Việt Nam (2/7/1976)</b>, Chủ tịch nước <b>Tôn Đức Thắng</b>.","<b>Đại hội IV (12/1976)</b>: TBT <b>Lê Duẩn</b>; <i>\"Đại hội toàn thắng\"</i>; Đổi tên thành <b>Đảng Cộng sản Việt Nam</b>; <b>3 đặc điểm lớn</b> (lớn nhất: từ sản xuất nhỏ tiến thẳng lên CNXH bỏ qua TBCN); Kế hoạch 5 năm 1976–1980; Hạn chế chủ quan nóng vội: muốn xong trong ~20 năm.","<b>Bảo vệ biên giới & Đột phá</b>: <b>17/2/1979</b> TQ tấn công biên giới phía Bắc (1979–1989 quan hệ phức tạp); <b>3/1988</b> Gạc Ma; <b>HNTW 6 (8/1979)</b> = bước đột phá đầu tiên đổi mới kinh tế.","<b>Đại hội V (1982)</b>: TBT <b>Lê Duẩn</b>; Lần đầu đề ra <b>2 nhiệm vụ chiến lược</b> (<i>Xây dựng CNXH</i> — hàng đầu — và <i>Bảo vệ vững chắc Tổ quốc VN XHCN</i>); Coi <b>Nông nghiệp</b> là <i>mặt trận hàng đầu</i>."],"questionIds":["5","7","8","48","49","53","90","145","197","234","280","310","311","312","313","314","315","320","322","324","326","328","329","330","333","334","339","379","383","394","400","404"]},{"id":"tip-11","group":"Thống nhất & Đổi mới","icon":"🚀","title":"Đại hội VI (1986), VII (1991) & VIII (1996) — 10 năm đầu Đổi mới","summary":"Thuộc lòng từ khóa \"đặc sản\" của từng Đại hội VI – VII – VIII để không bao giờ chọn nhầm!","bullets":["<b>Đại hội VI (1986) — Đại hội Đổi mới</b>: TBT <b>Nguyễn Văn Linh</b>; Kinh tế <b>nhiều thành phần</b>, xóa bỏ quan liêu bao cấp; <b>3 chương trình kinh tế lớn</b> (Lương thực-TP, Hàng tiêu dùng, Hàng xuất khẩu); Đổi mới KHÔNG đổi mục tiêu CNXH mà làm mục tiêu <i>thực hiện có hiệu quả</i>; 1986–1991 cơ chế thị trường <b>chưa đầy đủ</b>; HNTW 6 khóa VI (3/1989) lần đầu nêu <b>\"Hệ thống chính trị\"</b>.","<b>Đại hội VII (1991)</b>: Cương lĩnh 1991 có <b>6 đặc trưng</b>; Lần đầu khẳng định <b>CN Mác-Lênin + Tư tưởng Hồ Chí Minh</b> là nền tảng tư tưởng; Đối ngoại: <i>\"Việt Nam <b>muốn là bạn</b>...\"</i>.","<b>Đại hội VIII (1996)</b>: Kết thúc chuẩn bị tiền đề → <b>đẩy mạnh CNH-HĐH</b>; Động lực CNH-HĐH = <b>KH&CN</b>; Tăng trưởng kinh tế gắn công bằng XH <i>trong từng bước và suốt quá trình</i>; HNTW 4 khóa VIII (12/1997) bầu <b>Lê Khả Phiêu</b>."],"questionIds":["12","46","51","52","87","109","127","318b","321","323","335","336","337","338","343","344","350","356","365","373","380","381","384","386","387","388","392","407","409"]},{"id":"tip-12","group":"Thống nhất & Đổi mới","icon":"🌟","title":"Đại hội IX (2001), X (2006), XI (2011), XII (2016) & XIII (2021)","summary":"Mỗi Đại hội gắn với 1–2 dấu ấn riêng biệt cực dễ nhớ — gặp từ khóa là chốt đáp án trong 2 giây!","bullets":["<b>Đại hội IX (2001)</b>: Lần đầu nêu mô hình <b>Kinh tế thị trường định hướng XHCN</b>; Đối ngoại: <i>\"<b>sẵn sàng là bạn, là đối tác tin cậy</b>\"</i>.","<b>Đại hội X (2006)</b>: Cho phép <b>đảng viên làm kinh tế tư nhân</b>; Xây dựng chỉnh đốn Đảng = <i>nhiệm vụ then chốt</i>; Chủ đề: <i>sớm đưa nước ta ra khỏi tình trạng kém phát triển</i>.","<b>Đại hội XI (2011)</b>: Cương lĩnh 2011 bổ sung chữ <b>\"dân chủ\"</b> (<i>Dân giàu, nước mạnh, <b>dân chủ</b>, công bằng, văn minh</i>); Chiến lược 2011–2020: <i>phát triển nhanh gắn với bền vững</i>, chú trọng <b>nguồn nhân lực chất lượng cao</b>.","<b>Đại hội XII (2016)</b>: Lần đầu khẳng định <i>\"lấy lợi ích quốc gia, dân tộc làm mục tiêu cao nhất\"</i>; Khẩu hiệu: <b>Đoàn kết – Dân chủ – Kỷ cương – Đổi mới</b>; Mục tiêu 2020: nước công nghiệp theo hướng hiện đại.","<b>Đại hội XIII (25/1–1/2/2021)</b>: <i>\"Chưa bao giờ có được cơ đồ, tiềm lực, vị thế...\"</i>; <b>3 đột phá chiến lược</b>; Phương châm 6 chữ Dân (<i>biết, bàn, làm, kiểm tra, <b>giám sát, thụ hưởng</b></i>); Mốc: <b>2025</b> (vượt thu nhập trung bình thấp) → <b>2030</b> (thu nhập trung bình cao) → <b>giữa TK XXI / 2045</b> (<b>nước phát triển</b> định hướng XHCN)."],"questionIds":["2","11","34","41","42","128","183","275","296","317","318a","341","346","347","351","352","353","354","355","358","359","362","363","366","375","376","377","395","399","410","411"]},{"id":"tip-13","group":"Nghị quyết & Mẹo chống bẫy","icon":"🌍","title":"Mốc Đối ngoại & Hội nhập Quốc tế (1991–2012)","summary":"Gom tất cả năm hội nhập quốc tế vào 1 dòng timeline — học 10 giây nhớ suốt kỳ thi!","bullets":["<b>1991</b>: <b>23/10/1991</b> Hiệp định Paris về <b>Campuchia</b> (mở tiền đề hội nhập) + <b>10/11/1991</b> Bình thường hóa <b>Việt – Trung</b>.","<b>1995</b>: Cùng năm gia nhập <b>ASEAN</b> VÀ thiết lập ngoại giao với <b>Mỹ</b>!","<b>1998</b>: Gia nhập <b>APEC</b> | <b>11/1/2007</b>: Chính thức vào <b>WTO</b> | <b>2012</b>: <b>36 nước</b> công nhận KTTT của VN.","<b>Mẹo chống nhầm</b>: <b>ĐH VII (1991)</b> = <i>\"muốn là bạn\"</i> ↔ <b>ĐH IX (2001)</b> = <i>\"sẵn sàng là bạn, là đối tác tin cậy\"</i>."],"questionIds":["27","52","59","341","345","346","347","360","361","393","397"]},{"id":"tip-14","group":"Nghị quyết & Mẹo chống bẫy","icon":"📜","title":"Bảng tra nhanh số Nghị quyết TW & Chỉ thị Bộ Chính trị (Khóa VIII–XII)","summary":"Các câu hỏi trích số Nghị quyết/Chỉ thị hay gây \"tẩu hỏa nhập ma\" — gom hết vào bảng ngắn gọn này!","bullets":["<b>Khóa VIII</b>: TW2 (12/1996) = <b>KH&CN + GD&ĐT quốc sách hàng đầu</b> | TW3 (6/1997) = <b>Quyền làm chủ của nhân dân & đội ngũ cán bộ</b> | <b>NQ 03-NQ/TW (TW5, 7/1998)</b> = <b>Tuyên ngôn văn hóa</b>.","<b>Khóa IX</b>: TW5 (3/2002) = <b>KT tập thể & KT tư nhân</b> | TW7 (3/2003) = <b>Đất đai</b> | TW8 (7/2003) = <b>Bảo vệ Tổ quốc</b> | <b>NQ 36 (26/3/2004)</b> = <b>Người VN ở nước ngoài</b>.","<b>Khóa X</b>: <b>NQ 04 (TW3, 8/2006)</b> = <b>Phòng chống tham nhũng, lãng phí</b> | <b>CT 03 (11/2006)</b> = Học tập <i>tấm gương đạo đức HCM</i> | <b>NQ 14 (TW5, 7/2007)</b> = <b>Kiểm tra, giám sát của Đảng</b>.","<b>Khóa XII</b>: <b>CT 05 (15/5/2016)</b> = Học tập <i>tư tưởng, đạo đức, phong cách HCM</i> | TW5 (5/2017) = <b>Thể chế KTTT & KT tư nhân là động lực quan trọng</b> | <b>NQ 20 (10/2017)</b> = <b>Sức khỏe nhân dân</b> | <b>NQ 27 (21/5/2018)</b> = <b>Tiền lương</b> | <b>NQ 28 (23/5/2018)</b> = <b>Bảo hiểm xã hội</b> | <b>NQ 36 (22/10/2018)</b> = <b>Kinh tế biển</b>."],"questionIds":["6","35","40","109","295","348","349","357","364","367","370","371","372","387","389","390","391","396","398","401"]},{"id":"tip-15","group":"Nghị quyết & Mẹo chống bẫy","icon":"💡","title":"Từ khóa \"Chân ái\" về Xây dựng Đảng, Kinh tế & Xã hội thời Đổi mới","summary":"Những cặp khái niệm cố định xuất hiện lặp đi lặp lại trong ngân hàng đề VNR202.","bullets":["Nguyên tắc tổ chức cơ bản của Đảng: <b>Tập trung dân chủ</b> | Xây dựng, chỉnh đốn Đảng = <b>Nhiệm vụ then chốt</b> | Vai trò ĐCSVN = <b>Trụ cột</b>.","<b>Kinh tế nhà nước</b> = giữ vai trò <b>chủ đạo</b> | <b>Kinh tế tư nhân</b> = <b>động lực quan trọng</b> | CNH-HĐH = sự nghiệp của <b>toàn dân</b>.","Yếu tố quyết định tăng trưởng kinh tế & CNH-HĐH = <b>Con người</b> (nguồn lực con người).","Đổi mới kinh tế + chính trị: Lấy <b>đổi mới kinh tế làm trọng tâm</b>, từng bước đổi mới chính trị; kết hợp mục tiêu kinh tế với mục tiêu xã hội.","<b>Mặt trận Tổ quốc & các tổ chức CT-XH</b> = <i>Đại diện quyền và lợi ích hợp pháp của nhân dân</i> | Trả lương đúng = <i>đầu tư cho phát triển</i>."],"questionIds":["43","45","56","181","297","316","325","327","331","332","340","342","369","374","378","382","385","402","403","405","406"]},{"id":"tip-16","group":"Nghị quyết & Mẹo chống bẫy","icon":"⚠️","title":"Cảnh báo Câu Phủ định (KHÔNG / SAI / CHƯA ĐÚNG) & Câu Nhiều đáp án","summary":"Tổng hợp toàn bộ câu \"bẫy phủ định\" dễ đọc lướt mất điểm và 3 câu đặc biệt chọn NHIỀU đáp án!","bullets":["<b>3 câu chọn NHIỀU đáp án</b> trong ngân hàng đề: <b>Câu 20 (A, D)</b>, <b>Câu 36 (A, B)</b>, <b>Câu 115 (B, C)</b>.","Gặp chữ <b>\"KHÔNG\"</b>, <b>\"CHƯA ĐÚNG\"</b>, <b>\"CHƯA PHÙ HỢP\"</b>, <b>\"SAI\"</b> → Dừng lại 2 giây, gạch chân từ phủ định trước khi chọn!","Mẹo nhanh: <i>Câu 1</i> (Đông Dương CS Liên đoàn KHÔNG dự), <i>Câu 66 & 69</i> (Luận cương 10/1930 KHÔNG đặt giải phóng dân tộc lên hàng đầu), <i>Câu 77</i> (HNTW 8 KHÔNG chia ruộng đất), <i>Câu 355</i> (KHÔNG lấy đổi mới chính trị làm thứ yếu)."],"questionIds":["1","20","32","36","66","69","77","85","115","158","204","230","279","355","388"]}]};
